CM.data.topics([{"id":"abbasid-t1","k":"trivia","kj":"こぼれ話","t":"沈没船が語るインド洋の交易","l":"abbasid","x":"1998年、インドネシアのスマトラ島とボルネオ島の間にあるブリトゥン島の沖の海底で、1隻の沈没船が発見された。木の板をココヤシの繊維のひもで縫い合わせて造られた、アラブ・ペルシア系"},{"id":"abbasid-t2","k":"source","kj":"史料","t":"9世紀のアラブ商人が見た中国","l":"abbasid","x":"9世紀半ばにまとめられた『中国とインドの諸情報』は、ペルシア湾から中国まで航海した商人たちの見聞を記録した書物である。そこには、中国の港の様子が、次のように記されている。広府（広州"},{"id":"abbasid-t3","k":"source","kj":"史料","t":"ユダヤ人の国際商人ラーザーニーヤ","l":"abbasid","x":"9世紀のアッバース朝の駅伝の長官イブン・フルダーズベは、『諸道と諸国の書』の中で、「ラーザーニーヤ」と呼ばれるユダヤ人の商人たちについて、次のように記している。彼らは、アラビア語、"},{"id":"abbasid-t4","k":"person","kj":"人物","t":"ズバイダ――巡礼者のための道","l":"abbasid","x":"ハールーンの妻ズバイダは、マンスールの孫娘で、莫大な富を持っていた。伝承によれば、彼女の食卓には金と銀の器しか並ばず、宝石で飾った靴をはいたという。一方で、ズバイダは、メッカへの巡"},{"id":"abbasid-t5","k":"now","kj":"いま","t":"バグダードの現在","l":"abbasid","x":"バグダードは、現在、イラク共和国の首都であり、人口は800万人を超える。しかし、マンスールの円城の跡は、現在の市街地の下に完全に埋もれ、地上には何も残っていない。1258年、モンゴ"},{"id":"abbasid-t6","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"abbasid","x":"『千夜一夜物語』（アラビアン・ナイト）：ハールーン・アッラシードや宰相ジャアファル（バルマク家）が登場する物語が多く含まれる。日本語訳には、前嶋信次・池田修訳（平凡社東洋文庫、アラ"},{"id":"achaemenid-t1","k":"myth","kj":"俗説","t":"キュロスの円筒碑文は「最初の人権宣言」か","l":"achaemenid","x":"1879年、バビロンの遺跡で、楔形文字のアッカド語がびっしり刻まれた樽の形の粘土製品が発見された。キュロス2世がバビロンを征服したときのことを記した「キュロス＝シリンダー（キュロス"},{"id":"achaemenid-t2","k":"debate","kj":"諸説あり","t":"ダレイオス1世の即位の謎","l":"achaemenid","x":"ダレイオス1世は、即位の事情をイラン西部のベヒストゥーンの崖に刻ませた碑文で、次のように説明している。カンビュセスは弟のバルディヤをひそかに殺していた。カンビュセスが遠征中に、ガウ"},{"id":"achaemenid-t3","k":"confuse","kj":"混同注意","t":"サトラップと「属州総督」","l":"achaemenid","x":"アケメネス朝のサトラップは、ローマの属州総督や中国の郡県制の役人とよく比べられる。いずれも中央から地方に派遣された支配者だが、違いもある。サトラップ：主にペルシア人の貴族が任命され"},{"id":"achaemenid-t4","k":"source","kj":"史料","t":"「雪も雨も」――ヘロドトスの記録","l":"achaemenid","x":"この世に、ペルシアの急使より速く進むものはない。……道のりの日数と同じ数の馬と人が、途中に配置されている。一日の道のりごとに、馬一頭と人一人がいるのである。雪も雨も、暑さも夜の闇も"},{"id":"achaemenid-t5","k":"trivia","kj":"こぼれ話","t":"ベヒストゥーン碑文と楔形文字の解読","l":"achaemenid","x":"ベヒストゥーン碑文は、イラン西部の交通路沿いの崖の、地上から約60mの高さに刻まれている。同じ内容が、古代ペルシア語・エラム語・アッカド語（バビロニア語）の3つの言語で、いずれも楔"},{"id":"achaemenid-t6","k":"life","kj":"暮らし","t":"粘土板が語る労働者たち――産休手当もあった","l":"achaemenid","x":"1933〜34年、ペルセポリスの城壁の中から、数万枚の小さな粘土板が見つかった。エラム語で書かれた、宮殿の建設や運営にかかわる物資の支給の記録である（ペルセポリス城砦文書）。この記"},{"id":"achaemenid-t7","k":"now","kj":"いま","t":"アメリカの裁判に巻き込まれた粘土板","l":"achaemenid","x":"ペルセポリス城砦文書は、研究のために1930年代にアメリカのシカゴ大学に貸し出され、その一部が現在も研究されている。2000年代に入り、イランが支援したとされるテロの被害者たちが、"},{"id":"achaemenid-t8","k":"view","kj":"視点を変える","t":"ゾロアスター教の遺したもの","l":"achaemenid","x":"「最後の審判」「天使と悪魔」「天国と地獄」「救世主の到来」――こうした考え方は、ユダヤ教・キリスト教・イスラームにも見られる。これらの考え方の一部は、バビロン捕囚から解放されたユダ"},{"id":"achaemenid-t9","k":"confuse","kj":"混同注意","t":"アケメネス朝とササン朝","l":"achaemenid","x":"どちらもイラン（ペルシア）人の帝国なので、混同しやすい。アケメネス朝ササン朝時代前550〜前330年後224〜651年建国キュロス2世（メディアを倒す）アルダシール1世（パルティア"},{"id":"aegean-t1","k":"confuse","kj":"混同注意","t":"クレタ文明とミケーネ文明","l":"aegean","x":"クレタ文明（ミノア文明）ミケーネ文明時期前2000〜前1400年ごろ前1600〜前1200年ごろ中心クレタ島（クノッソス）ギリシア本土（ミケーネ・ティリンス・ピュロス）担い手民族系"},{"id":"aegean-t2","k":"myth","kj":"俗説","t":"迷宮ラビュリントスとミノタウロス","l":"aegean","x":"ギリシア神話によれば、クレタ島の王ミノスは、牛の頭と人の体をもつ怪物ミノタウロスを、名工ダイダロスに造らせた迷宮（ラビュリントス）に閉じ込め、アテネから毎年少年少女を貢ぎ物として送"},{"id":"aegean-t3","k":"trivia","kj":"こぼれ話","t":"牛跳びの競技","l":"aegean","x":"クノッソスの壁画で最も有名なのが、「牛跳び」の場面である。突進してくる牛の角をつかんで、その背の上で宙返りし、後ろに降り立つ若者たちが描かれている。祭りの儀式として行われた競技と考"},{"id":"aegean-t4","k":"now","kj":"いま","t":"「復元」された宮殿","l":"aegean","x":"現在、クノッソスを訪れた人が見る宮殿の赤い柱や、色鮮やかな壁画の多くは、発掘者エヴァンズが20世紀前半に、鉄筋コンクリートを使って「復元」したものである。エヴァンズは、崩れかけた遺"},{"id":"aegean-t5","k":"debate","kj":"諸説あり","t":"テラ島の噴火とアトランティス","l":"aegean","x":"前17世紀ごろ（年代には諸説）、クレタの北約100kmにあるテラ島（現在のサントリーニ島）で、人類の歴史の上でも最大級の火山の噴火が起こった。島の中央部は吹き飛び、海に沈んで、現在"},{"id":"aegean-t6","k":"myth","kj":"俗説","t":"「アガメムノンの顔を見た」","l":"aegean","x":"1876年、シュリーマンはミケーネの城門の内側にある円形の墓域で、黄金のマスクをつけた遺体を発見した。彼は、ギリシア王に「私は今日、アガメムノンの顔を見ました」という電報を送ったと"},{"id":"aegean-t7","k":"debate","kj":"諸説あり","t":"トロイア戦争の史実性","l":"aegean","x":"小アジア北西部のトロイア（現在のトルコのヒサルルク）の遺跡には、前3000年ごろから後の時代まで、9層以上にわたって都市が重なっている。シュリーマンは、黄金の財宝が出た第2層をホメ"},{"id":"aegean-t8","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"aegean","x":"ホメロス『イリアス』『オデュッセイア』：トロイア戦争の伝説を歌った叙事詩そのものが、今も読み継がれる「作品」である。映画『トロイ』（2004年）：『イリアス』をもとにした映画。神々"},{"id":"aksum-t1","k":"source","kj":"史料","t":"マニの「四つの王国」","l":"aksum","x":"地上には四つの大王国がある。第一はバビロンとペルシアの王国、第二はローマの王国、第三はアクスム人の王国、第四は中国人の王国である。出典：『ケファライア』第77章（マニ教の教説集、コ"},{"id":"aksum-t2","k":"source","kj":"史料","t":"『エリュトゥラー海案内記』に描かれたアドゥリスとアクスム","l":"aksum","x":"アドゥリスから、アクソーミタイ（アクスム人）と呼ばれる人々の町までは、さらに5日の行程である。ナイル川の向こうの地から産するすべての象牙が、その町に運ばれ、そこからアドゥリスへと運"},{"id":"aksum-t3","k":"life","kj":"暮らし","t":"奴隷から司教へ――フルメンティオスの物語","l":"aksum","x":"ルフィヌスの『教会史』によれば、4世紀の初め、ティルス（現在のレバノン）の哲学者メロピオスが、二人の少年フルメンティオスとアエデシオスを連れて、紅海を船で旅していた。船が水と食料を"},{"id":"aksum-t4","k":"source","kj":"史料","t":"エザナ王の碑文（キリスト教改宗後）","l":"aksum","x":"天と地においてすべてのものを支配する天の主の力によって……主の力と、主の子である勝利者イエス・キリストの恵みによって――わたしはこの方を信じる――……出典：エザナ王の碑文（アクスム"},{"id":"aksum-t5","k":"trivia","kj":"こぼれ話","t":"ローマ皇帝からの手紙","l":"aksum","x":"アクスムのキリスト教は、すぐにローマ帝国の教会の争いに巻き込まれた。356年ごろ、ローマ皇帝コンスタンティウス2世は、アクスムの王「アイザナスとサザナス」（エザナとその兄弟）に手紙"},{"id":"aksum-t6","k":"debate","kj":"諸説あり","t":"アクスムはメロエを滅ぼしたのか","l":"aksum","x":"教科書では、「アクスム王国が4世紀にメロエ王国を滅ぼした」と書かれることが多い。たしかに、エザナ王の碑文には、ナイル川流域への遠征が記され、メロエ遺跡からはアクスムの王の碑文の断片"},{"id":"aksum-t7","k":"now","kj":"いま","t":"ローマから帰ってきた石碑","l":"aksum","x":"1937年、エチオピアを侵略・占領したイタリアのムッソリーニ政権は、倒れていたアクスムの第2石碑（高さ約24m）を戦利品としてローマへ運び、ローマ進軍15周年を記念して、市内に建て"},{"id":"aksum-t8","k":"myth","kj":"俗説","t":"契約の箱はアクスムにあるのか","l":"aksum","x":"アクスムには、エチオピア正教会で最も神聖な教会の一つ、シオンの聖マリア教会がある。エチオピアの人々の間では、この教会の敷地内の礼拝堂に、古代イスラエルの「契約の箱」（モーセの十戒を"},{"id":"aksum-t9","k":"trivia","kj":"こぼれ話","t":"ムスリムを守った王","l":"aksum","x":"610年ごろ、メッカでムハンマドが教えを説き始めると、メッカの有力者たちは、信者たちを迫害した。615年ごろ、ムハンマドは、一部の信者に、紅海の対岸のアクスムへ逃れるよう勧めたとい"},{"id":"aksum-t10","k":"now","kj":"いま","t":"古都アクスムと現代の紛争","l":"aksum","x":"アクスムは、現在のエチオピア北部のティグライ州にある。この地域は、1993年に独立したエリトリアとの国境に近く、1998〜2000年のエチオピア・エリトリア国境紛争では、両国あわせ"},{"id":"aksum-t11","k":"works","kj":"作品紹介","t":"アクスムとエチオピアにまつわる作品","l":"aksum","x":"『ケブラ・ナガスト』（14世紀）：シバの女王とソロモン王の子メネリクが、契約の箱をエチオピアにもたらしたという物語を中心とする、エチオピアの書物。エチオピアの王家の正統性を語る「建"},{"id":"alexander-t1","k":"trivia","kj":"こぼれ話","t":"暴れ馬ブケファラス","l":"alexander","x":"アレクサンドロスがまだ少年だったころ、テッサリアから一頭の見事な馬が売りに出された。しかし、この馬はひどく暴れて、誰も乗りこなすことができなかった。フィリッポス2世が買うのをあきら"},{"id":"alexander-t2","k":"myth","kj":"俗説","t":"ゴルディオンの結び目","l":"alexander","x":"小アジア中部の町ゴルディオンには、昔の王の戦車が、複雑な結び目で縛りつけられていた。「この結び目を解いた者が、アジアの王になる」という言い伝えがあった。前333年、この町を訪れたア"},{"id":"alexander-t3","k":"person","kj":"人物","t":"捕らえられたペルシアの王母","l":"alexander","x":"イッソスの戦いで、ダレイオス3世は母のシシュガンビス、妃、子どもたちを陣営に残したまま逃走した。捕虜となった王の家族を、アレクサンドロスは王族にふさわしく丁重に扱った。ある逸話によ"},{"id":"alexander-t4","k":"source","kj":"史料","t":"兵士たちの拒否","l":"alexander","x":"アレクサンドロスは、さらに東のガンジス川流域へ進もうとした。しかし、ヒュファシス川（現在のビアス川）のほとりで、8年にわたって故郷を離れて戦い続けてきた兵士たちが、ついに進軍を拒ん"},{"id":"alexander-t5","k":"view","kj":"視点を変える","t":"英雄か、破壊者か――イランから見たアレクサンドロス","l":"alexander","x":"ギリシアやヨーロッパでは、アレクサンドロスは東西の文化を結びつけた英雄として語られてきた。しかし、征服された側から見た姿は異なる。ササン朝時代のイランのゾロアスター教の文献では、ア"},{"id":"alexander-t6","k":"confuse","kj":"混同注意","t":"アレクサンドロスの帝国とアケメネス朝","l":"alexander","x":"アレクサンドロスの帝国の範囲は、ほぼアケメネス朝ペルシアの領土をそのまま引き継いだものだった。ギリシアとマケドニアを加え、アラビア半島や黒海北岸などは含まない。アケメネス朝（最大領"},{"id":"alexander-t7","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"alexander","x":"岩明均『ヒストリエ』（漫画、2003年〜連載）：アレクサンドロス大王の書記官で、のちに後継者戦争を戦ったエウメネスの生涯を描く。少年時代のエウメネスの放浪から、マケドニアの宮廷での"},{"id":"americas-oceania-peopling-t1","k":"debate","kj":"諸説あり","t":"2万3000年前の足跡？――ホワイトサンズ","l":"americas-oceania-peopling","x":"2021年、アメリカのニューメキシコ州ホワイトサンズで、かつての湖のほとりの地層に残された人間の足跡が、約2万3000〜2万1000年前のものだと発表された。最終氷期の最盛期のころ"},{"id":"americas-oceania-peopling-t2","k":"confuse","kj":"混同注意","t":"「インディアン」「インディオ」という呼び名","l":"americas-oceania-peopling","x":"アメリカ大陸の先住民は、長く「インディアン」（英語）や「インディオ」（スペイン語）と呼ばれてきた。これは、1492年にカリブ海の島に着いたコロンブスが、そこをインドの一部だと思い込"},{"id":"americas-oceania-peopling-t3","k":"life","kj":"暮らし","t":"星と波を読む航海術","l":"americas-oceania-peopling","x":"ポリネシアの人々は、羅針盤も海図も持たずに、何千キロメートルもの大洋を渡った。使ったのは、2つの船体を板でつないだ大型の双胴カヌーである。人々や食料、豚や鶏、犬、タロイモやヤムイモ"},{"id":"americas-oceania-peopling-t4","k":"debate","kj":"諸説あり","t":"ポリネシア人はアメリカ大陸に到達していた？","l":"americas-oceania-peopling","x":"南アメリカ原産のサツマイモは、ヨーロッパ人が来るより前から、ポリネシアの島々で栽培されていた。しかもポリネシアの言葉でサツマイモを指す「クマラ」は、南アメリカのケチュア語の「クマル"},{"id":"americas-oceania-peopling-t5","k":"debate","kj":"諸説あり","t":"イースター島の「文明崩壊」は本当か","l":"americas-oceania-peopling","x":"イースター島（ラパ・ヌイ）は、巨大な石像モアイで知られる。かつては、島民がモアイを運ぶために森の木をすべて切り倒してしまい、その結果、資源が尽きて争いが起き、人口が激減して社会が崩"},{"id":"americas-oceania-peopling-t6","k":"trivia","kj":"こぼれ話","t":"巨鳥モアの絶滅","l":"americas-oceania-peopling","x":"ニュージーランドには、かつてモアと呼ばれる飛べない巨大な鳥がいた。最大の種は、首を伸ばすと高さ3.6メートル、体重は200キログラムを超えた。ニュージーランドにはもともと陸上の哺乳"},{"id":"americas-oceania-peopling-t7","k":"trivia","kj":"こぼれ話","t":"コロンブスより500年前にアメリカに来た人々","l":"americas-oceania-peopling","x":"アメリカ大陸に最初に来たヨーロッパ人は、コロンブスではない。11世紀初め、ノルウェー系のヴァイキング（ノルマン人）が、グリーンランドからさらに西へ航海し、北アメリカに到達していた。"},{"id":"an-shi-t1","k":"source","kj":"史料","t":"杜甫「憶昔」――開元の全盛の日","l":"an-shi","x":"のちに安史の乱を経験した詩人の杜甫は、開元の時代をこう振り返っている。憶う昔、開元全盛の日 小邑すら猶お蔵す万家の室稲米は脂を流し粟米は白く 公私の倉廩倶に豊実なり九州の道路に豺虎"},{"id":"an-shi-t2","k":"trivia","kj":"こぼれ話","t":"早馬で運ばれたライチ","l":"an-shi","x":"楊貴妃は、南方の果物ライチ（茘枝）を好んだ。ライチは、摘み取ってから数日で色も香りも失われてしまう。そこで、南方の産地から長安まで、早馬を乗り継いで、鮮度を保ったまま運ばせたという"},{"id":"an-shi-t3","k":"source","kj":"史料","t":"杜甫「春望」","l":"an-shi","x":"反乱軍に占領された長安に捕らわれていた杜甫は、757年の春、荒れ果てた都の姿を見て、こう詠んだ。国破れて山河在り 城春にして草木深し時に感じては花にも涙を濺ぎ 別れを恨んでは鳥にも"},{"id":"an-shi-t4","k":"confuse","kj":"混同注意","t":"租庸調制と両税法","l":"an-shi","x":"租庸調制両税法（780年〜）前提均田制で土地を与えられた成年男子（丁男）実際に住んでいる土地の戸（本籍地に関係なく）課税の基準人（丁男）ごとに一律戸の資産と土地の広さに応じて納める"},{"id":"an-shi-t5","k":"trivia","kj":"こぼれ話","t":"円仁が見た会昌の廃仏","l":"an-shi","x":"9世紀の唐では、仏教寺院が莫大な土地と財産を持ち、多くの人々が税や兵役を逃れるために僧となっていた。845年、道教を信じる武宗は、大規模な仏教弾圧を行い、4600余りの寺院を破壊し"},{"id":"an-shi-t6","k":"debate","kj":"諸説あり","t":"広州の外国人の虐殺","l":"an-shi","x":"10世紀のアラブの著述家アブー・ザイドは、黄巣の軍が広州を攻め落としたとき、そこに住んでいたムスリム・ユダヤ教徒・キリスト教徒・ゾロアスター教徒の外国人12万人が殺されたと記してい"},{"id":"an-shi-t7","k":"source","kj":"史料","t":"黄巣「菊を賦す」","l":"an-shi","x":"黄巣は、科挙に落第した後、次のような詩を作ったと伝えられる伝承。待ち到る秋来たりて九月八日 我が花開くの後、百花殺す衝天の香陣、長安に透り 満城尽く帯ぶ黄金の甲（秋になって9月8日"},{"id":"an-shi-t8","k":"works","kj":"作品紹介","t":"この時代にまつわる作品","l":"an-shi","x":"白居易「長恨歌」（806年）：玄宗と楊貴妃の悲恋を歌った長編詩。日本では平安時代に広く愛読され、『源氏物語』の冒頭の「桐壺」の巻は、その影響を強く受けている。陳鴻「長恨歌伝」：「長"},{"id":"andes-early-t1","k":"trivia","kj":"こぼれ話","t":"細長い頭と頭蓋骨の手術","l":"andes-early","x":"パラカスの墓から見つかった人骨には、頭蓋骨が後ろに細長く伸びたものが多い。これは、赤ん坊のうちに頭を板や布で締めつけて、意図的に形を変えたものである。頭の形は、どの集団に属するかを"},{"id":"andes-early-t2","k":"myth","kj":"俗説","t":"宇宙人が描いた？","l":"andes-early","x":"上空からでないと全体が見えないことから、地上絵は、宇宙人の宇宙船の滑走路や目印として描かれたのだという説が、1960年代末に出版されて話題を呼んだ。しかし、これは根拠のない俗説であ"},{"id":"andes-early-t3","k":"person","kj":"人物","t":"マリア・ライヘ――地上絵に生涯をささげた人","l":"andes-early","x":"ドイツ生まれの数学者マリア・ライヘ（1903〜1998年）は、1940年代から半世紀以上にわたって、ナスカの砂漠に住み込み、地上絵の測量と研究を続けた。彼女は、ほうきで地上絵の線を"},{"id":"andes-early-t4","k":"trivia","kj":"こぼれ話","t":"入れ墨の女王","l":"andes-early","x":"2006年、モチェ川の北のエル・ブルホ遺跡で、4〜5世紀ごろの女性のミイラが発見された。腕や足には、ヘビやクモなどの入れ墨が残っており、「カオの貴婦人」と呼ばれている。彼女は、王冠"},{"id":"andes-early-t5","k":"now","kj":"いま","t":"盗掘と開発に脅かされる遺跡","l":"andes-early","x":"シパン王墓の発見のきっかけが盗掘であったように、アンデスの遺跡は、長い間、盗掘に苦しめられてきた。ペルーでは、遺跡を掘って副葬品を売る者を「ワケーロ」と呼ぶ。スペインの植民地時代に"},{"id":"andes-early-t6","k":"works","kj":"作品紹介","t":"アンデスの古代文明にまつわる作品","l":"andes-early","x":"エーリッヒ・フォン・デニケン『未来の記憶』（1968年）：ナスカの地上絵などの古代の遺跡を、宇宙人が地球を訪れた証拠だと主張して、世界的なベストセラーとなった本。本編で見たように、"},{"id":"arab-conquests-t1","k":"myth","kj":"俗説","t":"ウマルの礼拝","l":"arab-conquests","x":"伝承によれば、ソフロニオスは、ウマルを、イエスの墓の上に建つとされる聖墳墓教会に案内した。礼拝の時刻になると、ソフロニオスは、教会の中で礼拝するよう勧めた。しかしウマルは、それを断"},{"id":"arab-conquests-t2","k":"trivia","kj":"こぼれ話","t":"切り刻まれた「ホスローの春」","l":"arab-conquests","x":"637年、アラブ軍がササン朝の首都クテシフォンを占領した時、宮殿からは、想像を絶する財宝が見つかった。その中に、「ホスローの春」と呼ばれる巨大な絨毯があったと伝えられる。伝承によれ"},{"id":"arab-conquests-t3","k":"myth","kj":"俗説","t":"アレクサンドリア図書館を焼いたのは誰か","l":"arab-conquests","x":"アラブ軍がアレクサンドリアを占領した時、カリフのウマルの命令で、アレクサンドリアの図書館の書物が焼かれたという話がある。伝説によれば、ウマルは、「もし書物が『クルアーン』と同じこと"},{"id":"arab-conquests-t4","k":"debate","kj":"諸説あり","t":"征服された人々は、アラブ軍を歓迎したのか","l":"arab-conquests","x":"シリアやエジプトの住民の多くは、ビザンツ帝国の正統の教義とは異なる、キリストの神性だけを認める「単性論」の教えを信じるキリスト教徒であった。彼らは、ビザンツ帝国から異端として弾圧さ"},{"id":"arab-conquests-t5","k":"myth","kj":"俗説","t":"血に染まった『クルアーン』","l":"arab-conquests","x":"伝承によれば、反乱者たちが家に押し入った時、80歳を超えていたウスマーンは、『クルアーン』を読んでいた。ウスマーンは、その場で殺され、その血が『クルアーン』のページに飛び散ったとい"},{"id":"arab-conquests-t6","k":"source","kj":"史料","t":"槍の先の『クルアーン』","l":"arab-conquests","x":"戦いは数か月にわたって続き、アリーの軍が優勢になった。追い詰められたムアーウィヤの軍は、知恵者のアムル・イブン・アル＝アース（エジプトの征服者）の策に従って、兵士たちの槍の先に、『"},{"id":"arab-conquests-t7","k":"now","kj":"いま","t":"現代に続く「最初の内乱」","l":"arab-conquests","x":"アリーとムアーウィヤの争いから始まったスンナ派とシーア派の分裂は、1300年以上たった現代の中東の政治にも、大きな影を落としている。シーア派の多いイランと、スンナ派の多いサウジアラ"},{"id":"arab-conquests-t8","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"arab-conquests","x":"バラーズリー『諸国征服史』（花田宇秋訳、岩波書店、全3巻）：9世紀のアラブの歴史家による、アラブの大征服の記録の日本語訳。テレビドラマ『オマル』（Omar）（2012年、MBC・カ"},{"id":"assyria-t1","k":"life","kj":"暮らし","t":"2万通の手紙が語る商人の家族","l":"assyria","x":"キュルテペの遺跡からは、アッシュルの商人たちが残した約2万3000枚の粘土板が見つかっている。その多くが、アナトリアの商人と、アッシュルにいる家族とのあいだでやりとりされた手紙や、"},{"id":"assyria-t2","k":"view","kj":"視点を変える","t":"浮き彫りは「宣伝」だった","l":"assyria","x":"アッシリアの王宮の壁は、戦争の場面を描いた浮き彫りで埋め尽くされていた。そこには、攻め落とした町の住民を串刺しにしたり、生きたまま皮をはいだりする、目をそむけたくなるような場面も含"},{"id":"assyria-t3","k":"confuse","kj":"混同注意","t":"「アッシリア」と「シリア」","l":"assyria","x":"名前がよく似ているので混同しないようにしたい。アッシリアは、メソポタミア北部（現在のイラク北部）を本拠地とした国である。一方、シリアは、地中海の東岸、現在のシリア・レバノン・イスラ"},{"id":"assyria-t4","k":"source","kj":"史料","t":"文字を読む王","l":"assyria","x":"アッシリアの王の多くは、自ら文字を読み書きしなかったと考えられている。しかし、アッシュルバニパルは、自分が文字を学んだことを誇りにしていた。私は、賢者アダパの技（書記の技）を学んだ"},{"id":"assyria-t5","k":"trivia","kj":"こぼれ話","t":"大洪水の物語を見つけた男","l":"assyria","x":"ニネヴェの遺跡は、19世紀半ばにイギリスのレヤードらによって発掘され、図書館の粘土板はロンドンの大英博物館に運ばれた。1872年、大英博物館で粘土板の整理をしていたジョージ＝スミス"},{"id":"assyria-t6","k":"source","kj":"史料","t":"「流血の町は災いだ」","l":"assyria","x":"アッシリアに苦しめられたユダ王国の預言者ナホムは、ニネヴェの滅亡を、喜びをもって歌っている。災いだ、流血の町は。すべて偽りに満ち、略奪にあふれ、獲物を奪うことをやめない。……あなた"},{"id":"assyria-t7","k":"now","kj":"いま","t":"破壊された遺跡、生き続ける人々","l":"assyria","x":"2014年、イラク北部のモスルを制圧した過激派組織「イスラム国（IS）」は、2015年に、モスル博物館の像を打ち壊す映像を公開し、さらにアッシリアの都カルフ（ニムルド）の遺跡を爆破"},{"id":"athenian-democracy-t1","k":"source","kj":"史料","t":"ソロンの詩――「黒い大地を自由にした」","l":"athenian-democracy","x":"ソロンは、自らの改革を詩に詠んでいる。黒い大地は、私の証人となるであろう。かつては奴隷の身だったこの大地から、私は、あちこちに打ち込まれていた境界の石（借金の証）を取り除き、自由に"},{"id":"athenian-democracy-t2","k":"confuse","kj":"混同注意","t":"財産政治の4等級","l":"athenian-democracy","x":"等級年収（穀物などの量）参政権兵役五百メディムノス級500メディムノス以上アルコンなど最高の役職に就ける騎兵・三段櫂船の艤装騎士級300以上アルコンに就ける（のちに）騎兵農民級（ゼ"},{"id":"athenian-democracy-t3","k":"confuse","kj":"混同注意","t":"僭主は「暴君」ではない","l":"athenian-democracy","x":"「僭主」の原語「テュランノス」は、英語の「タイラント（tyrant、暴君）」の語源である。しかし、古代ギリシアの僭主は、必ずしも暴君ではなかった。「僭主」とは、王の家柄でもなく、正"},{"id":"athenian-democracy-t4","k":"trivia","kj":"こぼれ話","t":"僭主殺しの像","l":"athenian-democracy","x":"前514年、ヒッピアスの弟ヒッパルコスを暗殺したのは、ハルモディオスとアリストゲイトンという二人の若者であった。動機は政治的なものではなく、ヒッパルコスがハルモディオスに言い寄って"},{"id":"athenian-democracy-t5","k":"source","kj":"史料","t":"字の書けない市民とアリステイデス","l":"athenian-democracy","x":"陶片追放には、次のような逸話が伝えられている。前482年の陶片追放のとき、字の書けない一人の農民が、近くにいた男に陶片を渡し、「アリステイデス」と書いてくれと頼んだ。男が「アリステ"},{"id":"athenian-democracy-t6","k":"now","kj":"いま","t":"陶片は今も残っている","l":"athenian-democracy","x":"陶片追放の投票に使われた陶片（オストラコン）は、アテネのアゴラやケラメイコス地区の発掘で、これまでに1万枚以上見つかっている。そこには、テミストクレス、アリステイデス、ペリクレス、"},{"id":"athenian-democracy-t7","k":"confuse","kj":"混同注意","t":"「陶片追放」の名前と目的","l":"athenian-democracy","x":"陶片追放は「貝殻追放」と訳されることもあるが、実際に使われたのは貝殻ではなく、割れた陶器のかけらである（ギリシア語の「オストラコン」には貝殻の意味もあったため、誤訳が広まった）。ま"},{"id":"athens-sparta-t1","k":"confuse","kj":"混同注意","t":"ヘイロータイ・ペリオイコイ・奴隷","l":"athens-sparta","x":"ヘイロータイ：スパルタの国家が所有する隷属農民。個人の市民が売買することはできず、家族をもち、土地に縛りつけられていた。農奴に近い存在である。ペリオイコイ：スパルタの周辺に住む自由"},{"id":"athens-sparta-t2","k":"life","kj":"暮らし","t":"スパルタの少年の一生","l":"athens-sparta","x":"プルタルコスの『リュクルゴス伝』などによれば、スパルタの男子の一生は次のようだった伝承。生まれると、長老たちが赤ん坊を調べ、弱々しい子は山中の谷間に捨てられたという（ただし、これを"},{"id":"athens-sparta-t3","k":"trivia","kj":"こぼれ話","t":"「もしも」――ラコニア式の簡潔さ","l":"athens-sparta","x":"スパルタ人は無駄な言葉を嫌い、短く鋭い言い回しを好んだ。スパルタのあるラコニア地方の名から、英語で簡潔な物言いを「ラコニック（laconic）」という。伝えられるところでは、のちに"},{"id":"athens-sparta-t4","k":"view","kj":"視点を変える","t":"スパルタは本当に「軍国主義の理想郷」だったか","l":"athens-sparta","x":"スパルタの制度は、のちの時代にくり返し理想化された。プラトンは理想国家の構想にスパルタを参考にし、近代ヨーロッパでも、スパルタの質実剛健さや愛国心はたたえられた。20世紀には、ナチ"},{"id":"black-death-t1","k":"confuse","kj":"混同注意","t":"「黒死病」と呼んだのは後の時代の人々","l":"black-death","x":"当時の人々はこの病気を「黒死病」とは呼んでいない。ヨーロッパの記録では「大いなる死」「疫病」「悪疫」などと書かれた。「黒死病」という呼び名が定着するのは、16〜17世紀以降のことで"},{"id":"black-death-t2","k":"term","kj":"用語","t":"ペストの三つのかたち","l":"black-death","x":"ペストには主に三つの病型がある。腺ペスト：ノミに刺されたところから菌が入り、近くのリンパ節が鶏卵ほどに腫れ上がる。わきの下や足の付け根の腫れが特徴で、当時の記録にもくり返し出てくる"},{"id":"black-death-t3","k":"source","kj":"史料","t":"死体を投げ込んだ？――ガブリエーレ・デ・ムッシの記録","l":"black-death","x":"イタリアのピアチェンツァの公証人ガブリエーレ・デ・ムッシは、この包囲の様子を次のように書いている。「タタール人の軍勢は病に打ちのめされ、日ごとに何千人もが死んでいった。……彼らは死"},{"id":"black-death-t4","k":"source","kj":"史料","t":"『デカメロン』序文――家族が家族を見捨てた","l":"black-death","x":"che l'uno fratello l'altro abbandonava e il zio il nipote e la sorella il fratello e spess"},{"id":"black-death-t5","k":"source","kj":"史料","t":"「私は5人の子を自分の手で埋めた」――シエナの年代記","l":"black-death","x":"フィレンツェの南の町シエナでは、靴職人で徴税人でもあったアーニョロ・ディ・トゥーラが、町の年代記を書いていた。1348年の項で、彼は流行のありさまを記したあと、ふいに自分のことを書"},{"id":"black-death-t6","k":"trivia","kj":"こぼれ話","t":"ペトラルカとラウラ","l":"black-death","x":"イタリアの詩人ペトラルカは、若いころに見初めた女性ラウラへの愛を、生涯にわたって詩に歌い続けた。そのラウラは、1348年4月6日、アヴィニョンで亡くなった。ペストだったと考えられて"},{"id":"black-death-t7","k":"view","kj":"視点を変える","t":"大旅行家イブン＝バットゥータが見たダマスクス","l":"black-death","x":"モロッコ出身の旅行家イブン＝バットゥータは、1348年、旅の帰り道でダマスクスに立ち寄り、ペストの流行に出会った。彼によれば、町の人々は3日間の断食を行い、そのあと、ムスリムもユダ"},{"id":"black-death-t8","k":"debate","kj":"諸説あり","t":"病気は「うつる」のか――イスラームの学者たちの論争","l":"black-death","x":"イスラーム世界では、預言者ムハンマドの言葉として「伝染というものはない」とする伝承があり、病気は神の定めによるものだとする考え方が有力だった。これに対して、グラナダの医師で政治家で"},{"id":"black-death-t9","k":"trivia","kj":"こぼれ話","t":"王女の死と教皇の「火」","l":"black-death","x":"1348年、イングランド王エドワード3世の娘ジョーンは、カスティリャの王子との結婚のためスペインへ向かう途中、フランスのボルドーでペストにかかって亡くなった。王家の人間も逃れられな"},{"id":"black-death-t10","k":"life","kj":"暮らし","t":"当時の人々は原因をどう考えたか","l":"black-death","x":"1348年、パリ大学の医学部はフランス王の求めに応じて、流行の原因についての報告書をまとめた。それによれば、1345年3月に土星・木星・火星が水瓶座で会合したことで大気が汚れ、その"},{"id":"black-death-t11","k":"source","kj":"史料","t":"ストラスブールの虐殺","l":"black-death","x":"1349年2月14日、ドイツ南西部のストラスブールでは、町の参事会がユダヤ人を捕らえ、ユダヤ人墓地に作った木の小屋に閉じ込めて火を放った。この町の年代記作者ケーニヒスホーフェンは、"},{"id":"black-death-t12","k":"trivia","kj":"こぼれ話","t":"「死の舞踏」","l":"black-death","x":"黒死病のあと、ヨーロッパの教会や墓地の壁には、骸骨の姿をした「死」が、教皇や皇帝、騎士、商人、農民、子どもの手を取って踊る絵が描かれるようになった。「死の舞踏」である。身分の高い者"},{"id":"black-death-t13","k":"myth","kj":"俗説","t":"くちばしのマスクの医者は14世紀にはいなかった","l":"black-death","x":"ペストというと、鳥のくちばしのようなマスクをつけ、長いコートを着た医者の姿がよく描かれる。しかし、この服装は17世紀のフランスやイタリアで考案されたもので、14世紀の黒死病の時代に"},{"id":"black-death-t14","k":"debate","kj":"諸説あり","t":"ネズミのせいか、人のせいか","l":"black-death","x":"ペストは、クマネズミについたノミが人を刺すことで広がる、と長く説明されてきた。しかし、14世紀の流行の速さや、北欧のようにネズミの少ない地域でも大流行したことを、ネズミとノミだけで"},{"id":"black-death-t15","k":"trivia","kj":"こぼれ話","t":"「検疫」の始まり","l":"black-death","x":"感染症の流行地から来た船や人を一定期間とどめておく「検疫」の制度は、黒死病の後にイタリアやアドリア海の港町で始まった。1377年、ドゥブロヴニク（当時のラグーザ）は、流行地から来た"},{"id":"black-death-t16","k":"now","kj":"いま","t":"歴史の中の感染症と現代","l":"black-death","x":"2020年からの新型コロナウイルス感染症の世界的な流行のなかで、黒死病の時代の記録は改めて注目された。外出を控える人と出歩く人、流行を特定の集団のせいにしようとする動き、人手不足と"},{"id":"byzantine-society-t1","k":"confuse","kj":"混同注意","t":"東西の「兵農一致」","l":"byzantine-society","x":"国家が農民に土地を与え、その代わりに兵役を課すしくみは、同じころの東アジアにも見られた。中国の北魏から唐にかけての均田制と府兵制である（→「律令体制と唐の制度」の回）。ビザンツ帝国"},{"id":"byzantine-society-t2","k":"trivia","kj":"こぼれ話","t":"三重の城壁","l":"byzantine-society","x":"ギリシアの火とともにコンスタンティノープルを守ったのが、5世紀前半のテオドシウス2世の時代に築かれた、陸側の「テオドシウスの城壁」である。城壁は、幅約20mの堀、低い外壁、そして高"},{"id":"byzantine-society-t3","k":"source","kj":"史料","t":"聖像を擁護する神学者","l":"byzantine-society","x":"私は物質を拝むのではない。私のために物質となられた、物質の創造主を拝むのである。……かつて、体も形もない神は、決して描かれることはなかった。しかし今や、神は肉体をとって現れ、人々と"},{"id":"byzantine-society-t4","k":"trivia","kj":"こぼれ話","t":"「紫の生まれ」","l":"byzantine-society","x":"ビザンツの皇宮には、壁を紫色の斑岩で張りつめた「紫の間（ポルフュラ）」と呼ばれる部屋があった。在位中の皇帝の子どもは、この部屋で生まれた。そのような皇子・皇女は、「紫の生まれ（ポル"},{"id":"byzantine-society-t5","k":"myth","kj":"俗説","t":"「ブルガリア人殺し」","l":"byzantine-society","x":"バシレイオス2世は、「ブルガロクトノス（ブルガリア人殺し）」と呼ばれる。12世紀の歴史家スキュリツェスによれば、1014年のクレイディオンの戦いの後、バシレイオス2世は、捕虜にした"},{"id":"byzantine-society-t6","k":"person","kj":"人物","t":"二人の女帝――ゾエとテオドラ","l":"byzantine-society","x":"バシレイオス2世には子がなく、帝位は弟のコンスタンティノス8世を経て、その娘ゾエに受け継がれた。ゾエは、次々に3人の夫を皇帝に迎え、さらに養子を皇帝とした。1042年、その養子の皇"},{"id":"byzantine-society-t7","k":"now","kj":"いま","t":"正教会の分裂とウクライナ","l":"byzantine-society","x":"東方正教会は、ローマ教皇のような単一の首長をもたず、国ごとに独立した教会が並び立っている。その中で、コンスタンティノープル（イスタンブル）の総主教は、「同等の者の中の第一人者」とし"},{"id":"byzantine-society-t8","k":"works","kj":"作品紹介","t":"ビザンツ帝国にまつわる作品","l":"byzantine-society","x":"『ディゲネス・アクリタス』（12世紀ごろ）：アラブ人の父とビザンツ人の母をもつ英雄ディゲネスが、帝国の東の国境地帯で活躍する叙事詩。キリスト教徒とイスラーム教徒が戦いながらも交わり"},{"id":"caesar-augustus-t1","k":"trivia","kj":"こぼれ話","t":"海賊に身代金を値上げさせた男","l":"caesar-augustus","x":"若いころ、カエサルは留学のため船で東方に向かう途中、海賊に捕まった。海賊が身代金として20タラントンを要求すると、カエサルは笑って「自分にはそんな安い値段はつかない」と言い、50タ"},{"id":"caesar-augustus-t2","k":"trivia","kj":"こぼれ話","t":"アレクサンドロスの像の前で泣いた","l":"caesar-augustus","x":"スエトニウスによれば、30代の初め、ヒスパニア（スペイン）に赴任していたカエサルは、ガデス（現カディス）の神殿でアレクサンドロス大王の像を見て、ため息をついたという。大王が世界を征"},{"id":"caesar-augustus-t3","k":"confuse","kj":"混同注意","t":"第1回と第2回の三頭政治の違い","l":"caesar-augustus","x":"第1回三頭政治（前60年）は、三人の非公式な盟約にすぎなかった。これに対して第2回三頭政治（前43年）は、民会で法律を通して作られた、5年任期の正式な国家機関である。名前は同じでも"},{"id":"caesar-augustus-t4","k":"source","kj":"史料","t":"『ガリア戦記』の書き出し","l":"caesar-augustus","x":"Gallia est omnis divisa in partes tres, quarum unam incolunt Belgae, aliam Aquitani, terti"},{"id":"caesar-augustus-t5","k":"war","kj":"戦術","t":"アレシアの二重の包囲線","l":"caesar-augustus","x":"カエサルは、アレシアを力ずくで攻め落とそうとはしなかった。町の周りをぐるりと囲む防御線を築き、兵糧攻めにしたのである。カエサル自身の記録によれば、内側の包囲線は全長11ローマ・マイ"},{"id":"caesar-augustus-t6","k":"debate","kj":"諸説あり","t":"ガリア遠征の犠牲はどれほどだったのか","l":"caesar-augustus","x":"古代の著述家プリニウスは、カエサルが生涯の戦いで敵を119万2000人殺したと記している。プルタルコスは、ガリア遠征だけで100万人を殺し、100万人を捕虜にしたとする。いずれも正"},{"id":"caesar-augustus-t7","k":"source","kj":"史料","t":"「賽は投げられた」","l":"caesar-augustus","x":"スエトニウスによれば、ルビコン川の前でカエサルはしばらく迷ったのち、こう言ったという。Eatur quo deorum ostenta et inimicorum iniquita"},{"id":"caesar-augustus-t8","k":"trivia","kj":"こぼれ話","t":"寝具の袋に入って現れた女王","l":"caesar-augustus","x":"プルタルコスによれば、弟の側の兵に阻まれてカエサルに会えなかったクレオパトラは、寝具を包む袋に身を隠し、召使いに担がせて宮殿に入り込んだ。袋から現れたクレオパトラの機知に、カエサル"},{"id":"caesar-augustus-t9","k":"trivia","kj":"こぼれ話","t":"445日あった1年","l":"caesar-augustus","x":"当時のローマの暦は、1年が355日しかなく、ずれを直すために、神官たちがときどき「閏月」を差し込んでいた。ところが、この閏月の扱いが政治の駆け引きに使われ、いいかげんになっていた。"},{"id":"caesar-augustus-t10","k":"confuse","kj":"混同注意","t":"7月・8月はカエサルとアウグストゥス、では10月は？","l":"caesar-augustus","x":"カエサルの死後の前44年、彼の生まれ月だった「5番目の月（クインティリス）」は、「ユリウスの月（ユリウス）」に改められた。これが英語のJulyである。前8年には、「6番目の月（セク"},{"id":"caesar-augustus-t11","k":"source","kj":"史料","t":"なぜ8月が「アウグストゥスの月」になったのか","l":"caesar-augustus","x":"5世紀の著述家マクロビウスは、8月の名を改めたときの元老院決議を伝えている。それによると、アウグストゥスはこの月に初めてコンスルに就任し、三度の凱旋式を行い、エジプトをローマの支配"},{"id":"caesar-augustus-t12","k":"trivia","kj":"こぼれ話","t":"月桂冠で薄い髪を隠した？","l":"caesar-augustus","x":"スエトニウスによれば、カエサルは薄くなった頭髪をひどく気にしていた。頭頂の髪を前にとかしつけ、元老院から常に月桂冠をかぶる許可を与えられたことを、何よりも喜んだという。ガリア遠征の"},{"id":"caesar-augustus-t13","k":"source","kj":"史料","t":"「ブルートゥス、お前もか」は本当か","l":"caesar-augustus","x":"スエトニウスは、暗殺の場面をこう書いている。atque ita tribus et viginti plagis confossus est uno modo ad primum "},{"id":"caesar-augustus-t14","k":"trivia","kj":"こぼれ話","t":"「3月15日は来たが、まだ過ぎてはいない」","l":"caesar-augustus","x":"占い師スプリンナは、以前からカエサルに「3月15日まで危険に気をつけよ」と警告していたという。当日の朝、議場に向かう途中でスプリンナに会ったカエサルは、「3月15日は来たではないか"},{"id":"caesar-augustus-t15","k":"debate","kj":"諸説あり","t":"クレオパトラは「逃げた」のか","l":"caesar-augustus","x":"古代の史料は、クレオパトラが臆病風に吹かれて逃げ出し、恋に溺れたアントニウスがそれを追った、という筋書きで描いている。しかし、これは勝者であるオクタウィアヌスの側が作った物語の色が"},{"id":"caesar-augustus-t16","k":"trivia","kj":"こぼれ話","t":"クレオパトラは本当に毒蛇で死んだのか","l":"caesar-augustus","x":"クレオパトラが毒蛇（コブラの一種）に自分を噛ませて死んだという話は有名だが、プルタルコスはこの話を紹介したうえで、「真相は誰にも分からない」と書いている。毒蛇はイチジクの籠に隠して"},{"id":"caesar-augustus-t17","k":"source","kj":"史料","t":"『業績録』の言葉","l":"caesar-augustus","x":"アウグストゥスは死の直前、自分の業績を記した文章を残し、ローマの霊廟の前に青銅板に刻んで掲げさせた。その写しが、現在のトルコのアンカラの神殿の壁に残っている。『神君アウグストゥスの"},{"id":"caesar-augustus-t18","k":"confuse","kj":"混同注意","t":"「皇帝」「インペラトル」「カエサル」","l":"caesar-augustus","x":"日本語ではアウグストゥスを「初代ローマ皇帝」と呼ぶが、彼が「皇帝」という称号を名乗ったわけではない。英語のemperorの語源となった「インペラトル」は、もともと勝利した将軍を兵士"},{"id":"caesar-augustus-t19","k":"trivia","kj":"こぼれ話","t":"「喜劇はうまく演じられたか」――最期の言葉","l":"caesar-augustus","x":"後14年8月19日、アウグストゥスはナポリ近くのノラで、75歳の生涯を閉じた。スエトニウスによれば、臨終の日、彼は鏡を持ってこさせて髪を整えさせ、友人たちを呼び入れて「人生という喜"},{"id":"caesar-augustus-t20","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"caesar-augustus","x":"シェイクスピア『ジュリアス・シーザー』（1599年ごろ初演）：カエサル暗殺と、その後のブルートゥスとアントニウスの争いを描いた悲劇。「ブルータス、おまえもか」のせりふで有名だが、こ"},{"id":"catholic-church-t1","k":"myth","kj":"俗説","t":"天使の城","l":"catholic-church","x":"590年、ペストの流行を鎮めるために、グレゴリウスは、ローマ市民を率いて、祈りの行列を行った。伝承によれば、行列がテヴェレ川のほとりのハドリアヌス帝の霊廟の近くにさしかかった時、霊"},{"id":"catholic-church-t2","k":"source","kj":"史料","t":"神殿を壊すな","l":"catholic-church","x":"グレゴリウス1世は、601年、ブリテン島に向かう修道士メリトゥスに、布教の方法について、次のような手紙を送っている。その民族の偶像の神殿は、壊してはならない。神殿の中の偶像だけを壊"},{"id":"catholic-church-t3","k":"trivia","kj":"こぼれ話","t":"『ケルズの書』のネコとネズミ","l":"catholic-church","x":"『ケルズの書』は、子牛の皮から作った羊皮紙340枚に、4つの福音書をラテン語で書き写し、渦巻きや組みひも、動物や人の姿を組み合わせた、細かな装飾をほどこした写本である。アイオナ島の"},{"id":"catholic-church-t4","k":"myth","kj":"俗説","t":"剣を受け止めた本","l":"catholic-church","x":"754年、80歳近い老人となったボニファティウスは、最後の布教の旅として、北海沿岸のフリースラント（現在のオランダ北部）に向かった。6月5日、ドックムの近くで、ボニファティウスの一"},{"id":"catholic-church-t5","k":"now","kj":"いま","t":"モンテ・カッシーノの破壊と再建","l":"catholic-church","x":"ベネディクトゥスが開いたモンテ・カッシーノ修道院は、その歴史の中で、何度も破壊された。6世紀末にはランゴバルド人に、9世紀にはイスラーム勢力に、14世紀には地震によって破壊され、そ"},{"id":"catholic-church-t6","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"catholic-church","x":"ウンベルト・エーコ『薔薇の名前』（1980年）：14世紀のイタリアのベネディクト会修道院を舞台に、写字室と図書館の秘密をめぐって起こる連続殺人を描いた小説。修道院の1日の生活が、聖"},{"id":"cave-art-t1","k":"trivia","kj":"こぼれ話","t":"8歳の少女の発見は、20年以上信じてもらえなかった","l":"cave-art","x":"アルタミラの洞窟壁画を最初に見つけたのは、8歳の少女マリアだった。1879年、父のサウトゥオラが洞窟の床を掘っていたとき、そばで天井を見上げたマリアが「パパ、見て、牛がいる！」と叫"},{"id":"cave-art-t2","k":"now","kj":"いま","t":"ラスコーはなぜ閉ざされたのか","l":"cave-art","x":"ラスコーの洞窟は1948年に一般公開され、多くの観光客が訪れた。ところが、1日に1000人を超える人々の吐く息や体温、持ち込まれた菌によって、洞窟の中の環境が変わり、壁に緑色のカビ"},{"id":"cave-art-t3","k":"debate","kj":"諸説あり","t":"ネアンデルタール人も絵を描いた？","l":"cave-art","x":"2018年、スペインの三つの洞窟で見つかった赤い顔料の線や手形が、6万4000年以上前のものだと発表された。この時代のヨーロッパには、まだホモ＝サピエンスは到達していなかった。もし"},{"id":"cave-art-t4","k":"trivia","kj":"こぼれ話","t":"「ヴィーナス」と呼ばれる女性像","l":"cave-art","x":"ヨーロッパからシベリアにかけての旧石器時代の遺跡からは、胸や腹、腰を強調した小さな女性の像がたくさん見つかっている。オーストリアで見つかった「ヴィレンドルフのヴィーナス」（約3万年"},{"id":"cave-art-t5","k":"life","kj":"暮らし","t":"3万4000年前の豪華な墓","l":"cave-art","x":"ロシアのスンギール遺跡では、約3万4000年前の墓が見つかっている。少年と少女が頭を合わせるように葬られた墓には、マンモスの牙で作った1万個以上のビーズや、長い槍、動物の彫刻などが"},{"id":"cave-art-t6","k":"view","kj":"視点を変える","t":"アボリジニにとっての岩絵","l":"cave-art","x":"アボリジニの人々は、世界で最も長く続く文化の担い手の一つとされる。彼らの考え方では、祖先の霊が大地を旅しながら、山や川、動植物、人間の決まりごとを作った「ドリーミング」の世界は、遠"},{"id":"charlemagne-t1","k":"source","kj":"史料","t":"ザクセン人への勅令","l":"charlemagne","x":"ザクセン人の征服は、キリスト教への改宗と一体となって進められた。782年ごろ（785年ごろとも）に出されたと考えられている「ザクセン地方に関する勅令」には、次のような条文が並んでい"},{"id":"charlemagne-t2","k":"myth","kj":"俗説","t":"『ローランの歌』","l":"charlemagne","x":"ロンスヴォーで戦死した後衛の指揮官の一人が、ブルターニュ辺境の長官ローランであった。アインハルトが名前を一度だけ挙げているにすぎないこの人物は、約300年後に、フランス最古の叙事詩"},{"id":"charlemagne-t3","k":"trivia","kj":"こぼれ話","t":"1ポンド＝240ペンス","l":"charlemagne","x":"カールは、父ピピンの改革を受け継いで、通貨の制度を整えた。重さ1リブラ（ポンド）の銀から240枚のデナリウス銀貨を作り、12デナリウスを1ソリドゥスとして、計算の単位とした。つまり"},{"id":"charlemagne-t4","k":"person","kj":"人物","t":"文字を書こうとした皇帝","l":"charlemagne","x":"アインハルトは、カールの人柄について、多くのことを書き残している。カールは背が高く、その身長は自分の足の長さの7倍あったという。2010年には、アーヘン大聖堂に伝わるカールの遺骨と"},{"id":"charlemagne-t5","k":"trivia","kj":"こぼれ話","t":"象のアブル・アッバース","l":"charlemagne","x":"カールは、遠くアッバース朝のカリフ、ハールーン・アッラシードとも使節を交換した（→「アッバース朝とバグダード」の回）。797年、カールが送った使節団は、802年、ハールーンからの贈"},{"id":"charlemagne-t6","k":"debate","kj":"諸説あり","t":"「ムハンマドなくして、カールなし」","l":"charlemagne","x":"ベルギーの歴史家アンリ・ピレンヌは、1937年に出版された『ヨーロッパ世界の誕生――マホメットとシャルルマーニュ』の中で、「ムハンマドなくしては、シャルルマーニュ（カール大帝）は考"},{"id":"charlemagne-t7","k":"source","kj":"史料","t":"ストラスブールの誓約","l":"charlemagne","x":"842年、ルートヴィヒとシャルルは、ストラスブールで、互いの軍隊の前で、同盟の誓いを交わした。この時、ルートヴィヒは、シャルルの兵士たちにわかるように、ロマンス語（のちのフランス語"},{"id":"charlemagne-t8","k":"now","kj":"いま","t":"ロタールの国の名残り","l":"charlemagne","x":"ロタールの中部フランクの北の部分は、ロタールの息子ロタール2世の名にちなんで「ロタリンギア」（ロタールの国）と呼ばれた。この名前が、現在のフランス東部の「ロレーヌ」地方（ドイツ語で"},{"id":"charlemagne-t9","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"charlemagne","x":"アインハルト『カール大帝伝』：カールに仕えた学者による伝記。古代ローマのスエトニウスの『皇帝伝』を手本に書かれた。日本語訳に、國原吉之助訳『カロルス大帝伝』（筑摩書房）がある。『ロ"},{"id":"china-neolithic-t1","k":"trivia","kj":"こぼれ話","t":"黄河は「黄色い川」","l":"china-neolithic","x":"黄河の水は、黄土を大量に含んでいるため、名前の通り黄色く濁っている。1立方メートルの水に含まれる土砂の量は、世界の大河の中でも際立って多い。運ばれた土砂が下流で積もるため、黄河の川"},{"id":"china-neolithic-t2","k":"life","kj":"暮らし","t":"半坡遺跡――濠に囲まれた村","l":"china-neolithic","x":"陝西省の西安郊外にある半坡遺跡は、仰韶文化の代表的な集落の跡である。直径約200mほどの居住区を、深さ5〜6m、幅6〜8mの大きな濠が取り囲んでいた。中央の広場の周りに数十軒の住居"},{"id":"china-neolithic-t3","k":"view","kj":"視点を変える","t":"「中国文明は西から来た」？","l":"china-neolithic","x":"仰韶文化を発見したアンダーソンは、その彩陶が、遠く西アジアや東ヨーロッパの新石器時代の彩文土器に似ていることに注目し、中国の文明は西方から伝わった文化の影響を受けて生まれたのではな"},{"id":"china-neolithic-t4","k":"trivia","kj":"こぼれ話","t":"陶寺遺跡の「観象台」","l":"china-neolithic","x":"山西省の陶寺遺跡は、竜山文化の時代（前2300〜前1900年ごろ）の大規模な城壁都市の跡である。ここで見つかった半円形の土台には、版築の柱が弧を描いて並び、柱のすき間から、季節ごと"},{"id":"china-neolithic-t5","k":"confuse","kj":"混同注意","t":"仰韶文化と竜山文化","l":"china-neolithic","x":"仰韶文化竜山文化時期前5000〜前3000年ごろ前3000〜前2000年ごろ中心地黄河中流域黄河下流域から中流域へ土器彩陶（赤地に黒・白の文様）黒陶（薄く光沢がある）・灰陶発見19"},{"id":"china-neolithic-t6","k":"now","kj":"いま","t":"良渚――「中国最古の国家」？","l":"china-neolithic","x":"浙江省杭州市の郊外にある良渚遺跡では、2000年代以降の調査で、東西約1.7km・南北約1.9kmの城壁に囲まれた都市の跡が明らかになった。中央には人工的に築かれた巨大な基壇があり"},{"id":"china-neolithic-t7","k":"view","kj":"視点を変える","t":"「満天の星」――多元的な中国文明","l":"china-neolithic","x":"中国の考古学者・蘇秉琦は、新石器時代の中国各地に、それぞれ個性的な文化がいくつも並び立っていた様子を、「満天の星」にたとえた。黄河流域だけが光っていたのではなく、空一面に星が散らば"},{"id":"china-neolithic-t8","k":"source","kj":"史料","t":"禹の治水","l":"china-neolithic","x":"『史記』は、禹の治水の苦労を次のように伝えている。禹は、父が治水に失敗して罰せられたことを悲しみ、身を苦しめ心を労して、13年間、外で働いた。自分の家の門の前を通り過ぎても、中に入"},{"id":"china-neolithic-t9","k":"debate","kj":"諸説あり","t":"夏王朝は実在したか","l":"china-neolithic","x":"夏王朝が実在したかどうかは、今も議論が続いている諸説。河南省の二里頭遺跡（前1900〜前1500年ごろ）からは、大規模な宮殿の基壇や、中国で最も古い青銅の礼器（儀式に使う器）、トル"},{"id":"christianity-origin-t1","k":"confuse","kj":"混同注意","t":"イエスの時代のユダヤ教の主な宗派","l":"christianity-origin","x":"宗派担い手特色サドカイ派神殿の祭司・貴族エルサレム神殿の儀式を重視。ローマの支配に協力的。死後の復活を否定パリサイ派（ファリサイ派）律法学者・中流の人々律法を日常生活の細部まで厳格"},{"id":"christianity-origin-t2","k":"now","kj":"いま","t":"死海文書の発見","l":"christianity-origin","x":"1947年、死海の北西岸のクムランの洞窟で、羊を探していたベドウィン（遊牧民）の少年が、壺に入った古い巻物を見つけた。その後の調査で、11の洞窟から、900点を超える文書の断片が発"},{"id":"christianity-origin-t3","k":"trivia","kj":"こぼれ話","t":"イエスは「紀元前」に生まれた？","l":"christianity-origin","x":"現在の西暦は、6世紀のローマの修道士ディオニュシウス＝エクシグウスが、イエスの誕生の年を計算し、それを紀元1年としたものである。ところが、福音書によれば、イエスはヘロデ王の時代に生"},{"id":"christianity-origin-t4","k":"source","kj":"史料","t":"山上の垂訓","l":"christianity-origin","x":"心の貧しい人々は、幸いである。天の国はその人たちのものである。悲しむ人々は、幸いである。その人たちは慰められる。……あなたがたも聞いているとおり、「目には目を、歯には歯を」と命じら"},{"id":"christianity-origin-t5","k":"source","kj":"史料","t":"ローマの歴史家が記したキリスト","l":"christianity-origin","x":"イエスについて記したローマ側の史料は少ないが、歴史家タキトゥスは、64年のローマの大火について記した中で、次のように書いている。ネロは、この噂（ネロが火をつけさせたという噂）を打ち"},{"id":"christianity-origin-t6","k":"confuse","kj":"混同注意","t":"ユダヤ教とキリスト教","l":"christianity-origin","x":"ユダヤ教キリスト教神唯一神ヤハウェ同じ唯一神（父なる神）イエス救世主とは認めない救世主（キリスト）・神の子聖典ヘブライ語聖書（キリスト教のいう旧約聖書）旧約聖書＋新約聖書救いの対象"},{"id":"christianity-origin-t7","k":"source","kj":"史料","t":"「ユダヤ人もギリシア人もない」","l":"christianity-origin","x":"パウロは、旅先から各地の教会に宛てて、多くの手紙を書いた。それらは『新約聖書』に収められ、新約聖書の中で最も古い文書となっている。あなたがたは皆、信仰により、キリスト＝イエスにあっ"},{"id":"christianity-origin-t8","k":"trivia","kj":"こぼれ話","t":"「新約」「旧約」とは","l":"christianity-origin","x":"「約」とは、神と人間との「契約」のことである。ユダヤ教では、神がモーセを通じてユダヤ人と結んだ契約を重んじる。キリスト教では、イエス＝キリストによって、神とすべての人間との「新しい"},{"id":"christianity-origin-t9","k":"now","kj":"いま","t":"「嘆きの壁」とエルサレム","l":"christianity-origin","x":"70年に焼かれた神殿のうち、ヘロデ王が築いた神殿の丘を囲む擁壁の一部が、今も残っている。これが「嘆きの壁」（西の壁）で、ユダヤ教の最も重要な祈りの場となっている。一方、神殿の丘の上"},{"id":"christianity-origin-t10","k":"source","kj":"史料","t":"小プリニウスとトラヤヌス帝の往復書簡","l":"christianity-origin","x":"112年ごろ、小アジアの属州ビテュニアの総督であった小プリニウス（→「ローマ人の暮らし」の回）は、キリスト教徒の扱いについて、トラヤヌス帝に問い合わせる手紙を書いた。私は、キリスト"},{"id":"christianity-origin-t11","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"christianity-origin","x":"映画『ベン・ハー』（1959年、ウィリアム・ワイラー監督）：イエスと同じ時代を生きたユダヤ人の貴族ベン・ハーの数奇な運命を描く。原作はルー・ウォーレスの小説（1880年）。戦車競走"},{"id":"christianity-rome-t1","k":"source","kj":"史料","t":"犠牲証明書","l":"christianity-rome","x":"犠牲を監督する役人の方々へ。……村の某より。私たちは、これまでずっと神々に犠牲を捧げ、敬ってまいりました。そして今また、命令に従い、あなたがたの前で、献酒をし、犠牲を捧げ、供え物を"},{"id":"christianity-rome-t2","k":"source","kj":"史料","t":"コンスタンティヌスが見たもの","l":"christianity-rome","x":"コンスタンティヌスは、夢の中で、天のしるしを兵士たちの盾に描かせ、そうして戦いに臨むよう告げられた。彼は命じられたとおりにし、Xの文字に縦の線を通し、その上端を丸く曲げた、キリスト"},{"id":"christianity-rome-t3","k":"source","kj":"史料","t":"ミラノ勅令","l":"christianity-rome","x":"私たち、コンスタンティヌス＝アウグストゥスと、リキニウス＝アウグストゥスは、ミラノで幸いにも会見し、……キリスト教徒にも、またすべての人々にも、それぞれが望む宗教に従う自由な権限を"},{"id":"christianity-rome-t4","k":"trivia","kj":"こぼれ話","t":"ヘレナと「聖十字架」","l":"christianity-rome","x":"コンスタンティヌスの母ヘレナは、熱心なキリスト教徒となり、320年代後半、70歳を超えて聖地エルサレムを巡礼した。彼女は、イエスの生誕地ベツレヘムや、エルサレムのオリーブ山に教会を"},{"id":"christianity-rome-t5","k":"source","kj":"史料","t":"ニケーア信条（325年）","l":"christianity-rome","x":"私たちは、唯一の神、全能の父、見えるものと見えないものすべての造り主を信じる。また、唯一の主イエス・キリストを信じる。神の子、父から生まれた独り子、すなわち父の本質から生まれ、神か"},{"id":"christianity-rome-t6","k":"myth","kj":"俗説","t":"サンタクロースがアリウスを殴った？","l":"christianity-rome","x":"後世の伝説によれば、ニケーア公会議の席で、小アジアのミラの司教ニコラオスは、アリウスの主張に激怒して、彼の顔を平手で打ったという。このニコラオスが、子どもたちに贈り物をしたという伝"},{"id":"christianity-rome-t7","k":"source","kj":"史料","t":"ユリアヌスが見たキリスト教徒の強さ","l":"christianity-rome","x":"ユダヤ人には物乞いをする者が一人もおらず、不敬なガリラヤ人（キリスト教徒）は、自分たちの貧しい者だけでなく、われわれの貧しい者まで養っている。それなのに、われわれの側の者が、われわ"},{"id":"christianity-rome-t8","k":"source","kj":"史料","t":"テオドシウス帝の勅令（380年）","l":"christianity-rome","x":"朕の寛大な支配のもとにあるすべての民は、神聖なる使徒ペテロがローマ人に伝えた宗教のうちにとどまることを、朕は望む。……すなわち、父と子と聖霊が、等しい威厳をもつ唯一の神であると信じ"},{"id":"christianity-rome-t9","k":"now","kj":"いま","t":"ニケーア信条の1700年","l":"christianity-rome","x":"2025年は、ニケーア公会議から1700年の節目の年であった。2025年11月、ローマ教皇レオ14世は、トルコのイズニク（古代のニケーア）を訪れ、コンスタンティノープル総主教バルト"},{"id":"christianity-rome-t10","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"christianity-rome","x":"辻邦生『背教者ユリアヌス』（1972年）：皇族の粛清を生き延びた少年ユリアヌスが、哲学に目覚め、皇帝となって伝統の神々の復活に挑み、遠征の地で倒れるまでを描いた長編小説。毎日芸術賞"},{"id":"chu-han-t1","k":"source","kj":"史料","t":"「王侯将相いずくんぞ種あらんや」","l":"chu-han","x":"陳勝は若いころ、日雇いで畑を耕していたとき、仲間に「金持ちになっても、お互い忘れないようにしよう」と言った。仲間が「雇われ者の身で、金持ちになどなれるものか」と笑うと、陳勝はため息"},{"id":"chu-han-t2","k":"debate","kj":"諸説あり","t":"遅刻したら本当に死刑だったのか","l":"chu-han","x":"『史記』は、期限に遅れれば「法では皆斬」と記している。ところが、1975年に発見された睡虎地秦簡の法律（徭律）では、労役の集合に遅れた場合の罰は、3〜5日の遅れで叱責、6〜10日で"},{"id":"chu-han-t3","k":"source","kj":"史料","t":"始皇帝の行列を見た二人","l":"chu-han","x":"若いころ、二人はそれぞれ、巡幸する始皇帝の行列を見たことがあった。会稽で行列を見た項羽は言った。彼、取って代わるべきなり（あいつに取って代わってやる）。出典：『史記』項羽本紀（本サ"},{"id":"chu-han-t4","k":"source","kj":"史料","t":"法三章","l":"chu-han","x":"父老たちは、秦の苛酷な法に長い間苦しんできた。……私は、父老たちと約束する。法はただ三章のみとする。人を殺した者は死刑。人を傷つけた者と盗んだ者は、罪に応じて罰する。そのほかの秦の"},{"id":"chu-han-t5","k":"source","kj":"史料","t":"背水の陣","l":"chu-han","x":"前204年、韓信は、わずか数万の兵で、20万と号する趙の大軍と、井陘（せいけい）で戦った。韓信は、川を背にして陣を敷いた。兵法では、川や沼を背にして陣を敷くことは、逃げ場がなくなる"},{"id":"chu-han-t6","k":"myth","kj":"俗説","t":"韓信の股くぐり","l":"chu-han","x":"韓信は、若いころ、貧しくて食べる物にも困っていた。故郷の淮陰の町で、ある若者が韓信をばかにして言った。「おまえは図体が大きくて剣を帯びているが、実は臆病者だろう。死ぬ気があるなら俺"},{"id":"chu-han-t7","k":"source","kj":"史料","t":"垓下の歌","l":"chu-han","x":"項王は夜中に起きて、とばりの中で酒を飲んだ。美人がいて、名を虞（ぐ）といい、いつも寵愛されて付き従っていた。駿馬がいて、名を騅（すい）といい、いつもこれに乗っていた。項王は悲しげに"},{"id":"chu-han-t8","k":"trivia","kj":"こぼれ話","t":"捲土重来","l":"chu-han","x":"のちの唐の詩人杜牧は、烏江を訪れて、項羽を惜しむ詩をつくった。「江東の子弟 才俊多し 捲土重来 未だ知るべからず」――江東の若者には優れた者が多い。もし項羽が江東に戻っていれば、土"},{"id":"chu-han-t9","k":"source","kj":"史料","t":"劉邦の自己分析","l":"chu-han","x":"天下を統一したのち、劉邦は、宴席で臣下たちに、自分が天下を取り、項羽が天下を失った理由を問うた。臣下たちの答えを聞いたのち、劉邦は自ら言った。本陣の中で計略をめぐらし、千里の外で勝"},{"id":"chu-han-t10","k":"view","kj":"視点を変える","t":"「勝者の歴史」としての『史記』","l":"chu-han","x":"私たちが知る項羽と劉邦の物語は、そのほとんどが、劉邦の子孫が皇帝として君臨する漢の時代に、司馬遷が書いた『史記』による。それでも、司馬遷は、皇帝にならなかった項羽のために、皇帝の伝"},{"id":"chu-han-t11","k":"confuse","kj":"混同注意","t":"封建制・郡県制・郡国制","l":"chu-han","x":"封建制郡県制郡国制王朝周秦（始皇帝）前漢初め（高祖）しくみ一族・功臣を諸侯に封じ、世襲で治めさせる全国を郡・県に分け、中央から役人を派遣する直轄地は郡県制、遠方は一族・功臣を王に封"},{"id":"chu-han-t12","k":"source","kj":"史料","t":"狡兎死して走狗烹らる","l":"chu-han","x":"前196年、韓信は、謀反を企てたとして、高祖の皇后呂后と蕭何の計略によって捕らえられ、処刑された。その数年前、楚王であった韓信が謀反の疑いで捕らえられたとき、韓信は次のように嘆いた"},{"id":"chu-han-t13","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"chu-han","x":"司馬遼太郎『項羽と劉邦』（1980年刊）：秦の滅亡から垓下の戦いまでを、2人の英雄と、彼らを取り巻く人々の群像劇として描いた長編小説。「なぜ劉邦が勝ったのか」という問いが、作品全体"},{"id":"crisis-3rd-t1","k":"source","kj":"史料","t":"死の床の遺言","l":"crisis-3rd","x":"兄弟仲良くせよ。兵士を富ませよ。ほかの者はすべて軽んじてよい。出典：カッシウス＝ディオ『ローマ史』第77巻15章（3世紀前半）（本サイト訳）211年、ブリタニアのエボラクム（現在の"},{"id":"crisis-3rd-t2","k":"myth","kj":"俗説","t":"エラガバルスのバラ","l":"crisis-3rd","x":"4世紀末に書かれた皇帝伝記集『ローマ皇帝群像（ヒストリア＝アウグスタ）』は、エラガバルスについて、宴会の天井から大量のバラの花びらを降らせて客を窒息死させた、といった数々の奇行を伝"},{"id":"crisis-3rd-t3","k":"source","kj":"史料","t":"シャープール1世の勝利の碑文","l":"crisis-3rd","x":"カエサル（ローマ皇帝）ウァレリアヌスが、7万の軍勢を率いて我らに向かってきた。カルラエとエデッサの向こう側で、我らはカエサル＝ウァレリアヌスと大いに戦い、カエサル＝ウァレリアヌスを"},{"id":"crisis-3rd-t4","k":"person","kj":"人物","t":"ゼノビア――ローマと渡り合った女王","l":"crisis-3rd","x":"パルミラは、シリア砂漠のオアシスにある隊商都市で、ローマとペルシア、さらにインドを結ぶ交易で繁栄していた（→「パルティアとイラン世界」の回）。夫オダエナトゥスが267年ごろに暗殺さ"},{"id":"crisis-3rd-t5","k":"source","kj":"史料","t":"最高価格令が定めた価格","l":"crisis-3rd","x":"最高価格令は、帝国各地の都市の広場に碑文として掲げられ、その断片が現在まで残っている。そこに記された価格の一部を見てみよう（単位はデナリウス）。品目・仕事最高価格小麦（1モディウス"},{"id":"crisis-3rd-t6","k":"trivia","kj":"こぼれ話","t":"「わたしが育てたキャベツを見せたい」","l":"crisis-3rd","x":"ディオクレティアヌスの退位後、皇帝たちの争いが激しくなると、308年、皇帝たちはドナウ川沿いのカルヌントゥムに集まって会議を開き、引退していたディオクレティアヌスにも出席を求めた。"},{"id":"crisis-3rd-t7","k":"debate","kj":"諸説あり","t":"「危機」はあったのか","l":"crisis-3rd","x":"「3世紀の危機」という言葉は、帝国が内乱・外敵・経済の混乱によって崩壊寸前に陥ったというイメージを与える。しかし、近年の研究では、危機の深刻さには地域差が大きかったことが指摘されて"},{"id":"crisis-3rd-t8","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"crisis-3rd","x":"映画『グラディエーターII 英雄を呼ぶ声』（2024年、リドリー・スコット監督）：カラカラとゲタの兄弟が共同皇帝として統治する時代のローマを舞台に、剣闘士となった主人公の戦いを描く"},{"id":"east-asia-early-t1","k":"term","kj":"用語","t":"漢字は朝鮮半島を経て伝わった","l":"east-asia-early","x":"楽浪郡の遺跡からは、紀元前45年の楽浪郡の各県の人口を記録した木簡（「楽浪郡初元四年県別戸口簿」）が見つかっている。それによれば、楽浪郡には、約4万3000戸、28万人余りが登録さ"},{"id":"east-asia-early-t2","k":"source","kj":"史料","t":"弁辰の鉄","l":"east-asia-early","x":"国は鉄を産出し、韓・濊・倭はみなこれを取っている。どの市での売買にも鉄を用いており、それは中国で銭を用いるのと同じようである。また、鉄を（楽浪・帯方の）2郡にも供給している。出典："},{"id":"east-asia-early-t3","k":"source","kj":"史料","t":"中国の史書に記された倭","l":"east-asia-early","x":"そもそも楽浪の海の中に倭人がおり、分かれて百余りの国をなしている。毎年、季節ごとにやって来て、貢ぎ物を献じ、皇帝に謁見するという。出典：『漢書』地理志（1世紀、班固）（本サイト訳）"},{"id":"east-asia-early-t4","k":"debate","kj":"諸説あり","t":"金印は本物か","l":"east-asia-early","x":"金印の発見のいきさつには、はっきりしない点が多く、発見した人物や正確な場所についても、記録によって食い違いがある。そのため、江戸時代の偽作ではないかとする説も唱えられてきた。しかし"},{"id":"east-asia-early-t5","k":"source","kj":"史料","t":"『魏志』倭人伝が記す卑弥呼","l":"east-asia-early","x":"その国（倭）は、もとは男子を王としていた。70〜80年たつと、倭国は乱れ、何年も互いに攻め合った。そこで、ともに一人の女子を立てて王とした。名を卑弥呼という。鬼道に仕え、よく人々を"},{"id":"east-asia-early-t6","k":"debate","kj":"諸説あり","t":"邪馬台国はどこにあったのか","l":"east-asia-early","x":"倭人伝は、帯方郡から邪馬台国までの道のりを、方角と距離（または日数）で記している。ところが、その記述どおりに進むと、九州のはるか南の海の上に出てしまう。そのため、方角か距離のどちら"},{"id":"east-asia-early-t7","k":"now","kj":"いま","t":"古代史をめぐる歴史論争","l":"east-asia-early","x":"古代の東アジアの歴史は、現在の国家の枠組みとは一致しない。そのため、古代の国家がどの国の歴史に属するのかが、現代の国家間の争点になることがある。その代表が、高句麗の帰属をめぐる中国"},{"id":"east-asia-early-t8","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"east-asia-early","x":"手塚治虫『火の鳥 黎明編』（漫画、1967年）：3世紀の日本列島を舞台に、ヤマタイ国の女王ヒミコと、不老不死をもたらす「火の鳥」をめぐる人々の物語。ヒミコを、老いを恐れる女王として"},{"id":"egypt-life-t1","k":"confuse","kj":"混同注意","t":"同じ「神権政治」でも","l":"egypt-life","x":"メソポタミアのシュメール人の都市国家も、エジプトも、「神権政治」の国と説明される。しかし、その中身は少し違う。シュメールの王（ルガル）は、都市の守り神に仕え、神の代理として都市を治"},{"id":"egypt-life-t2","k":"source","kj":"史料","t":"オシリスの死と復活","l":"egypt-life","x":"オシリスはエジプトを治める善良な王だった。しかし、弟のセトにねたまれて殺され、体はばらばらにされてエジプト中にまき散らされた。オシリスの妻イシスは、各地を探し回って夫の体を集め、つ"},{"id":"egypt-life-t3","k":"trivia","kj":"こぼれ話","t":"動物のミイラ","l":"egypt-life","x":"ミイラにされたのは人間だけではなかった。猫・トキ・ハヤブサ・ワニ・犬などの動物も、神の使いとして大量にミイラにされ、神殿に奉納された。サッカラのトキの地下墓地からは、数百万体ものト"},{"id":"egypt-life-t4","k":"source","kj":"史料","t":"死者の書の「否定告白」から","l":"egypt-life","x":"私は人に悪を行わなかった。私は家畜を虐げなかった。私は神殿の供え物を奪わなかった。私は飢えさせなかった。私は泣かせなかった。私は殺さなかった。私は畑の境を動かさなかった。私は天秤の"},{"id":"egypt-life-t5","k":"confuse","kj":"混同注意","t":"ヒエログリフと楔形文字","l":"egypt-life","x":"ヒエログリフ楔形文字地域エジプトメソポタミアを中心に西アジア一帯書き方石に刻む、パピルスにインクで書く粘土板に葦のペンを押しつける使った言語エジプト語のみシュメール語、アッカド語、"},{"id":"egypt-life-t6","k":"trivia","kj":"こぼれ話","t":"「やったぞ！」と叫んで気絶した","l":"egypt-life","x":"伝えられるところでは、1822年9月、ヒエログリフの解読に確信を得たシャンポリオンは、兄のいる研究所に駆け込み、「やったぞ！（ジュ・ティアン・ラフェール）」と叫んで、そのまま気を失"},{"id":"egypt-life-t7","k":"source","kj":"史料","t":"「12キュビトなら飢饉」","l":"egypt-life","x":"1世紀のローマの博物学者プリニウス（大プリニウス）は、ナイル川の増水の高さと、その年の暮らしの関係を次のように記している。12キュビトの増水では飢饉となり、13キュビトでは飢えが残"},{"id":"egypt-life-t8","k":"debate","kj":"諸説あり","t":"「縄張り師」は3・4・5の縄を使ったか","l":"egypt-life","x":"古代エジプトでは、神殿の基礎を定める儀式で、王と女神が杭と縄を使って建物の位置を決める「縄を張る」場面が描かれている。また、前5世紀ごろのギリシアの哲学者デモクリトスは、「線を描い"},{"id":"egypt-life-t9","k":"confuse","kj":"混同注意","t":"太陽暦と太陰暦","l":"egypt-life","x":"太陽暦太陰暦もとにする天体太陽（季節のめぐり）月（満ち欠け）1年365日約354日（12か月）生まれた地域エジプトメソポタミア長所季節とずれない。農業に便利月の形で日付が分かるメソ"},{"id":"egypt-life-t10","k":"life","kj":"暮らし","t":"欠勤届の理由","l":"egypt-life","x":"ある職人の出勤簿には、欠勤した日とその理由がずらりと書き込まれている。「病気」「目が悪い」といったもっともな理由のほかに、「サソリに刺された」「兄弟のミイラ作りのため」「ビールを造"},{"id":"egypt-life-t11","k":"life","kj":"暮らし","t":"世界最古のストライキ","l":"egypt-life","x":"ラメス3世の治世第29年（前12世紀前半）、デル＝エル＝メディナの職人たちへの給料（穀物）の支給が遅れた。職人たちは仕事を放棄して持ち場を離れ、王の葬祭殿の裏に座り込んだ。記録に残"},{"id":"egypt-life-t12","k":"source","kj":"史料","t":"「書記ほどよい仕事はない」","l":"egypt-life","x":"中王国時代に書かれた『職業の風刺』（ドゥアケティの教訓）は、父親が息子を書記の学校に連れていく道すがら、ほかの職業がいかにつらいかを説いて聞かせる、という形の作品である。鍛冶屋は炉"},{"id":"egypt-new-t1","k":"confuse","kj":"混同注意","t":"中王国の都は「テーベ」か","l":"egypt-new","x":"教科書では、中王国の都はテーベ、新王国の都もテーベと説明されることが多い。テーベが中王国を興した王家の本拠地で、王家の守り神アメンの信仰の中心だったからである。ただし、中王国の第1"},{"id":"egypt-new-t2","k":"source","kj":"史料","t":"『シヌヘの物語』――故郷に葬られたい","l":"egypt-new","x":"中王国時代の物語『シヌヘの物語』の主人公シヌヘは、第12王朝の王アメンエムハト1世に仕える役人だった。遠征中に王の暗殺を知ったシヌヘは、なぜか恐ろしくなって逃げ出し、シリア・パレス"},{"id":"egypt-new-t3","k":"trivia","kj":"こぼれ話","t":"「カバがうるさくて眠れない」","l":"egypt-new","x":"新王国時代に書かれた物語の断片に、こんな話がある。ヒクソスの王アペピが、テーベの王セケンエンラーに使者を送り、「おまえの町の池のカバが、夜うるさく鳴くので眠れない。なんとかせよ」と"},{"id":"egypt-new-t4","k":"war","kj":"戦術","t":"メギドの戦い――狭い山道を選んだ王","l":"egypt-new","x":"前1457年ごろ、トトメス3世は、パレスチナ北部の要衝メギドに集まったシリア・パレスチナの諸侯の連合軍と戦った。カルナック神殿の壁に刻まれた『トトメス3世年代記』によれば、メギドへ"},{"id":"egypt-new-t5","k":"person","kj":"人物","t":"つけひげの女王――消された記憶","l":"egypt-new","x":"ハトシェプストの像には、女性の姿で表されたものと、王の頭巾をかぶり、あごに儀式用のつけひげをつけた男性の王の姿で表されたものがある。ファラオは本来男性であるという考えが強かったため"},{"id":"egypt-new-t6","k":"source","kj":"史料","t":"王たちの手紙――「わが兄弟よ」","l":"egypt-new","x":"アマルナ文書の大国の王たちは、互いに「わが兄弟」と呼び合っている。対等な大国どうしであることを示す呼び方だった。一方、シリア・パレスチナの小国の王たちは、エジプト王を「わが主、わが"},{"id":"egypt-new-t7","k":"view","kj":"視点を変える","t":"「国際社会」はヨーロッパで生まれたのではない","l":"egypt-new","x":"主権を持つ国々が互いを対等と認め、外交使節を送り合い、条約を結ぶ――こうした「国際社会」のしくみは、近代ヨーロッパで生まれたものと説明されることが多い。しかし、アマルナ文書に見られ"},{"id":"egypt-new-t8","k":"confuse","kj":"混同注意","t":"アメンホテプ4世＝イクナートン","l":"egypt-new","x":"同じ人物が二つの名前で呼ばれるので注意したい。即位したときの名がアメンホテプ4世（「アメンは満足する」の意味）で、改革の途中でイクナートン（アクエンアテン）と改名した。試験では、ど"},{"id":"egypt-new-t9","k":"now","kj":"いま","t":"ネフェルティティの胸像はどこにあるべきか","l":"egypt-new","x":"アマルナ美術の傑作として名高いのが、王妃ネフェルティティの彩色胸像である。1912年にドイツの調査隊がアマルナの彫刻家の工房跡で発見し、現在はベルリンの新博物館に展示されている。エ"},{"id":"egypt-new-t10","k":"myth","kj":"俗説","t":"「ファラオの呪い」","l":"egypt-new","x":"墓の発掘を資金面で支えたカーナヴォン卿が、発見の翌年に急死したことから、「王の眠りを妨げた者には死が訪れる」という「ファラオの呪い」の噂が新聞をにぎわせた。俗説しかし、カーナヴォン"},{"id":"egypt-new-t11","k":"source","kj":"史料","t":"夫を失った王妃の手紙","l":"egypt-new","x":"ヒッタイト王シュッピルリウマ1世の業績を、息子のムルシリ2世がまとめた記録に、不思議な話が残っている。エジプトの王が亡くなったころ、エジプトの王妃からヒッタイト王に手紙が届いたとい"},{"id":"egypt-new-t12","k":"trivia","kj":"こぼれ話","t":"引っ越したアブ＝シンベル神殿","l":"egypt-new","x":"ラメス2世は、エジプト各地に巨大な神殿や像を建てた。その代表が、ヌビアの岩山を掘り抜いて造られたアブ＝シンベル神殿である。入口には高さ約20mのラメス2世の座像が4体並ぶ。神殿の最"},{"id":"egypt-new-t13","k":"life","kj":"暮らし","t":"王を殺した後宮の陰謀","l":"egypt-new","x":"ラメス3世の最期については、裁判の記録（「後宮陰謀パピルス」）が残っている。王の側室の一人が、自分の息子を王位につけようと、後宮の女性や役人たちと陰謀をめぐらせたのである。陰謀にか"},{"id":"egypt-new-t14","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"egypt-new","x":"細川智栄子あんど芙〜みん『王家の紋章』（漫画、1976年〜連載）：古代エジプトの王子の墓を発掘した一家の娘キャロルが、古代エジプトにタイムスリップする物語。ヒッタイトやアッシリアな"},{"id":"egypt-old-t1","k":"trivia","kj":"こぼれ話","t":"増水を測る「ナイロメーター」","l":"egypt-old","x":"ナイル川の増水の高さは、その年の収穫を、そして税の額を決める重要な情報だった。増水が少なすぎれば畑に水が行き渡らず飢饉になり、多すぎれば村や堤防が流される。そこでエジプトでは、川の"},{"id":"egypt-old-t2","k":"source","kj":"史料","t":"ナルメルのパレット","l":"egypt-old","x":"上エジプトの古都ヒエラコンポリスの神殿跡から見つかった、高さ64センチの石の板である。化粧用の顔料をすりつぶすパレットの形をしているが、実用品ではなく、神殿に奉納された記念品だった"},{"id":"egypt-old-t3","k":"confuse","kj":"混同注意","t":"メソポタミアの王とエジプトの王","l":"egypt-old","x":"メソポタミアの王は、基本的に「神に選ばれた人間」であり、神の代理人として都市を治めた（アッカドのナラム＝シンのように自らを神とした王は例外である）。これに対してエジプトの王は、生ま"},{"id":"egypt-old-t4","k":"source","kj":"史料","t":"4500年前の業務日誌――メレルのパピルス","l":"egypt-old","x":"2013年、紅海に面したワディ・アル＝ジャルフという古代の港の跡で、フランスとエジプトの調査隊が、パピルスの束を発見した。世界最古の文字の書かれたパピルスである。そのなかに、クフ王"},{"id":"egypt-old-t5","k":"myth","kj":"俗説","t":"ピラミッドは奴隷が造った？","l":"egypt-old","x":"ピラミッドは、王に鞭打たれた何十万人もの奴隷が造らされた――。このイメージは、ヘロドトスが「10万人が3か月交代で20年かけて造った」と書いたことや、映画などの影響で広まった。しか"},{"id":"egypt-old-t6","k":"debate","kj":"諸説あり","t":"ピラミッドは何のために造られたのか","l":"egypt-old","x":"ピラミッドは王の墓である、というのが一般的な考え方である。王の遺体を納めるための墓室があり、周囲には王の魂をまつる葬祭殿が設けられた。ピラミッドの形は、太陽の光が天から地上に降り注"},{"id":"egypt-old-t7","k":"source","kj":"史料","t":"「上エジプト全土が飢えで死にかけていた」","l":"egypt-old","x":"第1中間期の上エジプトの州侯アンクティフィは、自分の墓に、自らの功績をたたえる碑文を残している。そこには、こんな一節がある。「上エジプト全土が飢えで死にかけていた。人々は自分の子ど"},{"id":"fall-west-rome-t1","k":"source","kj":"史料","t":"「西のローマの帝国は滅びた」","l":"fall-west-rome","x":"都の建設から709年目に、最初のアウグストゥスであるオクタウィアヌス＝アウグストゥスが治め始めたローマ人の西の帝国は、このアウグストゥルスとともに滅びた。以後、ゴート人の王たちがロ"},{"id":"fall-west-rome-t2","k":"debate","kj":"諸説あり","t":"西ローマ帝国はいつ滅びたのか","l":"fall-west-rome","x":"476年の「滅亡」には、いくつもの留保がつく。476年に廃位されたロムルスは、東ローマ帝国からは正式な皇帝と認められていなかった。東ローマが認めていた西方の皇帝は、ダルマティアに逃"},{"id":"fall-west-rome-t3","k":"trivia","kj":"こぼれ話","t":"ローマ滅亡の原因は210通り","l":"fall-west-rome","x":"ローマ帝国（西ローマ帝国）がなぜ滅びたのかは、歴史学で最も多く論じられてきた問題の一つである。18世紀のイギリスの歴史家ギボンは、大著『ローマ帝国衰亡史』（1776〜1789年）で"},{"id":"fall-west-rome-t4","k":"source","kj":"史料","t":"「この男には骨がない」","l":"fall-west-rome","x":"オドアケルが「神はどこにいるのか」と叫ぶと、テオドリックは剣を振り下ろし、鎖骨から腰まで切り裂いた。そして、こう言ったという。「まったく、この悪党には骨というものがなかった。」出典"},{"id":"fall-west-rome-t5","k":"person","kj":"人物","t":"ボエティウス――獄中の哲学者","l":"fall-west-rome","x":"ボエティウス（480年ごろ〜524年ごろ）は、ローマの名門貴族の出身で、テオドリックのもとで最高の官職にまで昇った。彼は、プラトンとアリストテレスの著作をすべてラテン語に翻訳する計"},{"id":"fall-west-rome-t6","k":"trivia","kj":"こぼれ話","t":"消された王の宮廷","l":"fall-west-rome","x":"ラヴェンナのサンタポリナーレ・ヌオーヴォ聖堂は、テオドリックが、アリウス派の宮廷教会として建てた聖堂である。その壁面には、テオドリックの宮殿を描いたモザイク画がある。東ローマ帝国が"},{"id":"fall-west-rome-t7","k":"works","kj":"作品紹介","t":"この時代にまつわる作品","l":"fall-west-rome","x":"ギボン『ローマ帝国衰亡史』（1776〜1789年）：五賢帝の時代から1453年のコンスタンティノープル陥落までを描いた大著。近代的な歴史叙述の古典とされ、「衰亡（デクライン＝アンド"},{"id":"feudalism-t1","k":"person","kj":"人物","t":"閉じこもった修道女ヴィボラーダ","l":"feudalism","x":"926年、マジャール人が、スイスのザンクト・ガレン修道院に迫った。修道院の近くでは、ヴィボラーダという女性が、小さな庵に自ら閉じこもって、祈りの生活を送っていた。マジャール人の襲撃"},{"id":"feudalism-t2","k":"trivia","kj":"こぼれ話","t":"ソールズベリーの誓い","l":"feudalism","x":"ノルマン人に征服されたイングランドでは、事情が少し異なっていた。ウィリアム1世（→「ノルマン人の移動」の回）は、1086年、ソールズベリーに国中の主な土地保有者を集めて、自分の直接"},{"id":"feudalism-t3","k":"source","kj":"史料","t":"修道院の財産目録","l":"feudalism","x":"9世紀前半、パリのサン・ジェルマン・デ・プレ修道院の院長イルミノンは、修道院がパリ周辺の各地に持つ荘園の土地と農民、その負担を、詳しく記録させた。これが「イルミノンの所領明細帳」で"},{"id":"feudalism-t4","k":"myth","kj":"俗説","t":"「初夜権」はあったのか","l":"feudalism","x":"中世ヨーロッパの領主は、農奴の結婚の際、花嫁と最初の夜を過ごす権利（初夜権）を持っていた、という話が、よく語られる。しかし、中世の西ヨーロッパで、こうした権利が実際に行使されたこと"},{"id":"feudalism-t5","k":"debate","kj":"諸説あり","t":"「封建制」とは何か","l":"feudalism","x":"「封建制」という言葉は、実は、中世の人々が使った言葉ではない。17〜18世紀のヨーロッパの法学者や思想家たちが、中世の社会のしくみをまとめて呼ぶために作った言葉である。この言葉は、"},{"id":"first-villages-t1","k":"trivia","kj":"こぼれ話","t":"顔を塗り込めた頭骨","l":"first-villages","x":"イェリコなどの新石器時代の遺跡からは、不思議なものが見つかっている。死者の頭骨に石膏を塗って顔の肉付けをし、目の部分に貝殻をはめ込んだ「漆喰頭骨」である。家の床下に葬られた死者の頭"},{"id":"first-villages-t2","k":"debate","kj":"諸説あり","t":"平等な社会だったのか","l":"first-villages","x":"チャタル＝ヒュユクの家々は、大きさも作りもほとんど同じで、特別に大きな屋敷や神殿のような建物は見つかっていない。人骨の分析でも、男女の食べ物や体格に大きな差はなかったという。そのた"},{"id":"first-villages-t3","k":"trivia","kj":"こぼれ話","t":"世界最古の土器は日本と中国で生まれた","l":"first-villages","x":"土器は、農耕とともに西アジアで生まれたと思われがちだが、実は最古の土器は東アジアで見つかっている。中国江西省の仙人洞遺跡では約2万年前の、日本の青森県・大平山元（おおだいやまもと）"},{"id":"first-villages-t4","k":"trivia","kj":"こぼれ話","t":"240キロ先から運ばれた石","l":"first-villages","x":"ストーンヘンジの内側に並ぶ「ブルーストーン」と呼ばれる石は、約240キロメートル離れたウェールズの山地から運ばれてきたことが、岩石の分析で分かっている。重さは1個あたり2〜4トンも"},{"id":"first-villages-t5","k":"life","kj":"暮らし","t":"アイスマンの持ち物と最後の食事","l":"first-villages","x":"アイスマンは、身長160センチほど、40代半ばの男性だった。毛皮の帽子をかぶり、何種類もの動物の皮を縫い合わせた服を着て、干し草を詰めた革の靴を履いていた。持ち物は、銅の刃をつけた"},{"id":"first-villages-t6","k":"source","kj":"史料","t":"殺人事件だった","l":"first-villages","x":"発見から10年後の2001年、エックス線写真の再調査で、アイスマンの左肩に石の矢じりが刺さっていたことが分かった。矢は背後から放たれ、肩の動脈を傷つけていた。彼は出血多量で、短い時"},{"id":"first-villages-t7","k":"source","kj":"史料","t":"1万年前の虐殺の跡――ナタルク遺跡","l":"first-villages","x":"ケニアのトゥルカナ湖の西にあるナタルク遺跡では、約1万年前の、少なくとも27人の人骨が見つかっている。そのうち多くの骨には、頭を棍棒のようなもので殴られた跡や、矢じりが刺さった跡が"},{"id":"first-villages-t8","k":"trivia","kj":"こぼれ話","t":"世界最古の金の宝飾品――ヴァルナの墓地","l":"first-villages","x":"ブルガリアの黒海沿岸の町ヴァルナでは、前4600〜前4200年ごろの墓地が見つかっている。その中のある墓には、金の腕輪や首飾り、王笏（おうしゃく）のような飾りなど、合わせて1キログ"},{"id":"former-han-t1","k":"myth","kj":"俗説","t":"少女の嘆願と肉刑の廃止","l":"former-han","x":"前167年、ある地方の役人が罪を犯して、肉刑（鼻を削ぐ、足を切るなど、体を傷つける刑罰）を受けることになった。その末娘の緹縈（ていえい）は、父とともに都の長安に行き、文帝に上書した"},{"id":"former-han-t2","k":"source","kj":"史料","t":"武帝が受け継いだ富","l":"former-han","x":"漢が興って70年余りの間、国家は無事で、水害や日照りにも遭わなければ、民はみな家々に十分な蓄えがあった。……都の銭は巨万を重ね、銭を通す紐が腐って、数えることもできなくなった。国の"},{"id":"former-han-t3","k":"debate","kj":"諸説あり","t":"武帝は儒学を「国教」にしたのか","l":"former-han","x":"教科書では、武帝が董仲舒の献策によって「儒学を官学化した」と説明される。しかし、近年の研究では、武帝の時代に儒学が他の学派を排除して国家の唯一の正統な学問になったわけではない、とす"},{"id":"former-han-t4","k":"trivia","kj":"こぼれ話","t":"元号のはじまり","l":"former-han","x":"「令和」「平成」のような元号（年号）も、武帝の時代に始まった。それまでは、皇帝の即位から何年目と数えていたが、武帝の時代に、「建元」「元光」など、めでたい言葉を年の名前につけるよう"},{"id":"former-han-t5","k":"now","kj":"いま","t":"「滇王之印」と「漢委奴国王」","l":"former-han","x":"前109年、漢に服属した滇の王は、武帝から、「滇王之印」と刻まれた金印を授けられた（『史記』西南夷列伝）。1956年、雲南省の石寨山（せきさいざん）の古墓群から、この記述どおりの、"},{"id":"former-han-t6","k":"confuse","kj":"混同注意","t":"武帝の財政政策","l":"former-han","x":"政策内容ねらい塩・鉄・酒の専売塩と鉄（前119年）、酒（前98年）の生産・販売を国家が独占大商人や豪族が得ていた莫大な利益を国家が吸収均輸法地方から税として納められる特産物を、国家"},{"id":"former-han-t7","k":"source","kj":"史料","t":"塩鉄論――国家は民と利益を争うべきか","l":"former-han","x":"武帝の死後の前81年、朝廷では、塩・鉄の専売などの財政政策を続けるべきかどうかについて、大論争が行われた。その記録は、のちに桓寛によって『塩鉄論』にまとめられた。地方から推薦されて"},{"id":"four-kingdoms-t1","k":"confuse","kj":"混同注意","t":"四王国を整理する","l":"four-kingdoms","x":"国名中心地都民族・王朝滅亡エジプト（サイス朝）ナイル川流域サイスエジプト人（第26王朝）前525年、アケメネス朝に征服されるリディア小アジア西部サルデスインド＝ヨーロッパ語系前54"},{"id":"four-kingdoms-t2","k":"confuse","kj":"混同注意","t":"「最初の貨幣」はどこか","l":"four-kingdoms","x":"「リディアが最初の金属貨幣を作った」というのは、西アジア・地中海世界の硬貨についての話である。中国では、殷の時代から、南の海でとれる子安貝が貨幣として使われていた（「貨」「財」「買"},{"id":"four-kingdoms-t3","k":"source","kj":"史料","t":"「大きな帝国が滅びるであろう」","l":"four-kingdoms","x":"前6世紀半ば、クロイソスは、東で急速に力をつけていたペルシアのキュロス2世を攻めるべきか迷い、ギリシアのデルフォイのアポロン神殿に、莫大な贈り物とともに使者を送って神託をうかがった"},{"id":"four-kingdoms-t4","k":"trivia","kj":"こぼれ話","t":"日食が終わらせた戦争","l":"four-kingdoms","x":"メディアとリディアの戦争は5年間続いた。ヘロドトスによれば、6年目の戦いの最中、突然、昼が夜に変わった。両軍は恐れおののいて戦いをやめ、和平を結んだ。ハリュス川を両国の国境とし、リ"},{"id":"four-kingdoms-t5","k":"myth","kj":"俗説","t":"バベルの塔と空中庭園","l":"four-kingdoms","x":"エテメンアンキは、「天と地の基礎の家」という意味で、高さ約90mの7層の塔だったと推定されている。旧約聖書の「バベルの塔」の物語――天に届く塔を建てようとした人間の傲慢さに怒った神"},{"id":"four-kingdoms-t6","k":"now","kj":"いま","t":"ベルリンにあるイシュタル門","l":"four-kingdoms","x":"バビロンの遺跡は、1899年から1917年にかけてドイツの調査隊が発掘した。イシュタル門の彩釉煉瓦の破片は、ドイツに運ばれて組み立て直され、現在はベルリンのペルガモン博物館に、高さ"},{"id":"four-kingdoms-t7","k":"trivia","kj":"こぼれ話","t":"「最初の考古学者」","l":"four-kingdoms","x":"ナボニドゥスは、古い神殿を修理するとき、その土台を掘り返して、昔の王たちが埋めた建設記念の碑文を探させた。そして、見つかった碑文を読み、それが何年前の王のものかを書き記している。た"},{"id":"four-kingdoms-t8","k":"trivia","kj":"こぼれ話","t":"アブ＝シンベルに残るギリシア人の落書き","l":"four-kingdoms","x":"前592年ごろ、サイス朝の王プサメティコス2世は、南のヌビア（クシュ）に遠征した。この遠征に参加したギリシア人傭兵たちは、帰り道に立ち寄ったアブ＝シンベル神殿で、ラメス2世の巨大な"},{"id":"four-kingdoms-t9","k":"trivia","kj":"こぼれ話","t":"人類最初の言葉は何語か","l":"four-kingdoms","x":"ヘロドトスは、サイス朝の初代の王プサメティコス1世について、こんな話を伝えている。王は、人類で最も古い民族はどれかを知るために、生まれたばかりの赤ん坊二人を羊飼いに預け、誰も言葉を"},{"id":"franks-t1","k":"trivia","kj":"こぼれ話","t":"ナポレオンのミツバチ","l":"franks","x":"1653年、現在のベルギーのトゥルネーで、教会の工事をしていた職人が、古い墓を掘り当てた。中からは、金の装身具や剣、数百枚の金貨・銀貨、そして「キルデリク王の（印章）」（CHILD"},{"id":"franks-t2","k":"source","kj":"史料","t":"ソワソンの壺","l":"franks","x":"トゥールのグレゴリウスは、クローヴィスについて、次のような話を伝えている。486年、ソワソンの戦いの後、フランクの兵士たちは、教会から奪った戦利品を分けることになった。その中に、美"},{"id":"franks-t3","k":"myth","kj":"俗説","t":"天から届いた聖油","l":"franks","x":"9世紀のランスの大司教ヒンクマールは、クローヴィスの洗礼の時、聖油を運ぶ役目の者が群衆にはばまれて間に合わなかったので、レミギウスが祈ると、白い鳩が、天から聖油の入った小瓶をくわえ"},{"id":"franks-t4","k":"trivia","kj":"こぼれ話","t":"「キツネ」と呼んだら罰金","l":"franks","x":"サリカ法典には、悪口に対する罰金も定められている。人を「キツネ」や「ウサギ」と呼んだ場合は3ソリドゥス、戦場で盾を投げ捨てて逃げたと、根拠もなく言いふらした場合も3ソリドゥスであっ"},{"id":"franks-t5","k":"person","kj":"人物","t":"二人の王妃――ブルンヒルドとフレデグンド","l":"franks","x":"6世紀後半のフランク王国では、二人の王妃の争いが、40年以上にわたって王国を揺るがした。アウストラシア王シギベルト1世の妃ブルンヒルドは、西ゴート王国の王女で、教養が高く、気性の激"},{"id":"franks-t6","k":"debate","kj":"諸説あり","t":"「ヨーロッパを救った戦い」だったのか","l":"franks","x":"18世紀のイギリスの歴史家ギボンは、『ローマ帝国衰亡史』の中で、もしフランク軍が敗れていたら、と想像して、次のように書いた。おそらく今ごろは、オックスフォードの学校で『クルアーン』"},{"id":"franks-t7","k":"myth","kj":"俗説","t":"「コンスタンティヌスの寄進状」","l":"franks","x":"ピピンの寄進と同じころ、ローマ教会では、1通の文書が作られたと考えられている。それは、4世紀のローマ皇帝コンスタンティヌス1世が、重い病気を治してくれた教皇シルウェステル1世に感謝"},{"id":"franks-t8","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"franks","x":"トゥールのグレゴリウス『歴史十書（フランク史）』：メロヴィング朝の歴史を知るための最も重要な史料。日本語訳に、兼岩正夫・臺幸夫訳（東海大学出版会）、杉本正俊訳（新評論）がある。オー"},{"id":"germanic-migration-t1","k":"source","kj":"史料","t":"タキトゥス『ゲルマニア』が描くゲルマン人","l":"germanic-migration","x":"小さなことは首長たちが相談し、大きなことは全員が相談する。……集会に出席した人々は、武装したまま座る。……提案が気に入らなければ、ざわめきによって退け、気に入れば、槍を打ち鳴らす。"},{"id":"germanic-migration-t2","k":"source","kj":"史料","t":"犬と引き換えの子どもたち","l":"germanic-migration","x":"将軍たちは、恥ずべき欲に駆られて、……飢えに苦しむゴート人から、犬を手に入れられるだけ手に入れ、犬1匹と引き換えに奴隷1人を取った。その中には、首長の息子たちまで連れ去られた者がい"},{"id":"germanic-migration-t3","k":"source","kj":"史料","t":"ヒエロニムスの嘆き","l":"germanic-migration","x":"全世界を征服した都が、征服された。……世界の光は消え、ローマ帝国の頭は切り落とされた。出典：ヒエロニムス『書簡』第127・エゼキエル書注解序文（412年ごろ）（本サイト訳）ヒエロニ"},{"id":"germanic-migration-t4","k":"trivia","kj":"こぼれ話","t":"川の底に眠る王","l":"germanic-migration","x":"アラリックは、ローマを略奪した後、さらに南へ進んでアフリカへ渡ろうとしたが、船団が嵐で失われ、まもなく南イタリアのコゼンツァで病死した。6世紀のゴート人の歴史家ヨルダネスによれば、"},{"id":"germanic-migration-t5","k":"trivia","kj":"こぼれ話","t":"「ヴァンダリズム」の誕生","l":"germanic-migration","x":"英語やフランス語で、公共物や文化財を破壊する行為を「ヴァンダリズム」という。これは、1794年、フランス革命のさなかに、聖職者で政治家のグレゴワールが、革命派の民衆による教会や美術"},{"id":"germanic-migration-t6","k":"trivia","kj":"こぼれ話","t":"地名に残るゲルマン人","l":"germanic-migration","x":"ゲルマン人の部族の名前は、ヨーロッパの地名に残っている。フランス：「フランク人の国」に由来する。イングランド：「アングル人の土地」に由来する。ロンバルディア（北イタリアの州）：ラン"},{"id":"germanic-migration-t7","k":"myth","kj":"俗説","t":"アーサー王は実在したのか","l":"germanic-migration","x":"アングロ＝サクソン人の侵入に抵抗したブリトン人の英雄として語られるのが、アーサー王である。円卓の騎士や聖剣エクスカリバーの物語で知られる。しかし、アーサー王の名は、同時代の史料には"},{"id":"germanic-migration-t8","k":"debate","kj":"諸説あり","t":"「大移動」か「変容」か","l":"germanic-migration","x":"ドイツ語では、この時代のゲルマン人の移動を「民族の移動（フェルカーヴァンデルング）」と呼び、フランス語やイタリア語では「蛮族の侵入」と呼ぶ。同じ出来事が、ゲルマン人の子孫を自認する"},{"id":"germanic-migration-t9","k":"works","kj":"作品紹介","t":"この時代にまつわる作品","l":"germanic-migration","x":"『ニーベルンゲンの歌』（13世紀初め）：ドイツの英雄叙事詩。後半では、ブルグンド人の王たちが、フン人の王エッツェルの宮廷で滅ぼされる。437年に、ブルグンド王国が、ローマの将軍アエ"},{"id":"gracchi-t1","k":"source","kj":"史料","t":"「野の獣にさえ穴がある」","l":"gracchi","x":"プルタルコスは、ティベリウスが民衆に向かって行った演説を、次のように伝えている。イタリアをさまよう野の獣でさえ、それぞれ巣穴を持ち、身を休める場所がある。ところが、イタリアのために"},{"id":"gracchi-t2","k":"confuse","kj":"混同注意","t":"閥族派と平民派","l":"gracchi","x":"閥族派（オプティマテス）平民派（ポプラレス）意味「最良の人々」「民衆の側に立つ人々」基盤元老院民会・護民官、無産市民主張元老院の伝統的な権威を守る土地分配・穀物配給など民衆の利益主"},{"id":"gracchi-t3","k":"view","kj":"視点を変える","t":"改革がもたらしたもの――「将軍の軍隊」","l":"gracchi","x":"マリウスの改革は、ローマ軍を強くしたが、同時に、共和政を内側から壊す危険な種もまいた。兵士たちにとって、退役後に土地をもらえるかどうかは、自分を率いる将軍が、その約束を元老院に認め"},{"id":"gracchi-t4","k":"person","kj":"人物","t":"若きカエサルとスッラ","l":"gracchi","x":"スッラの公敵宣告のとき、まだ18歳ほどの若者だったカエサルも、命を狙われた。カエサルは、マリウスの妻の甥であり、マリウス派の有力者キンナの娘を妻としていた。スッラはカエサルに妻との"},{"id":"gracchi-t5","k":"view","kj":"視点を変える","t":"英雄としてのスパルタクス","l":"gracchi","x":"スパルタクスは、のちの時代に、抑圧された人々の解放の象徴として語られるようになった。マルクスは、スパルタクスを「古代の歴史全体の中で最も素晴らしい人物」と評した。第一次世界大戦の末"},{"id":"greek-culture-t1","k":"confuse","kj":"混同注意","t":"オリンポスの主な神々（ローマの神々との対応）","l":"greek-culture","x":"ギリシアの神つかさどるものローマの神英語ゼウス天空・最高神ユピテルジュピター（木星）ヘラ結婚・ゼウスの妻ユノジュノー（June）ポセイドン海ネプトゥヌスネプチューン（海王星）アテナ"},{"id":"greek-culture-t2","k":"confuse","kj":"混同注意","t":"「万物の根源（アルケー）」を探した人々","l":"greek-culture","x":"哲学者出身万物の根源タレスミレトス水アナクシマンドロスミレトス無限なもの（ト＝アペイロン）アナクシメネスミレトス空気ヘラクレイトスエフェソス火。「万物は流転する」ピタゴラスサモス（"},{"id":"greek-culture-t3","k":"trivia","kj":"こぼれ話","t":"日食を予言し、井戸に落ちた哲学者","l":"greek-culture","x":"タレスには、さまざまな逸話が伝えられている。前585年の日食を予言したという話（2-11）のほか、エジプトでピラミッドの影の長さを測り、自分の影の長さと身長の比を使ってピラミッドの"},{"id":"greek-culture-t4","k":"source","kj":"史料","t":"「無知の知」と「よく生きること」","l":"greek-culture","x":"デルフォイの神託は、「ソクラテスより知恵のある者はいない」と告げた。驚いたソクラテスは、知恵があると評判の政治家や詩人、職人を訪ねて問答し、彼らが、本当は知らないことを知っていると"},{"id":"greek-culture-t5","k":"source","kj":"史料","t":"「吟味されない生は、生きるに値しない」","l":"greek-culture","x":"裁判で、ソクラテスは、哲学をやめれば釈放してやると言われても、こう答えたとプラトンは伝えている。私は、息をしているかぎり、知を愛し求めること（哲学）をやめないだろう。……吟味されな"},{"id":"greek-culture-t6","k":"trivia","kj":"こぼれ話","t":"1万人に届く声","l":"greek-culture","x":"ペロポネソス半島のエピダウロスには、前4世紀に造られた野外劇場が、ほぼ完全な形で残っている。約1万4000人を収容できるこの劇場は、音響のよさで有名で、舞台の中央で落としたコインの"},{"id":"greek-culture-t7","k":"view","kj":"視点を変える","t":"ギリシア彫刻は白かったか","l":"greek-culture","x":"大理石のギリシア彫刻やパルテノン神殿は、白く輝く美しさで知られる。18世紀のドイツの美術史家ヴィンケルマンは、その「高貴な単純と静かな偉大」をたたえ、白い大理石の彫刻こそが美の理想"},{"id":"greek-life-t1","k":"source","kj":"史料","t":"「女性の名誉は、話題にされないこと」","l":"greek-life","x":"ペリクレスは、トゥキディデスが伝える葬送演説の最後で、戦死者の妻たちに次のように語りかけている。女性の最大の名誉は、女性としての本性に劣らぬことであり、また、ほめられるにせよ、けな"},{"id":"greek-life-t2","k":"view","kj":"視点を変える","t":"自由と奴隷制は矛盾しなかったのか","l":"greek-life","x":"現代の私たちから見ると、「自由」と「平等」を掲げる民主政が、多数の奴隷の存在と両立していたことは、大きな矛盾に見える。しかし、多くのギリシア人にとって、それは矛盾ではなかった。哲学"},{"id":"greek-life-t3","k":"trivia","kj":"こぼれ話","t":"陶器に描かれた暮らし","l":"greek-life","x":"私たちがギリシア人の暮らしをよく知ることができるのは、陶器の絵のおかげである。アテネの陶器には、神話の場面だけでなく、酒宴、運動競技、学校の授業、機織り、市場の買い物、結婚式など、"},{"id":"greek-life-t4","k":"life","kj":"暮らし","t":"死者への渡し賃","l":"greek-life","x":"ギリシア人は、死者の魂は冥界に行き、冥界の川（ステュクス川・アケロン川）を渡し守カロンの舟で渡ると考えた。そのため、死者の口の中に、渡し賃として1オボロスの硬貨を入れて葬る習慣があ"},{"id":"gupta-t1","k":"trivia","kj":"こぼれ話","t":"鉄柱に背中を向けて抱きつくと……","l":"gupta","x":"デリーの鉄柱には、柱に背中をつけて両腕を後ろに回し、手と手を結ぶことができれば願いがかなう、という言い伝えがあった俗説。多くの観光客が試したため、柱の下の部分は人々の手でこすられて"},{"id":"gupta-t2","k":"source","kj":"史料","t":"アラーハーバード石柱碑文","l":"gupta","x":"碑文は、サムドラグプタの征服を、地域ごとに異なる扱いをしたものとして描いている。（王は）アーリヤーヴァルタ（北インド）の王たち、ルドラデーヴァ、マティラ……らを力ずくで根こそぎにし"},{"id":"gupta-t3","k":"myth","kj":"俗説","t":"兄の妃を救った王――ラーマグプタの伝説","l":"gupta","x":"6世紀ごろに書かれた戯曲『デーヴィーチャンドラグプタム』（現在は断片だけが伝わる）は、次のような物語を伝えている伝承。サムドラグプタの死後、王位を継いだのは、チャンドラグプタ2世の"},{"id":"gupta-t4","k":"source","kj":"史料","t":"法顕『仏国記』が記すインド","l":"gupta","x":"法顕は、ガンジス川流域の「中国」（インドの中心の地方の意味）について、次のように記している。人々は豊かで楽しく暮らしている。戸籍や役所の煩わしい決まりはなく、王の土地を耕す者だけが"},{"id":"gupta-t5","k":"trivia","kj":"こぼれ話","t":"800年間修理され続けたダム","l":"gupta","x":"インド西部のグジャラート地方のジュナーガドには、大きな岩に3つの時代の碑文が刻まれている。1つ目は、前3世紀のアショーカ王の詔勅である。2つ目は、150年ごろ、西クシャトラパの王ル"},{"id":"gupta-t6","k":"debate","kj":"諸説あり","t":"フーナとエフタル","l":"gupta","x":"日本の世界史の教科書では、グプタ朝を衰退させた遊牧民を「エフタル」と記すことが多い。エフタルは、5世紀に中央アジアのアフガニスタン北部を中心に大国を築き、ササン朝と争った遊牧民であ"},{"id":"gupta-t7","k":"source","kj":"史料","t":"『マヌ法典』が説く女性の地位","l":"gupta","x":"『マヌ法典』には、次のような一節がある。少女であれ、若い女であれ、老いた女であれ、家の中のことであっても、何事も独立して行ってはならない。少女の時は父に、若い時は夫に、夫が死んだ後"},{"id":"gupta-t8","k":"trivia","kj":"こぼれ話","t":"東南アジアに広がった『ラーマーヤナ』","l":"gupta","x":"『ラーマーヤナ』の物語は、インドから東南アジアに伝わり、各地で独自の形に作り変えられた。タイでは『ラーマキエン』、インドネシアのジャワ島では影絵芝居（ワヤン・クリ）や舞踊劇の題材と"},{"id":"gupta-t9","k":"trivia","kj":"こぼれ話","t":"燃え続けた図書館","l":"gupta","x":"ナーランダー僧院には、「ダルマガンジャ」（法の市場）と呼ばれる図書館があり、9階建ての建物を含む3つの大きな建物に、膨大な経典が収められていたと伝えられる伝承。12世紀末、イスラー"},{"id":"gupta-t10","k":"source","kj":"史料","t":"ゲーテとシャクンタラー","l":"gupta","x":"『シャクンタラー』は、18世紀末に英語に翻訳され、ヨーロッパで大きな反響を呼んだ。ドイツの詩人ゲーテは、1791年、この作品をたたえて次のような短い詩を書いた。若い年の花と、熟した"},{"id":"gupta-t11","k":"debate","kj":"諸説あり","t":"最古の「ゼロ」はどれか","l":"gupta","x":"ゼロの記号がいつ生まれたのかについては、はっきりしたことはわかっていない。インド国内で、年代が確実な最古のゼロの例は、中部インドのグワーリヤルの寺院の碑文（876年）に刻まれた「2"},{"id":"gupta-t12","k":"trivia","kj":"こぼれ話","t":"法隆寺の壁画の焼失と文化財保護法","l":"gupta","x":"奈良の法隆寺の金堂には、7世紀末から8世紀初めに描かれた仏教の壁画があった。その中の観音菩薩の姿は、アジャンターの蓮華手菩薩とよく似ており、インドのグプタ様式の影響が、シルクロード"},{"id":"gupta-t13","k":"term","kj":"用語","t":"グプタ文字と日本の梵字","l":"gupta","x":"グプタ朝の時代に使われたグプタ文字は、アショーカ王の碑文のブラーフミー文字から発達した文字である。グプタ文字から、6世紀ごろに「シッダマートリカー文字」（悉曇文字）が生まれ、さらに"},{"id":"gupta-t14","k":"trivia","kj":"こぼれ話","t":"天空の宮殿シーギリヤ","l":"gupta","x":"スリランカ中部のシーギリヤには、高さ約200mの巨大な岩山がそびえ、その頂上に宮殿の遺跡がある。5世紀後半、父王を殺して王位を奪ったカッサパ1世が、弟の報復を恐れて、この岩山の上に"},{"id":"gupta-t15","k":"now","kj":"いま","t":"現代インドとグプタ朝","l":"gupta","x":"グプタ朝の時代は、20世紀前半のインドの独立運動の時代に、インドの歴史家たちによって「インドの古典時代」「黄金時代」として高く評価された。イギリスの支配に対抗して、インド人が自らの"},{"id":"gupta-t16","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"gupta","x":"カーリダーサ『シャクンタラー姫』（辻直四郎訳、岩波文庫）：カーリダーサの代表作の日本語訳。『マハーバーラタ』（ピーター・ブルック演出）：イギリスの演出家ピーター・ブルックが、叙事詩"},{"id":"hammurabi-t1","k":"confuse","kj":"混同注意","t":"「最古の法典」ではない","l":"hammurabi","x":"ハンムラビ法典は、長い間「世界最古の法典」と紹介されてきた。しかし、前回見たウル＝ナンム法典（前21世紀）をはじめ、それより古い法典がいくつか見つかっており、現在では最古の法典では"},{"id":"hammurabi-t2","k":"source","kj":"史料","t":"ハンムラビ法典の条文から","l":"hammurabi","x":"第196条「もし人が、アヴィールム（自由人）の目をつぶしたならば、その人の目をつぶす」第197条「もし人が、アヴィールムの骨を折ったならば、その人の骨を折る」第198条「もし人が、"},{"id":"hammurabi-t3","k":"life","kj":"暮らし","t":"手抜き工事は死刑","l":"hammurabi","x":"建築に関する条文は、とくに厳しい。第229条「もし大工が人のために家を建て、その工事が堅固でなかったために家が倒れ、家の主人を死なせたならば、その大工は殺される」第230条「もし家"},{"id":"hammurabi-t4","k":"life","kj":"暮らし","t":"ビールの水増しは水に投げ込まれる","l":"hammurabi","x":"酒場（ビール店）の主人に関する条文もある。主人は多くの場合、女性だった。第108条では、ビールの代金を受け取るとき、麦で受け取るべきところを銀で受け取り、その際にビールの量をごまか"},{"id":"hammurabi-t5","k":"life","kj":"暮らし","t":"結婚と離婚――女性の権利","l":"hammurabi","x":"ハンムラビ法典には、結婚・離婚・相続についての条文も多い。結婚は、花婿の家が花嫁の家に結納金を払い、花嫁は実家から持参金を持って嫁ぐという形だった。注目すべきは、女性にも一定の権利"},{"id":"hammurabi-t6","k":"trivia","kj":"こぼれ話","t":"借金帳消しの「徳政令」","l":"hammurabi","x":"古代メソポタミアでは、不作の年などに借金を返せなくなり、自分や家族を奴隷として差し出す人が少なくなかった。ハンムラビ法典第117条では、借金のために妻や子を売ったり、人質に入れたり"},{"id":"hammurabi-t7","k":"trivia","kj":"こぼれ話","t":"世界最古の「苦情の手紙」","l":"hammurabi","x":"大英博物館には、前1750年ごろの粘土板の手紙がある。差出人はナンニという男で、宛先は銅の商人エア＝ナシルである。ナンニは、エア＝ナシルから質の悪い銅を売りつけられたことに腹を立て"},{"id":"han-society-t1","k":"confuse","kj":"混同注意","t":"儒学の五経","l":"han-society","x":"経典内容『易経』（『易』）占いの書。陰陽の組み合わせで世界の変化を説く『書経』（『尚書』）古代の帝王の言葉や記録『詩経』（『詩』）周代の歌謡を集めた詩集。孔子が編集したと伝えられる"},{"id":"han-society-t2","k":"source","kj":"史料","t":"「任安に報ずるの書」","l":"han-society","x":"司馬遷は、友人の任安に宛てた手紙の中で、宮刑を受けてもなお生き続けた理由を語っている。人は、もとより一度は死ぬものである。しかし、その死は、泰山よりも重いこともあれば、鴻毛（おおと"},{"id":"han-society-t3","k":"confuse","kj":"混同注意","t":"紀伝体と編年体","l":"han-society","x":"紀伝体編年体書き方人物の伝記（本紀・列伝など）を中心に、制度史（書・志）や年表（表）を組み合わせる出来事を年月の順に記す長所人物の生き方や、制度の移り変わりが分かりやすい同時に起き"},{"id":"han-society-t4","k":"now","kj":"いま","t":"馬王堆が語る漢代の暮らし","l":"han-society","x":"馬王堆の3つの墓からは、3000点を超える副葬品が出土した。中でも驚かされるのは、1号墓から出土した絹の衣服である。そのうちの1着の「素紗襌衣（そしゃたんい）」は、身丈128cm、"},{"id":"harsha-t1","k":"source","kj":"史料","t":"バーナ『ハルシャチャリタ』――燃え盛る火の前で","l":"harsha","x":"ハルシャ王の宮廷詩人バーナ（バーナバッタ）は、王の前半生を描いた伝記的な物語『ハルシャチャリタ』（ハルシャ王の事績）を、技巧を凝らした華麗なサンスクリット語の散文で書いた。バーナに"},{"id":"harsha-t2","k":"source","kj":"史料","t":"『大唐西域記』が記すハルシャ王の征服","l":"harsha","x":"王は東に征し西に討ち、従わない者を服属させた。象は鞍を解かず、兵は甲冑を脱がなかった。こうして6年のうちに、五インドの王たちを臣従させた。領土が広がると兵も増やし、象の軍は6万、騎"},{"id":"harsha-t3","k":"source","kj":"史料","t":"アイホーレ碑文――「歓喜」が溶けた王","l":"harsha","x":"プラケーシン2世の宮廷詩人ラヴィキールティは、634年、チャールキヤ朝の古い都アイホーレのジャイナ教寺院（メーグティ寺院）の壁に、王の功績をたたえるサンスクリット語の詩を刻んだ。こ"},{"id":"harsha-t4","k":"source","kj":"史料","t":"すべてを与えた王","l":"harsha","x":"643年、玄奘は、ハルシャ王に招かれて、プラヤーガでの6回目の無遮大会に参加した。玄奘の伝記によれば、この大会は75日間にわたって続いた。初日にはブッダの像が、2日目には太陽神の像"},{"id":"harsha-t5","k":"trivia","kj":"こぼれ話","t":"鳥の王に身を捧げた王子――『ナーガーナンダ』","l":"harsha","x":"ハルシャ王の作とされる戯曲『ナーガーナンダ』（竜たちの喜び）は、仏教の説話をもとにした作品である。主人公の王子ジームータヴァーハナは、神鳥ガルダが、毎日1匹ずつ竜（ナーガ、蛇の一族"},{"id":"harsha-t6","k":"trivia","kj":"こぼれ話","t":"太宗の陵墓に並んだインドの王","l":"harsha","x":"太宗の陵墓である昭陵（陝西省）には、太宗に従った周辺の国々の君主たち14人の石像が並べられた。突厥の可汗や、吐蕃のソンツェン＝ガンポ、新羅の真徳女王などと並んで、そこには、王玄策が"},{"id":"harsha-t7","k":"trivia","kj":"こぼれ話","t":"砂糖の作り方を学ぶ","l":"harsha","x":"『新唐書』によれば、647年、太宗は、インドのマガダ国に使者を送り、サトウキビの汁を煮詰めて砂糖を作る方法（熬糖法ごうとうほう）を学ばせた。そして、揚州（長江下流）から献上させたサ"},{"id":"harsha-t8","k":"debate","kj":"諸説あり","t":"玄奘はいつ出発したのか","l":"harsha","x":"玄奘自身が太宗に提出した上表文や、伝記『大慈恩寺三蔵法師伝』は、出発を貞観3年（629年）としている。日本の教科書なども、629年の出発とすることが多い。一方、玄奘は、旅の途中で、"},{"id":"harsha-t9","k":"source","kj":"史料","t":"玄奘が見たバーミヤーン","l":"harsha","x":"王城の東北の山の斜面に、石の立仏の像がある。高さは140〜150尺（約45m）で、金色に輝き、宝の飾りが光りまばゆい。……城の東2〜3里の寺には、仏が涅槃に入る（亡くなる）姿の臥像"},{"id":"harsha-t10","k":"trivia","kj":"こぼれ話","t":"3年間待っていた師","l":"harsha","x":"玄奘の伝記によれば、戒賢は、このとき100歳を超える高齢であった伝承。戒賢は、数年前から重い病に苦しみ、命を絶とうとまで考えていたが、夢の中に金色に輝く3人の天人が現れて、「東の大"},{"id":"harsha-t11","k":"trivia","kj":"こぼれ話","t":"インドで歌われていた唐の歌","l":"harsha","x":"カーマルーパの王は、玄奘にこう語ったという。「いまインドの国々では、マハーチーナ国（大唐）の『秦王破陣楽しんおうはじんらく』を歌う者が多い。久しく聞いてきたが、それはあなたの国のこ"},{"id":"harsha-t12","k":"source","kj":"史料","t":"燃え上がる楼閣と刺客","l":"harsha","x":"『大唐西域記』は、この大法会の時に起こった事件を記している。王は、ガンジス川の西に大きな寺を建て、その東に高さ100尺余りの宝の楼閣を建てて、王の背丈と同じ高さの金の仏像を安置した"},{"id":"harsha-t13","k":"person","kj":"人物","t":"太宗と玄奘","l":"harsha","x":"帰国した玄奘は、洛陽で太宗に会った。太宗は、ちょうど高句麗への遠征の準備のため、洛陽に来ていたのである（→「唐の成立と貞観の治」の回）。太宗は、玄奘がたどった西域やインドの国々の地"},{"id":"harsha-t14","k":"trivia","kj":"こぼれ話","t":"玄奘の遺骨の旅","l":"harsha","x":"玄奘の遺骨は、長安の郊外に葬られた後、唐末の戦乱の中で掘り出され、のちに南京に移されて寺に納められたと伝えられる。1942年、日中戦争中の南京で、日本軍が神社を建てるための工事をし"},{"id":"harsha-t15","k":"trivia","kj":"こぼれ話","t":"玄奘の記録で遺跡を掘り当てる","l":"harsha","x":"19世紀、フランスの東洋学者スタニスラス・ジュリアンが『大唐西域記』をフランス語に翻訳すると、それはインドの考古学に大きな影響を与えた。イギリス領インドの考古調査局の初代局長となっ"},{"id":"harsha-t16","k":"works","kj":"作品紹介","t":"『西遊記』――玄奘の旅から生まれた物語","l":"harsha","x":"玄奘の旅は、のちに多くの伝説を生んだ。宋の時代には、猿の行者が玄奘の旅を助ける物語『大唐三蔵取経詩話』が作られ、元の時代には劇として演じられた。こうした物語が、明の時代の16世紀に"},{"id":"harsha-t17","k":"trivia","kj":"こぼれ話","t":"上から掘り下げた寺院","l":"harsha","x":"エローラのカイラーサナータ寺院は、シヴァ神が住むとされるヒマラヤのカイラーサ山を表した寺院である。普通の建物は、下から石を積み上げて造る。しかし、この寺院は、玄武岩の崖を、上から下"},{"id":"harsha-t18","k":"now","kj":"いま","t":"現代のインドと中国と玄奘","l":"harsha","x":"玄奘は、現代のインドと中国の両国で、両国の交流の象徴として語られることが多い。ナーランダー僧院の遺跡の近くには、中国とインドの協力によって建てられた「玄奘記念館」があり、玄奘の遺骨"},{"id":"harsha-t19","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"harsha","x":"玄奘『大唐西域記』（水谷真成訳、平凡社東洋文庫・中国古典文学大系）：玄奘の旅行記の日本語の全訳。慧立・彦悰『玄奘三蔵――西域・インド紀行』（長澤和俊訳、講談社学術文庫）：玄奘の伝記"},{"id":"hebrews-t1","k":"confuse","kj":"混同注意","t":"ヘブライ人・イスラエル人・ユダヤ人","l":"hebrews","x":"同じ民族が、三つの名前で呼ばれる。ヘブライ人：主に周りの民族が彼らを呼んだ名。「（川の）向こうから来た者」の意味ともいわれるが、はっきりしない。イスラエル人：彼ら自身の呼び名。祖先"},{"id":"hebrews-t2","k":"debate","kj":"諸説あり","t":"出エジプトは史実か","l":"hebrews","x":"出エジプトの物語が史実かどうかは、長く議論されてきた諸説。エジプト側の記録には、ヘブライ人の大規模な脱出を記したものは見つかっていない。シナイ半島でも、数十万人もの人々が40年間さ"},{"id":"hebrews-t3","k":"source","kj":"史料","t":"聖書の外に現れた「イスラエル」","l":"hebrews","x":"聖書以外の史料に「イスラエル」の名が初めて現れるのは、ラメス2世の息子メルエンプタハの戦勝碑（前1208年ごろ）である。王がパレスチナで打ち破った相手を並べた中に、こう書かれている"},{"id":"hebrews-t4","k":"debate","kj":"諸説あり","t":"ダヴィデとソロモンの「大王国」","l":"hebrews","x":"旧約聖書は、ダヴィデとソロモンの王国を、エジプトの国境からユーフラテス川にまで及ぶ大王国として描いている。しかし、考古学の成果からは、当時のエルサレムは小さな町にすぎず、王国もずっ"},{"id":"hebrews-t5","k":"myth","kj":"俗説","t":"「失われた10部族」と日本","l":"hebrews","x":"連れ去られた北の10部族は、その後、各地の住民と混じり合い、独自の集団としては歴史から姿を消した。そのため、彼らは「失われた10部族」と呼ばれ、後世さまざまな伝説を生んだ。世界の各"},{"id":"hebrews-t6","k":"source","kj":"史料","t":"トンネルに残された碑文","l":"hebrews","x":"アッシリア軍の攻撃に備えて、ユダ王ヒゼキヤは、エルサレムの城壁の外にあった泉から、城内まで水を引くトンネルを掘らせた。包囲されても水に困らないようにするためである。1880年、この"},{"id":"hebrews-t7","k":"source","kj":"史料","t":"「バビロンの川のほとりに座り」","l":"hebrews","x":"バビロンの川のほとりに座り、シオンを思って、私たちは泣いた。そこの柳の木々に、私たちは竪琴を掛けた。私たちを捕らえて連れてきた者たちが、そこで歌をうたえと言ったからだ。「シオンの歌"},{"id":"hebrews-t8","k":"view","kj":"視点を変える","t":"一神教はどう生まれたか","l":"hebrews","x":"ヘブライ人も、はじめから唯一の神だけを信じていたわけではなかったようである。旧約聖書には、預言者たちが、民が周りの民族の神々（豊穣の神バアルなど）を拝むことを繰り返し非難する場面が"},{"id":"hebrews-t9","k":"now","kj":"いま","t":"エルサレム――三つの宗教の聖地","l":"hebrews","x":"エルサレムの旧市街は、1km四方ほどの小さな区域に、ユダヤ教・キリスト教・イスラームの聖地が集まっている。ユダヤ教の聖地「嘆きの壁」は、捕囚の後に再建され、のちにヘロデ王が大改築し"},{"id":"hellenistic-t1","k":"confuse","kj":"混同注意","t":"ヘレニズム三国と、その後","l":"hellenistic","x":"王国建国者中心地・都滅亡アンティゴノス朝マケドニアアンティゴノス2世マケドニア・ギリシア（都ペラ）前168年、ローマに敗れる（前148年に属州化）セレウコス朝シリアセレウコス1世シ"},{"id":"hellenistic-t2","k":"myth","kj":"俗説","t":"大図書館を焼いたのは誰か","l":"hellenistic","x":"アレクサンドリアの大図書館は、いつ、どのように失われたのか。これについては、さまざまな話が伝えられている。前48年、カエサルがアレクサンドリアで戦ったとき（3-17）、港の火事が燃"},{"id":"hellenistic-t3","k":"mech","kj":"しくみ","t":"アリスタルコスの太陽中心説","l":"hellenistic","x":"アリスタルコス（前3世紀前半）は、月が半月のときの太陽・月・地球の角度などから、太陽は地球よりはるかに大きいと計算した。そして、大きな太陽が小さな地球の周りを回るのは不自然だと考え"},{"id":"hellenistic-t4","k":"source","kj":"史料","t":"「われに支点を与えよ」","l":"hellenistic","x":"アルキメデスには、多くの逸話が伝えられている。シラクサの王から、新しく作らせた王冠に、金細工師が銀を混ぜてごまかしていないか調べるよう頼まれたアルキメデスは、公衆浴場の湯船に入った"},{"id":"hellenistic-t5","k":"confuse","kj":"混同注意","t":"ストア派とエピクロス派","l":"hellenistic","x":"ストア派エピクロス派創始者ゼノン（キプロス島出身）エピクロス理想理性によって情念を抑え、心を乱されないこと（アパテイア＝不動心）心の平静（アタラクシア）を得ること幸福自然＝理性（ロ"},{"id":"hellenistic-t6","k":"trivia","kj":"こぼれ話","t":"「日陰にしないでくれ」","l":"hellenistic","x":"ヘレニズム時代の少し前、アテネやコリントスに、樽（実際には大きな甕）の中に住み、ほとんど何も持たずに暮らした哲学者ディオゲネスがいた。社会の慣習や富を軽蔑し、自然のままに生きること"},{"id":"hellenistic-t7","k":"now","kj":"いま","t":"アフガニスタンのギリシア都市","l":"hellenistic","x":"1964年、アフガニスタン北部の、アム川（オクサス川）とコクチャ川の合流点にある遺跡アイ＝ハヌムで、フランスの調査隊が発掘を始めた。そこには、劇場、体育場（ギュムナシオン）、コリン"},{"id":"hellenistic-t8","k":"works","kj":"作品紹介","t":"この時代とつながる作品","l":"hellenistic","x":"魚豊『チ。―地球の運動について―』（漫画、2020〜2022年連載、手塚治虫文化賞マンガ大賞受賞、2024〜2025年アニメ化）：15世紀の「P王国」（ポーランドを思わせる架空の国"},{"id":"hittite-iron-t1","k":"confuse","kj":"混同注意","t":"「語族」は人種や民族ではない","l":"hittite-iron","x":"「インド＝ヨーロッパ語族」「セム語族」などの「語族」は、言葉の系統によるグループ分けであって、人種や血筋のまとまりではない。同じ語族の言葉を話していても、人々の祖先や見た目はさまざ"},{"id":"hittite-iron-t2","k":"trivia","kj":"こぼれ話","t":"「パンを食べ、水を飲むであろう」","l":"hittite-iron","x":"ヒッタイト人の言葉は、楔形文字で書かれていたため、文字は読めた。しかし、それがどんな言葉なのかは長いあいだ分からなかった。1915年、チェコの学者フロズニーは、次の一文に注目した。"},{"id":"hittite-iron-t3","k":"trivia","kj":"こぼれ話","t":"馬の調教マニュアルと、インドの神々","l":"hittite-iron","x":"ヒッタイトの文書の中に、キックリという人物が書いた、戦車用の馬の調教の手引きがある。約180日にわたって馬を走らせ、水を飲ませ、休ませる方法が細かく記されている。キックリは、ヒッタ"},{"id":"hittite-iron-t4","k":"source","kj":"史料","t":"「よい鉄は、今はない」","l":"hittite-iron","x":"あなたが手紙で求めてきたよい鉄は、キズワトナにある私の倉には、今はない。鉄を作るのによくない時期であると、私は書いた。よい鉄は作らせているが、まだ仕上がっていない。仕上がったら、あ"},{"id":"hittite-iron-t5","k":"now","kj":"いま","t":"日本の調査隊とアナトリアの鉄","l":"hittite-iron","x":"トルコ中部のカマン＝カレホユック遺跡では、1986年から日本の中近東文化センター（のちにアナトリア考古学研究所）の調査隊が発掘を続けている。この遺跡では、ヒッタイト以前の前2千年紀"},{"id":"hittite-iron-t6","k":"source","kj":"史料","t":"ラメス2世の「詩」","l":"hittite-iron","x":"ラメス2世は、この戦いを自分の大勝利として、カルナック・ルクソール・アビドス・アブ＝シンベル・ラメセウムなど各地の神殿の壁に、浮き彫りと長い詩で刻ませた。詩の中で、敵に囲まれた王は"},{"id":"hittite-iron-t7","k":"now","kj":"いま","t":"国連本部に飾られた条約","l":"hittite-iron","x":"この条約は、両国で別々の形で残っている。エジプトではヒエログリフでカルナック神殿などの壁に刻まれ、ヒッタイトではハットゥシャの文書庫から、アッカド語で書かれた粘土板が見つかった。も"},{"id":"hittite-iron-t8","k":"source","kj":"史料","t":"最後の手紙――ウガリト王の叫び","l":"hittite-iron","x":"シリアの港町ウガリトの遺跡からは、町が滅びる直前のものとみられる手紙が見つかっている。ウガリトの王アンムラピが、キプロス（アラシア）の王に書いた手紙である。わが父よ、ご覧ください。"},{"id":"hittite-iron-t9","k":"trivia","kj":"こぼれ話","t":"「パレスチナ」の名の由来","l":"hittite-iron","x":"海の民の一つに、エジプトの記録で「ペレセト」と呼ばれる集団がいる。彼らはその後、パレスチナの南の海岸地帯に住み着いた。『旧約聖書』に、イスラエル人の宿敵として登場するペリシテ人であ"},{"id":"hittite-iron-t10","k":"confuse","kj":"混同注意","t":"鉄器の「使用」と「普及」","l":"hittite-iron","x":"試験では、次の二つを区別しておきたい。鉄器を早くから使用した国 → ヒッタイト（前17〜前12世紀）鉄器が西アジアから地中海一帯に広く普及した時期 → ヒッタイト滅亡後の前12世紀"},{"id":"hittite-iron-t11","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"hittite-iron","x":"篠原千絵『天は赤い河のほとり』（漫画、1995〜2002年連載）：現代の日本の少女が、古代ヒッタイト帝国にタイムスリップする物語。ムルシリ2世の時代を舞台に、ヒッタイトとエジプト、"},{"id":"homo-sapiens-t1","k":"debate","kj":"諸説あり","t":"「アフリカ単一起源説」と「多地域進化説」","l":"homo-sapiens","x":"私たちの起源をめぐっては、長い論争があった。一つは、ホモ＝サピエンスはアフリカで生まれ、その後世界中に広がって、各地にいた原人や旧人と入れ替わったとするアフリカ単一起源説。もう一つ"},{"id":"homo-sapiens-t2","k":"trivia","kj":"こぼれ話","t":"世界最古級の「釣り針」は沖縄で見つかった","l":"homo-sapiens","x":"沖縄県南城市のサキタリ洞遺跡では、約2万3000年前の貝殻で作った釣り針が見つかっている。世界最古級の釣り針である。この遺跡からは、モクズガニなどを食べた跡も多数見つかっており、旧"},{"id":"homo-sapiens-t3","k":"debate","kj":"諸説あり","t":"花を手向けた？――シャニダール洞窟の埋葬","l":"homo-sapiens","x":"1950〜60年代、イラクのシャニダール洞窟で、ネアンデルタール人の埋葬人骨が見つかった。遺体の周りの土からは大量の花粉が検出され、「ネアンデルタール人は死者に花を手向けていた」と"},{"id":"homo-sapiens-t4","k":"trivia","kj":"こぼれ話","t":"私たちの中のネアンデルタール人","l":"homo-sapiens","x":"2010年、スウェーデン出身の遺伝学者スヴァンテ＝ペーボらの研究チームは、ネアンデルタール人の骨から取り出したDNAを解読し、驚くべき結果を発表した。アフリカ以外の現代人のDNAに"},{"id":"homo-sapiens-t5","k":"confuse","kj":"混同注意","t":"「人種」と人類の多様性","l":"homo-sapiens","x":"ホモ＝サピエンスが世界中に広がる過程で、それぞれの土地の環境に合わせて、肌の色などの見た目が変わっていった。たとえば、紫外線の強い地域では肌の色が濃く、弱い地域では薄くなった。しか"},{"id":"homo-sapiens-t6","k":"confuse","kj":"混同注意","t":"「クロマニョン人」は人種や種の名前ではない","l":"homo-sapiens","x":"「クロマニョン人」は、私たちと別の種の人類のように聞こえるが、そうではない。クロマニョン人は、ヨーロッパの後期旧石器時代に暮らしたホモ＝サピエンス、つまり私たちと同じ種の人々の呼び"},{"id":"homo-sapiens-t7","k":"debate","kj":"諸説あり","t":"7万4000年前の巨大噴火は人類を絶滅寸前に追い込んだ？","l":"homo-sapiens","x":"約7万4000年前、インドネシアのスマトラ島にあるトバ火山が、過去数百万年で最大級の噴火を起こした。噴き出した火山灰はインドにまで厚く降り積もり、その後、地球は数年にわたって寒冷化"},{"id":"homo-sapiens-t8","k":"trivia","kj":"こぼれ話","t":"行商の青年が見つけた日本の旧石器時代――岩宿遺跡","l":"homo-sapiens","x":"かつて、日本列島には旧石器時代の人類はいなかったと考えられていた。関東地方の赤土（関東ローム層）は、火山灰が積もった地層で、そのころは火山活動が激しく人は住めなかったと思われていた"},{"id":"homo-sapiens-t9","k":"now","kj":"いま","t":"旧石器捏造事件","l":"homo-sapiens","x":"日本の旧石器時代の研究には、大きな汚点もある。1970年代から、宮城県などで、ある考古学研究者が次々に「日本最古」の石器を発見し、日本列島の人類の歴史は60万年前、70万年前とさか"},{"id":"human-origins-t1","k":"trivia","kj":"こぼれ話","t":"日本人研究者も発見に加わった「ラミダス猿人」","l":"human-origins","x":"1990年代、エチオピアで約440万年前の人類の化石が見つかり、アルディピテクス＝ラミダス（ラミダス猿人）と名づけられた。調査チームには東京大学の諏訪元（すわ・げん）も加わっており"},{"id":"human-origins-t2","k":"trivia","kj":"こぼれ話","t":"「ルーシー」の名はビートルズの曲から","l":"human-origins","x":"1974年、エチオピアのアファール地方で、アウストラロピテクス＝アファレンシスの全身の約40パーセントにあたる骨が見つかった。約318万年前の若い女性の骨である。発見を祝ってキャン"},{"id":"human-origins-t3","k":"source","kj":"史料","t":"366万年前の足跡――ラエトリ","l":"human-origins","x":"1978年、タンザニアのラエトリで、イギリスの考古学者メアリー＝リーキーの調査隊が、火山灰の上に残された人類の足跡の列を発見した。約366万年前、近くの火山が噴火して降り積もった灰"},{"id":"human-origins-t4","k":"trivia","kj":"こぼれ話","t":"北京原人の化石は戦争で行方不明になった","l":"human-origins","x":"北京原人の化石は、1920年代から30年代にかけて、北京郊外の周口店の洞窟で見つかった。頭骨や歯など40体分以上の骨が発掘され、世界的な大発見となった。ところが、日中戦争のさなかの"},{"id":"human-origins-t5","k":"debate","kj":"諸説あり","t":"人類はいつ火を使い始めたのか","l":"human-origins","x":"火を使うことは、人類の歴史で最も大きな出来事の一つである。火は、夜の闇と寒さ、猛獣から身を守り、食べ物を加熱して消化しやすくした。加熱した食べ物から多くのエネルギーをとれるようにな"},{"id":"human-origins-t6","k":"trivia","kj":"こぼれ話","t":"身長1メートルの「ホビット」","l":"human-origins","x":"2003年、インドネシアのフローレス島で、身長1メートルほど、脳の容積も400cc程度という小さな人類の化石が見つかった。ホモ＝フロレシエンシスと名づけられ、映画『ロード・オブ・ザ"},{"id":"human-origins-t7","k":"confuse","kj":"混同注意","t":"猿人・原人・旧人・新人は「分類」ではない","l":"human-origins","x":"日本の教科書では、人類の進化を「猿人→原人→旧人→新人」の4段階で説明することが多い。分かりやすい区分だが、注意も必要だ。これは生物学上の正式な分類ではなく、進化の段階をおおまかに"},{"id":"human-origins-t8","k":"trivia","kj":"こぼれ話","t":"道具は人類だけのものではなかった","l":"human-origins","x":"石器を作ることは、長い間「ヒト属（ホモ属）の証」とされてきた。ところが2015年、ケニアのトゥルカナ湖のほとりのロメクウィ遺跡で、約330万年前の石器が見つかったと発表された。ホモ"},{"id":"human-origins-t9","k":"trivia","kj":"こぼれ話","t":"40年間見破られなかった偽の化石――ピルトダウン人","l":"human-origins","x":"1912年、イギリスのピルトダウンで、アマチュア考古学者のドーソンが「人類と類人猿をつなぐ化石」を発見したと発表した。頭骨は人間のように大きいのに、あごは類人猿のようだったので、「"},{"id":"human-origins-t10","k":"trivia","kj":"こぼれ話","t":"「タウング・チャイルド」と猛禽類","l":"human-origins","x":"1924年、南アフリカのタウングの石灰岩採石場で、幼い子どもの頭骨の化石が見つかった。解剖学者ダートは、これを人類の祖先と考え、アウストラロピテクス＝アフリカヌス（「アフリカの南の"},{"id":"hundred-schools-t1","k":"source","kj":"史料","t":"『論語』のことば","l":"hundred-schools","x":"先生（孔子）は言われた。「法令で民を導き、刑罰で民を統制すれば、民は刑罰をうまく免れようとして、恥を感じなくなる。徳で民を導き、礼で民を統制すれば、民は恥を知り、自ら正しくなる」。"},{"id":"hundred-schools-t2","k":"source","kj":"史料","t":"孟子の性善説","l":"hundred-schools","x":"人が、幼い子どもが今にも井戸に落ちそうなのを見たとする。だれでも、はっとして、かわいそうに思う心が起こる。それは、その子の親と親しくなろうとするからでも、村人や友人にほめられたいか"},{"id":"hundred-schools-t3","k":"confuse","kj":"混同注意","t":"孟子と荀子","l":"hundred-schools","x":"孟子荀子人間の本性性善説（生まれつき善の芽生えをもつ）性悪説（生まれつき利己的で争う）重視したもの内にある善の芽生えを育てること。王道政治外からの礼による矯正と学習。礼治主義政治思"},{"id":"hundred-schools-t4","k":"source","kj":"史料","t":"墨子、戦争を止める","l":"hundred-schools","x":"楚の王が、名工の公輸盤（こうしゅはん）がつくった雲梯（城攻めの長いはしご）を使って、小国の宋を攻めようとしているという知らせを聞いた墨子は、10日10晩歩き続けて楚の都に駆けつけた"},{"id":"hundred-schools-t5","k":"debate","kj":"諸説あり","t":"老子は実在したか","l":"hundred-schools","x":"『史記』は、老子を、孔子が礼について教えを受けた、周の王室の記録係であったと記している。しかし、司馬遷自身も、老子が誰であったかについて、いくつかの異なる説を併記しており、老子が実"},{"id":"hundred-schools-t6","k":"source","kj":"史料","t":"胡蝶の夢","l":"hundred-schools","x":"昔、荘周（荘子）は、夢の中で蝶になった。ひらひらと楽しく飛び回る蝶であり、自分が荘周であることなど、分からなかった。ふと目が覚めると、まぎれもなく荘周である。荘周が夢で蝶になったの"},{"id":"hundred-schools-t7","k":"trivia","kj":"こぼれ話","t":"『韓非子』から生まれた故事成語","l":"hundred-schools","x":"「矛盾」：楚の人が、「この盾はどんな矛でも突き通せない」「この矛はどんな盾でも突き通す」と自慢した。ある人が「では、その矛でその盾を突いたらどうなるか」と尋ねると、答えられなかった"},{"id":"hundred-schools-t8","k":"confuse","kj":"混同注意","t":"諸子百家の主な学派","l":"hundred-schools","x":"学派主な思想家主な主張主な書物儒家孔子・孟子・荀子仁と礼、徳治主義。孟子は性善説、荀子は性悪説『論語』『孟子』『荀子』道家老子・荘子無為自然、万物斉同『老子』『荘子』墨家墨子兼愛・"},{"id":"hundred-schools-t9","k":"now","kj":"いま","t":"2000年ぶりに出てきた『孫子』","l":"hundred-schools","x":"かつて、『孫子』の作者については、春秋時代の孫武とする説と、その子孫で戦国時代の斉に仕えた孫臏（そんぴん）とする説があり、決着がついていなかった。1972年、山東省の銀雀山（ぎんじ"},{"id":"hundred-schools-t10","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"hundred-schools","x":"酒見賢一『墨攻』（小説、1991年、中島敦記念賞）：墨家の革離が、たった一人で小国の城の守りを任され、大軍の攻撃から城を守る物語。のちに森秀樹によって漫画化され、2006年には香港"},{"id":"huns-attila-t1","k":"source","kj":"史料","t":"ローマ人の目に映ったフン人","l":"huns-attila","x":"彼らは、火も、味つけした食べ物も必要とせず、野生の植物の根や、どんな動物のものでも生に近い肉を食べる。肉は、自分の太ももと馬の背の間に挟んで、少し温めて食べるのである。……彼らは、"},{"id":"huns-attila-t2","k":"debate","kj":"諸説あり","t":"フン人と匈奴","l":"huns-attila","x":"フン人と匈奴を結びつける説には、次のような根拠が挙げられている。4世紀初めに中央アジアのソグド人の商人が書いた手紙で、中国の洛陽を攻めた匈奴が「フン（xwn）」と呼ばれている。フン"},{"id":"huns-attila-t3","k":"source","kj":"史料","t":"アッティラの宴","l":"huns-attila","x":"ほかの蛮族の者たちや私たちには、銀の皿に盛った豪華な料理が出されたが、アッティラには、木の皿に盛った肉のほかは何もなかった。ほかの点でも、彼は質素であった。宴の客には金や銀の杯が配"},{"id":"huns-attila-t4","k":"person","kj":"人物","t":"「最後のローマ人」アエティウス","l":"huns-attila","x":"アエティウス（390年ごろ〜454年）は、ドナウ川沿いの属州出身の軍人の子であった。少年時代、西ローマ帝国と西ゴート人・フン人との和平のための人質として、アラリックのもとで、さらに"},{"id":"huns-attila-t5","k":"debate","kj":"諸説あり","t":"アッティラはなぜ引き返したのか","l":"huns-attila","x":"教会の伝説では、アッティラは、レオ1世の威厳に打たれ、あるいはレオ1世の背後に剣を持った聖ペテロと聖パウロが現れたのを見て、恐れて引き返したとされる。しかし、これは後世の教会の伝承"},{"id":"huns-attila-t6","k":"trivia","kj":"こぼれ話","t":"ヴェネツィアの誕生","l":"huns-attila","x":"アッティラがアクイレイアなどの北イタリアの都市を破壊すると、多くの人々が、アドリア海の沿岸の干潟に浮かぶ小さな島々に逃れたという。陸地から離れた干潟は、騎馬の軍隊が近づけない安全な"},{"id":"huns-attila-t7","k":"myth","kj":"俗説","t":"三重の棺","l":"huns-attila","x":"ヨルダネスによれば、フン人たちは、アッティラの遺体を、金・銀・鉄の三重の棺に納め、夜の闇の中でひそかに葬った。そして、財宝を奪われないよう、墓を掘った者たちを殺したという。アッティ"},{"id":"huns-attila-t8","k":"trivia","kj":"こぼれ話","t":"ハンガリーはフン人の国？","l":"huns-attila","x":"ハンガリー（ハンガリー語ではマジャロルサーグ）の国名は、フン人とは関係がない。ハンガリーの人々の祖先であるマジャル人は、アッティラの時代から400年以上たった9世紀末に、東方から現"},{"id":"huns-attila-t9","k":"works","kj":"作品紹介","t":"この時代にまつわる作品","l":"huns-attila","x":"ヴェルディのオペラ『アッティラ』（1846年初演）：アクイレイアを滅ぼしたアッティラと、復讐をねらう娘オダベッラ、ローマの将軍エツィオ（アエティウス）らの物語。イタリアの統一運動（"},{"id":"ice-age-t1","k":"trivia","kj":"こぼれ話","t":"北海の海底から見つかる石器","l":"ice-age","x":"北海の底を引き網で漁をすると、ときどきマンモスの骨や、人類が使った石器、骨角器が網にかかる。これらは、海に沈んだドッガーランドに人々が暮らしていた証拠である。ドッガーランドは、氷期"},{"id":"ice-age-t2","k":"life","kj":"暮らし","t":"マンモスの骨で作った家","l":"ice-age","x":"ウクライナのメジリチ遺跡では、約1万5000年前の、マンモスの骨を組み上げて作った住居の跡が見つかっている。直径5メートルほどの円形の住居で、土台にはマンモスの頭骨や下あごの骨をず"},{"id":"ice-age-t3","k":"trivia","kj":"こぼれ話","t":"服を着始めたのはいつか――シラミが教えてくれる","l":"ice-age","x":"人類がいつから服を着るようになったのかは、服そのものが残らないので分かりにくい。そこで研究者が目をつけたのが、人間に寄生するシラミだった。人間のシラミには、髪に住むアタマジラミと、"},{"id":"ice-age-t4","k":"life","kj":"暮らし","t":"狩猟採集民はどのくらい働いていたのか","l":"ice-age","x":"狩猟採集民の生活というと、飢えと隣り合わせの厳しい暮らしを想像しがちだ。しかし、20世紀にアフリカのカラハリ砂漠の狩猟採集民（サン人）を調べた人類学者たちは、彼らが食料を得るために"},{"id":"ice-age-t5","k":"trivia","kj":"こぼれ話","t":"最後のマンモス","l":"ice-age","x":"マンモスの多くは約1万年前までに絶滅したが、北極海に浮かぶロシアのウランゲリ島では、約4000年前まで小型のマンモスが生き残っていた。約4000年前といえば、エジプトではすでにピラ"},{"id":"ice-age-t6","k":"trivia","kj":"こぼれ話","t":"野尻湖のナウマンゾウ","l":"ice-age","x":"長野県の野尻湖の湖底からは、1948年以来、ナウマンゾウの化石が数多く見つかっている。ナウマンゾウは、明治時代に日本の地質学の基礎を築いたドイツ人の地質学者ナウマンにちなんで名づけ"},{"id":"ice-age-t7","k":"confuse","kj":"混同注意","t":"「中石器時代」とは","l":"ice-age","x":"旧石器時代と新石器時代の間を、とくにヨーロッパでは「中石器時代」と呼ぶことがある。氷期が終わり、大型動物が減って森が広がった環境の中で、人々が弓矢で中小の動物を狩り、魚や貝をとり、"},{"id":"india-buddhism-t1","k":"debate","kj":"諸説あり","t":"ブッダはいつの人か","l":"india-buddhism","x":"ブッダが80歳で亡くなったことは、どの伝承でも一致している。しかし、その年代については、大きく2つの説がある。スリランカに伝わる年代記などに基づく説では、ブッダの生涯は、前563年"},{"id":"india-buddhism-t2","k":"source","kj":"史料","t":"ブッダのことば","l":"india-buddhism","x":"ブッダの言葉は、はじめは弟子たちによって暗唱で伝えられ、のちに文字に記された。最も古い層に属するとされる経典から、いくつか紹介しよう。実にこの世においては、怨みに報いるに怨みをもっ"},{"id":"india-buddhism-t3","k":"trivia","kj":"こぼれ話","t":"日本語の中の仏教のことば","l":"india-buddhism","x":"仏教は、中国を経て6世紀に日本に伝わり、日本語の中に多くの言葉を残した。「我慢」：もとは、自分に執着して思い上がる心（我への慢心）を意味する、悪い意味の言葉だった。「醍醐味」：醍醐"},{"id":"india-buddhism-t4","k":"now","kj":"いま","t":"ガンディーと不殺生","l":"india-buddhism","x":"ジャイナ教の不殺生の思想は、インドの文化に深く根づいた。20世紀のインド独立運動の指導者ガンディーは、ジャイナ教徒の多いグジャラート地方に生まれ、若いころには、ジャイナ教の在家の思"},{"id":"india-buddhism-t5","k":"confuse","kj":"混同注意","t":"バラモン教・仏教・ジャイナ教","l":"india-buddhism","x":"バラモン教仏教ジャイナ教開祖なし（ヴェーダの宗教）ガウタマ＝シッダールタ（ブッダ）ヴァルダマーナ（マハーヴィーラ）開祖の出身―クシャトリヤ（シャーキャ族の王子）クシャトリヤヴェーダ"},{"id":"india-buddhism-t6","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"india-buddhism","x":"手塚治虫『ブッダ』（漫画、1972〜1983年連載）：ゴータマ＝シッダールタの生涯を、多くの架空の人物を交えて描いた大作。ヴァルナ制に苦しむ人々の姿や、生と死をめぐる問いが、壮大な"},{"id":"indus-t1","k":"confuse","kj":"混同注意","t":"「インダス文明」の時代は、アーリヤ人の時代ではない","l":"indus","x":"インドの古代史で混同しやすいのが、インダス文明とアーリヤ人の関係である。インダス文明アーリヤ人のヴェーダ時代時代前2600〜前1900年ごろ前1500年ごろ〜中心地インダス川流域（"},{"id":"indus-t2","k":"trivia","kj":"こぼれ話","t":"「大浴場」と「穀物倉」","l":"indus","x":"モエンジョ＝ダーロの城塞の上には、「大浴場」と呼ばれる施設がある。長さ約12m、幅約7m、深さ約2.4mの長方形のプールで、底と壁には煉瓦がすき間なく並べられ、水が漏れないようにア"},{"id":"indus-t3","k":"trivia","kj":"こぼれ話","t":"世界最古の木綿","l":"indus","x":"インダス文明の人々は、世界で最も早く木綿を栽培し、布を織った人々の一つである。モエンジョ＝ダーロからは、木綿の布の切れ端が銀の器にくっついた状態で見つかっている。のちのギリシア人や"},{"id":"indus-t4","k":"source","kj":"史料","t":"「メルッハの船」","l":"indus","x":"アッカド王国のサルゴン（前24〜前23世紀）は、碑文の中で、自分の都の岸壁に遠い国々の船を停泊させたと誇っている。メルッハの船、マガンの船、ディルムンの船を、彼はアッカドの岸壁に停"},{"id":"indus-t5","k":"view","kj":"視点を変える","t":"「四大文明」という言い方","l":"indus","x":"日本では、メソポタミア・エジプト・インダス・中国（黄河）の四つの文明を「四大文明」と呼ぶことが多い。しかし、この呼び方は、主に日本や中国で使われてきたもので、欧米の歴史学では一般的"},{"id":"indus-t6","k":"myth","kj":"俗説","t":"「アーリヤ人がインダス文明を滅ぼした」","l":"indus","x":"20世紀半ば、モエンジョ＝ダーロを発掘したイギリスの考古学者ウィーラーは、遺跡の最上層の通りや家の中から、埋葬されずに放置されたような人骨がいくつか見つかったことに注目した。そして"},{"id":"indus-t7","k":"now","kj":"いま","t":"遺伝子が語る人々の歴史","l":"indus","x":"2019年、インドのラーキーガリー遺跡で見つかった、インダス文明の時代の女性の人骨から、DNAの解析結果が発表された。その結果、この女性の祖先には、イラン方面の古い狩猟採集民と、南"},{"id":"intro-calendar-t1","k":"trivia","kj":"こぼれ話","t":"ナイル川の洪水とシリウス星","l":"intro-calendar","x":"古代エジプトでは、毎年夏にナイル川が増水し、上流から肥えた土を運んできた。この増水の始まりと、明け方の東の空に恒星シリウスが初めて見える日がほぼ一致することに、エジプト人は気づいて"},{"id":"intro-calendar-t2","k":"debate","kj":"諸説あり","t":"イエスは「紀元前」に生まれた？","l":"intro-calendar","x":"ディオニシウスの計算には誤りがあったと考えられている。新約聖書の福音書によれば、イエスが生まれたのはユダヤのヘロデ王の時代である。ところがヘロデ王は、ほかの史料から前4年に死んだこ"},{"id":"intro-calendar-t3","k":"confuse","kj":"混同注意","t":"「0年」は存在しない","l":"intro-calendar","x":"西暦には「0年」がない。前1年の次の年が後1年である。ディオニシウスの時代のヨーロッパには、数としての「0」の考え方がまだなかったからだ（0はインドで生まれ、イスラーム世界を経て1"},{"id":"intro-calendar-t4","k":"trivia","kj":"こぼれ話","t":"シェイクスピアとセルバンテスは同じ日に死んだ？","l":"intro-calendar","x":"1616年4月23日、イギリスの劇作家シェイクスピアと、スペインの作家セルバンテスが亡くなったとされる。この偶然にちなんで、4月23日はユネスコの「世界本の日」に定められている。し"},{"id":"intro-calendar-t5","k":"confuse","kj":"混同注意","t":"「十月革命」は11月に起きた","l":"intro-calendar","x":"1917年のロシアの「十月革命」は、私たちの暦では11月7日に起きている。当時のロシアはまだユリウス暦を使っていて、その暦では10月25日だったからだ。同じように、1917年の「二"},{"id":"intro-calendar-t6","k":"trivia","kj":"こぼれ話","t":"明治政府の改暦と「12月分の給料」","l":"intro-calendar","x":"日本は明治5年の11月、突然、翌月から太陽暦に切り替えると発表した。そして、明治5年12月2日の翌日が、明治6年1月1日とされた。12月はわずか2日で終わってしまったのである。この"},{"id":"intro-calendar-t7","k":"myth","kj":"俗説","t":"「マヤ暦では2012年に世界が終わる」","l":"intro-calendar","x":"2012年12月21日に世界が終わる、という噂が世界中で話題になったことがある。古代マヤの「長期暦」が、この日に一つの大きな区切り（13バクトゥン）を迎えることから広まった説だった"},{"id":"intro-calendar-t8","k":"trivia","kj":"こぼれ話","t":"「日月火水木金土」は空海が持ち帰った？","l":"intro-calendar","x":"日本の曜日の名前（日・月・火・水・木・金・土）も、同じ7つの天体に由来する。曜日の考え方は、平安時代の初めに、唐に渡った空海が持ち帰った仏教の占星術の経典『宿曜経（すくようきょう）"},{"id":"intro-history-t1","k":"trivia","kj":"こぼれ話","t":"年代はどうやって測るのか","l":"intro-history","x":"遺跡や遺物の年代を調べる方法として有名なのが、放射性炭素年代測定である。生物は生きている間、大気中の炭素を体に取り込んでいる。その中にはごくわずかに放射性の炭素14が含まれていて、"},{"id":"intro-history-t2","k":"source","kj":"史料","t":"ヘロドトスの「ペルシア軍170万人」","l":"intro-history","x":"古代ギリシアの歴史家ヘロドトスは、前480年にギリシアに攻め込んだペルシア王クセルクセスの陸軍を、170万人と書いている。さらに海軍や従者まで数えて、総勢は500万人を超えたという"},{"id":"intro-history-t3","k":"trivia","kj":"こぼれ話","t":"偽の文書を見破った男――ロレンツォ＝ヴァッラ","l":"intro-history","x":"中世ヨーロッパでは、「コンスタンティヌスの寄進状」という文書が大きな意味を持っていた。4世紀のローマ皇帝コンスタンティヌスが、病気を治してくれたお礼に、ローマ教皇にローマ市と西方の"},{"id":"intro-history-t4","k":"now","kj":"いま","t":"20世紀の偽史料事件","l":"intro-history","x":"偽の史料は昔の話ではない。1983年、西ドイツの週刊誌『シュテルン』は、発見されたばかりの「ヒトラーの日記」60冊余りを大々的に発表した。高名な歴史家も一時は本物と認めたが、間もな"},{"id":"intro-history-t5","k":"view","kj":"視点を変える","t":"征服された側の記録を残した人々","l":"intro-history","x":"それでも、征服された側の声が残されたこともある。16世紀、メキシコに渡ったスペインの修道士サアグンは、アステカの人々から話を聞き取り、ナワトル語とスペイン語で百科事典のような記録を"},{"id":"intro-history-t6","k":"source","kj":"史料","t":"司馬遷の手紙――「死は泰山より重く、鴻毛より軽い」","l":"intro-history","x":"司馬遷は、匈奴に降伏した将軍李陵を武帝の前で弁護したため、武帝の怒りを買い、宮刑（男性器を切除する刑）に処せられた。死を選ぶこともできたが、父から託された歴史書を完成させるため、屈"},{"id":"intro-history-t7","k":"confuse","kj":"混同注意","t":"「史料」と「資料」","l":"intro-history","x":"このサイトでは「史料」という言葉を使っている。一般的な「資料」と同じ意味のように見えるが、歴史学で「史料」というときは、過去を知る手がかりとなる、その時代に作られたもの（または伝え"},{"id":"intro-history-t8","k":"trivia","kj":"こぼれ話","t":"ロゼッタ＝ストーンとシャンポリオン","l":"intro-history","x":"1799年、エジプトに遠征していたナポレオンの軍隊が、ナイル川河口の町ロゼッタ（ラシード）の近くで、文字の刻まれた黒い石碑を見つけた。ロゼッタ＝ストーンである。そこには同じ内容の文"},{"id":"intro-history-t9","k":"confuse","kj":"混同注意","t":"「先史時代」と「歴史時代」","l":"intro-history","x":"文字による記録が残る以前の時代を先史時代、文字の記録がある時代を歴史時代という。ただし、その境目は地域によって大きく違う。メソポタミアやエジプトでは前3000年ごろに歴史時代に入る"},{"id":"intro-maps-t1","k":"trivia","kj":"こぼれ話","t":"「上」は東だった――中世ヨーロッパのTO図","l":"intro-maps","x":"中世ヨーロッパでは、「TO図」と呼ばれる図式的な世界地図が広く描かれた。円（O）の中にT字形の水路があり、世界を三つの大陸に分けている。上半分がアジア、左下がヨーロッパ、右下がアフ"},{"id":"intro-maps-t2","k":"view","kj":"視点を変える","t":"南が上――イスラーム世界の地図","l":"intro-maps","x":"12世紀、シチリア王ロジェール2世に仕えたイスラーム教徒の地理学者イドリーシーは、各地の旅行者や商人から情報を集め、1154年に大きな世界地図とその解説書を完成させた。「ロジェール"},{"id":"intro-maps-t3","k":"view","kj":"視点を変える","t":"1402年、朝鮮で描かれたアフリカ","l":"intro-maps","x":"1402年、朝鮮王朝で「混一疆理歴代国都之図」という世界地図が作られた。元の時代の中国の地図をもとに、朝鮮と日本を書き加えたものである。驚くべきことに、この地図にはアフリカの南端が"},{"id":"intro-maps-t4","k":"debate","kj":"諸説あり","t":"地図は「中立」か","l":"intro-maps","x":"1970年代、ドイツの歴史家ペータースは、メルカトル図法がヨーロッパを大きく、アフリカや南アメリカを小さく見せ、ヨーロッパ中心の世界観を植えつけてきたと批判し、面積を正しく表す図法"},{"id":"intro-maps-t5","k":"trivia","kj":"こぼれ話","t":"日本を「歩いて」測った伊能忠敬","l":"intro-maps","x":"日本では、江戸時代後期の伊能忠敬が、1800年から1816年にかけて全国を測量して回った。50歳で隠居してから天文学と測量を学び、歩幅で距離を測りながら、17年間で約4万キロメート"},{"id":"intro-maps-t6","k":"confuse","kj":"混同注意","t":"「帝国」の範囲と実際の支配","l":"intro-maps","x":"地図の上では、モンゴル帝国やローマ帝国が巨大な一色で塗られていることが多い。しかし、たとえばモンゴル帝国の中には、それぞれ独立性の強いいくつものウルス（国家）があり、さらに服属して"},{"id":"intro-maps-t7","k":"confuse","kj":"混同注意","t":"変わる地名","l":"intro-maps","x":"歴史の地図を見るときに戸惑うのが、地名の変化である。同じ場所でも、時代によって呼び名が違う。現在の名かつての名イスタンブルビザンティオン → コンスタンティノープル（コンスタンティ"},{"id":"intro-worldhistory-t1","k":"person","kj":"人物","t":"王朝の盛衰に法則を見いだしたイブン＝ハルドゥーン","l":"intro-worldhistory","x":"14世紀、北アフリカのチュニス出身の歴史家イブン＝ハルドゥーンは、大著『歴史序説（ムカッディマ）』で、王朝が興っては滅びるのはなぜかを論じた。彼によれば、厳しい砂漠や山地で暮らす遊"},{"id":"intro-worldhistory-t2","k":"confuse","kj":"混同注意","t":"「発見」という言葉の問題","l":"intro-worldhistory","x":"世界史の用語にも、ヨーロッパ中心の見方の名残がある。かつての教科書では、15〜16世紀のヨーロッパ人の航海を「地理上の発見」と呼んでいた。しかし、アメリカ大陸には何千万もの人々がす"},{"id":"intro-worldhistory-t3","k":"view","kj":"視点を変える","t":"「オリエント」「極東」は誰から見た方角か","l":"intro-worldhistory","x":"「オリエント」は、ラテン語で「日の昇る方角」、つまり東を意味する。古代ローマから見た東方、すなわちエジプトや西アジアを指す言葉だった。「中東」「近東」「極東」という地域の呼び方も、"},{"id":"intro-worldhistory-t4","k":"trivia","kj":"こぼれ話","t":"「東洋史」を生んだ日本の歴史学","l":"intro-worldhistory","x":"「東洋史」という学問の分野は、実は明治時代の日本で生まれたものである。1894年ごろ、歴史家の那珂通世が、中国を中心にアジア全体の歴史を扱う科目として「東洋史」を提唱した。これは、"},{"id":"islam-faith-t1","k":"trivia","kj":"こぼれ話","t":"『クルアーン』の中のイエスとマリア","l":"islam-faith","x":"『クルアーン』には、イエスとその母マリアが、たびたび登場する。第19章は、マリアの名をとって「マルヤム章」と呼ばれ、マリアが男性に触れることなくイエスを身ごもり、ナツメヤシの木の下"},{"id":"islam-faith-t2","k":"person","kj":"人物","t":"ブハーリー――60万のハディースから選ぶ","l":"islam-faith","x":"ムハンマドの死後、時代がたつにつれて、ハディースの数は膨大になり、その中には、後の時代の人々が自分たちの都合のよいように作り出したものも数多く含まれるようになった。9世紀、中央アジ"},{"id":"islam-faith-t3","k":"term","kj":"用語","t":"「ハラール」と「ハラーム」","l":"islam-faith","x":"シャリーアで許されたものを「ハラール」、禁じられたものを「ハラーム」という。食べ物では、豚肉と、その脂やエキスなどを含むもの、酒などのアルコール、動物の血、自然に死んだ動物の肉など"},{"id":"islam-faith-t4","k":"trivia","kj":"こぼれ話","t":"日本人で最初の巡礼者","l":"islam-faith","x":"日本人として初めてメッカへの巡礼を果たしたのは、山岡光太郎やまおかこうたろうであるとされる。1909年、ロシアから亡命していたタタール人のイスラーム学者アブデュルレシト・イブラヒム"},{"id":"islam-faith-t5","k":"now","kj":"いま","t":"ラマダーンと現代社会","l":"islam-faith","x":"ラマダーン月の時期は、毎年約11日ずつ早まっていくため、夏の暑い時期にあたることもある。日の長い北ヨーロッパの国々では、夏のラマダーンには、断食の時間が18時間以上になることもある"},{"id":"islam-faith-t6","k":"works","kj":"作品紹介","t":"イスラーム教を知るための作品","l":"islam-faith","x":"井筒俊彦『イスラーム文化――その根底にあるもの』（岩波文庫）：イスラーム学者の井筒俊彦が、イスラームの宗教・法・内面の信仰を、一般向けに語った講演録。映画『ハッジ』（Le Gran"},{"id":"islamic-science-t1","k":"trivia","kj":"こぼれ話","t":"本の重さと同じ黄金","l":"islamic-science","x":"後世の伝承によれば、カリフのマームーンは、フナインが翻訳した書物の重さと同じ重さの黄金を、報酬として与えたという伝承。そのため、フナインは、わざと厚い紙に、大きな文字で、行の間を広"},{"id":"islamic-science-t2","k":"debate","kj":"諸説あり","t":"「知恵の館」は何だったのか","l":"islamic-science","x":"「知恵の館」は、学者たちが集まって翻訳と研究を行う、一種のアカデミーであったと説明されることが多い。しかし、実際の姿については、わからないことが多い諸説。近年の研究では、「知恵の館"},{"id":"islamic-science-t3","k":"trivia","kj":"こぼれ話","t":"暗号解読の祖キンディー","l":"islamic-science","x":"キンディーは、哲学だけでなく、数学・医学・音楽など、あらゆる学問について書いた。その中に『暗号文を解読することについての書』という論文がある。この中でキンディーは、文章の中で、それ"},{"id":"islamic-science-t4","k":"source","kj":"史料","t":"ビールーニー『インド誌』","l":"islamic-science","x":"ビールーニーは、インドの人々の学問への態度について、次のように書いている。インドの人々は、自分たちの国のほかに国はなく、自分たちの民族のほかに民族はなく、自分たちの王のほかに王はな"},{"id":"islamic-science-t5","k":"myth","kj":"俗説","t":"肉をつるして病院の場所を選ぶ","l":"islamic-science","x":"ラーズィーには、次のような逸話が伝えられている。カリフから、バグダードに新しい病院を建てる場所を選ぶよう命じられたラーズィーは、町のあちこちに生の肉をつるした。そして、肉が最も腐り"},{"id":"islamic-science-t6","k":"person","kj":"人物","t":"イブン＝シーナーの自伝","l":"islamic-science","x":"イブン＝シーナーは、弟子に口述した自伝を残している。その中で、若いころの学問について、次のように語っている。私はアリストテレスの『形而上学』を読んだが、その内容が理解できなかった。"},{"id":"islamic-science-t7","k":"myth","kj":"俗説","t":"狂人のふりをした科学者","l":"islamic-science","x":"イブン＝ハイサムについては、次のような話が伝えられている。イラクのバスラに生まれたイブン＝ハイサムは、ナイル川の洪水を、堤防によって調節することができる、と語っていた。これを聞いた"},{"id":"islamic-science-t8","k":"person","kj":"人物","t":"神への愛――ラービアとハッラージュ","l":"islamic-science","x":"8世紀のバスラの女性ラービアは、スーフィズムの先駆者の一人とされる。ある日、ラービアは、片手にたいまつ、片手に水の入った桶を持って、町を走っていた。人々がそのわけを尋ねると、ラービ"},{"id":"islamic-science-t9","k":"trivia","kj":"こぼれ話","t":"「アラジン」と「アリババ」はどこから来たか","l":"islamic-science","x":"『千夜一夜物語』で最も有名な「アラジンと魔法のランプ」と「アリババと40人の盗賊」は、実は、アラビア語の古い写本には含まれていない。18世紀初め、フランスの東洋学者アントワーヌ・ガ"},{"id":"islamic-science-t10","k":"myth","kj":"俗説","t":"金貨と銀貨","l":"islamic-science","x":"12世紀の文人ニザーミー・アルーズィーの伝えるところでは、フィルドゥシーは、完成した『シャー・ナーメ』を、ガズナ朝のマフムードにささげた。ところが、マフムードは、約束の金貨ではなく"},{"id":"islamic-science-t11","k":"source","kj":"史料","t":"『ルバイヤート』より","l":"islamic-science","x":"木陰には一斤のパン、一瓶の酒、一巻の詩――そして君が荒野でわが傍らに歌うなら、荒野もそのまま楽園となる。（フィッツジェラルドの英訳『ルバイヤート』（1859年の初版）より試訳）フィ"},{"id":"islamic-science-t12","k":"now","kj":"いま","t":"月に刻まれた名前","l":"islamic-science","x":"月のクレーターには、科学に貢献した人々の名前がつけられている。その中には、イスラーム世界の学者たちの名前も数多い。月の表側には、バッターニー（ラテン名アルバテグニウス）、マームーン"},{"id":"islamic-science-t13","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"islamic-science","x":"『千夜一夜物語』（アラビアン・ナイト）：アラビア語からの日本語訳には、前嶋信次・池田修訳（平凡社東洋文庫）がある。ガランのフランス語訳からの日本語訳や、19世紀のイギリスのバートン"},{"id":"jin-sixteen-t1","k":"confuse","kj":"混同注意","t":"屯田制・占田課田法・均田制","l":"jin-sixteen","x":"魏晋南北朝時代から隋唐にかけての土地制度は、名前が似ていて紛らわしい。制度王朝始まった年内容屯田制魏（曹操）196年戦乱で荒れた土地に流民や兵士を集めて耕作させ、収穫の5〜6割を国"},{"id":"jin-sixteen-t2","k":"trivia","kj":"こぼれ話","t":"石崇と王愷の富くらべ","l":"jin-sixteen","x":"西晋の貴族たちのぜいたくぶりは、のちの時代まで語り草となった。『世説新語』は、大富豪の石崇と、武帝の母方のおじ王愷の富くらべの逸話を伝えている伝承。王愷が飴（麦芽糖）で釜を洗わせる"},{"id":"jin-sixteen-t3","k":"myth","kj":"俗説","t":"「肉のかゆを食べればよいのに」","l":"jin-sixteen","x":"恵帝については、能力の乏しさを示す逸話が、『晋書』恵帝紀に記されている伝承。あるとき、天下に飢饉が起こり、多くの民が餓死しているという報告を受けた恵帝は、「どうして肉のかゆを食べな"},{"id":"jin-sixteen-t4","k":"source","kj":"史料","t":"江統『徙戎論』（299年）","l":"jin-sixteen","x":"晋の官僚江統は、八王の乱の最中の299年、華北に住む異民族を、もとの土地に帰らせるべきだと主張する意見書を朝廷に提出した。関中（長安を中心とする地方）の人口は100万余りであるが、"},{"id":"jin-sixteen-t5","k":"trivia","kj":"こぼれ話","t":"「青い衣を着て酒をつげ」","l":"jin-sixteen","x":"捕らえられた懐帝は、平陽で、劉聡から「会稽郡公」という称号を与えられた。313年の元日、劉聡は、宴会の席で、懐帝に召使いの青い衣を着させ、客たちに酒をつがせた。かつての晋の皇帝が、"},{"id":"jin-sixteen-t6","k":"person","kj":"人物","t":"石勒――奴隷から皇帝へ","l":"jin-sixteen","x":"石勒（274〜333年）は、羯という、匈奴の別部とされる人々の出身であった。羯は、中央アジアの出身ではないかとする説もある諸説。若いころ、飢饉の中で晋の役人に捕らえられて山東に売ら"},{"id":"jin-sixteen-t7","k":"now","kj":"いま","t":"永嘉の乱と客家","l":"jin-sixteen","x":"中国の広東・福建・江西などの山地や、台湾・東南アジアの各地に住む客家（ハッカ）と呼ばれる人々は、独自の言語（客家語）と文化を持つ漢民族の一集団である。客家の多くの家の族譜（家系の記"},{"id":"jin-sixteen-t8","k":"view","kj":"視点を変える","t":"「五胡」という呼び名を考える","l":"jin-sixteen","x":"「五胡」や「乱華」（中華を乱す）という言葉は、漢人の側から見た呼び名である。中国の伝統的な歴史書は、この時代を、異民族によって中華が乱された暗黒時代として描いてきた。しかし、近年の"},{"id":"jin-sixteen-t9","k":"term","kj":"用語","t":"「風声鶴唳」と「草木皆兵」","l":"jin-sixteen","x":"淝水の戦いからは、現在も使われる四字熟語が二つ生まれた。草木皆兵（そうもくかいへい）：戦いの前、寿陽の城壁から八公山を眺めた苻堅が、山の草木までが東晋の兵に見えて恐れたという話から"},{"id":"jin-sixteen-t10","k":"source","kj":"史料","t":"下駄の歯が折れたのにも気づかず――謝安の囲碁","l":"jin-sixteen","x":"冒頭に紹介した、勝報を受けた謝安の逸話は、『晋書』謝安伝に記されている。謝安は、そのとき客と囲碁を打っていた。駅伝の使者が持ってきた手紙を読み終えると、それを床の上に置いたまま、少"},{"id":"jin-sixteen-t11","k":"debate","kj":"諸説あり","t":"あぶみが封建制を生んだ？","l":"jin-sixteen","x":"1962年、アメリカの歴史家リン＝ホワイトは、あぶみの普及によって、ヨーロッパで重装の騎士による突撃戦術が可能になり、高価な騎士の装備をまかなうために、騎士に土地を与える封建制が生"},{"id":"jin-sixteen-t12","k":"trivia","kj":"こぼれ話","t":"統万城――錐が1寸入れば工人を殺す","l":"jin-sixteen","x":"匈奴の赫連勃勃が、オルドス（現在の陝西省北部）に築いた夏の都が、統万城である。「天下を統一し、万国に君臨する」という意味の名をつけられたこの城は、413年から約6年をかけて、10万"},{"id":"jin-sixteen-t13","k":"works","kj":"作品紹介","t":"この時代にまつわる作品と言葉","l":"jin-sixteen","x":"劉義慶『世説新語』（5世紀、南朝の宋）：後漢末から東晋までの貴族や名士たちの逸話を集めた書物。石崇の富くらべ、謝安や王導の逸話など、魏晋の貴族社会の雰囲気を生き生きと伝える。日本で"},{"id":"justinian-t1","k":"debate","kj":"諸説あり","t":"二つの顔をもつ歴史家プロコピオス","l":"justinian","x":"ユスティニアヌスの時代について最も詳しい記録を残したのは、名将ベリサリウスの秘書として遠征に同行した歴史家プロコピオスである。彼は、戦争の経過を記した『戦史』と、皇帝の建築事業をた"},{"id":"justinian-t2","k":"source","kj":"史料","t":"テオドラの演説","l":"justinian","x":"今は、女が男たちの前で大胆に振る舞ってよいかどうかを論じている時ではない。……いったん帝衣をまとった者が、逃亡者になることは耐えがたい。皇帝陛下、もし御身の安全を望まれるなら、それ"},{"id":"justinian-t3","k":"myth","kj":"俗説","t":"「ソロモンよ、我は汝に勝てり」","l":"justinian","x":"後世の伝説によれば、537年の献堂式の日、完成した聖堂に足を踏み入れたユスティニアヌスは、「ソロモンよ、我は汝に勝てり」と叫んだという。古代イスラエルのソロモン王がイェルサレムに建"},{"id":"justinian-t4","k":"trivia","kj":"こぼれ話","t":"日本の民法の遠い祖先","l":"justinian","x":"『ローマ法大全』は、中世の西ヨーロッパでは長く忘れられていた。しかし、11世紀末、北イタリアで『学説彙纂』の写本が再発見されると、ボローニャ大学で研究が始まり、ヨーロッパ各地から学"},{"id":"justinian-t5","k":"trivia","kj":"こぼれ話","t":"竪琴とパンとスポンジ","l":"justinian","x":"ヴァンダル王ゲリメルは、敗れて山中に逃れ、ベリサリウスの軍に包囲された。冬の山中で飢えに苦しんだゲリメルは、包囲軍の将校に使者を送り、3つの物を求めた。竪琴とパンとスポンジである。"},{"id":"justinian-t6","k":"source","kj":"史料","t":"ユスティニアヌスの疫病","l":"justinian","x":"この疫病は、コンスタンティノープルで4か月にわたって続き、そのうち3か月は猛威をふるった。……死者の数は、1日に5000人に達し、さらには1万人、またそれ以上となった。……死体を埋"},{"id":"justinian-t7","k":"trivia","kj":"こぼれ話","t":"絹の秘密を盗んだ修道士","l":"justinian","x":"ローマ帝国の人々にとって、絹は、ササン朝ペルシアの商人を通じて中国から買うしかない高価な品であった。ササン朝とは戦争が絶えなかったため、ユスティニアヌスは、ペルシアを通らずに絹を手"},{"id":"justinian-t8","k":"trivia","kj":"こぼれ話","t":"「ビザンツ帝国」は後世の呼び名","l":"justinian","x":"「ビザンツ帝国」という呼び名は、この国の人々自身が使っていたものではない。彼らは、1453年に滅びるまで、自分たちの国を「ローマ人の帝国」、自分たちを「ローマ人（ロマイオイ）」と呼"},{"id":"justinian-t9","k":"now","kj":"いま","t":"ハギア＝ソフィアの1500年","l":"justinian","x":"ハギア＝ソフィアは、537年の完成から900年以上にわたって、キリスト教世界最大の聖堂であった。1453年、オスマン帝国がコンスタンティノープルを征服すると、モスク（アヤソフィア）"},{"id":"justinian-t10","k":"works","kj":"作品紹介","t":"この時代にまつわる作品","l":"justinian","x":"プロコピオス『秘史』（6世紀）：ユスティニアヌスとテオドラを痛烈に批判した、生前には公表されなかった書物。17世紀にヴァチカンの図書館で写本が発見され、大きな反響を呼んだ。日本語訳"},{"id":"korea-japan-state-t1","k":"debate","kj":"諸説あり","t":"広開土王碑の「辛卯年」条","l":"korea-japan-state","x":"広開土王碑の第1面には、次のような一節がある。百残（百済）・新羅は、もとは（高句麗の）属民で、朝貢してきた。ところが倭が、辛卯の年（391年）に、海を渡ってきて百残を破り、□□新羅"},{"id":"korea-japan-state-t2","k":"source","kj":"史料","t":"七支刀の銘文","l":"korea-japan-state","x":"七支刀の銘文は、さびのため読めない字が多いが、おおよそ次のように読まれている。（表）泰■四年■月十六日丙午の正陽に、百たび鍛えた鉄の七支刀を造る。（この刀は）百兵を避けることができ"},{"id":"korea-japan-state-t3","k":"trivia","kj":"こぼれ話","t":"武寧王陵の墓誌と日本のコウヤマキ","l":"korea-japan-state","x":"武寧王陵から出土した墓誌には、「寧東大将軍の百済の斯麻しま王は、年62歳で、癸卯の年（523年）5月7日に亡くなった」と刻まれていた。「寧東大将軍」は、梁の皇帝から与えられた称号で"},{"id":"korea-japan-state-t4","k":"term","kj":"用語","t":"加耶と「任那」","l":"korea-japan-state","x":"朝鮮半島の南端の洛東江の流域には、4〜6世紀、金官加耶（金海）・大加耶（高霊）などの小国が分立していた。これを加耶（伽耶）という。加耶は、良質の鉄の産地で、鉄を求めて倭とも密接に交"},{"id":"korea-japan-state-t5","k":"trivia","kj":"こぼれ話","t":"鬱陵島と于山国","l":"korea-japan-state","x":"512年、新羅の将軍異斯夫は、日本海に浮かぶ鬱陵島うつりょうとうの于山国うさんこくを服属させた。異斯夫は、木で獅子の像を作って船に積み、「降伏しなければこの猛獣を放つ」と脅したとこ"},{"id":"korea-japan-state-t6","k":"source","kj":"史料","t":"世俗五戒","l":"korea-japan-state","x":"7世紀初め、僧の円光えんこうは、花郎の若者に、次の5つの戒め（世俗五戒）を授けたと伝えられる。一に、忠をもって君に仕える。二に、孝をもって親に仕える。三に、信をもって友と交わる。四"},{"id":"korea-japan-state-t7","k":"trivia","kj":"こぼれ話","t":"太宗と安市城の城主","l":"korea-japan-state","x":"『資治通鑑』によれば、唐軍が撤退する時、安市城の城主は城壁に登って、太宗に別れの礼をした。太宗は、城を固く守り抜いた城主の忠誠をほめたたえ、絹100匹を与えたという。敵の将をたたえ"},{"id":"korea-japan-state-t8","k":"trivia","kj":"こぼれ話","t":"瞻星台の石の数","l":"korea-japan-state","x":"瞻星台は、花崗岩の石を27段に積み上げて造られている。27段は、善徳女王が新羅の第27代の王であることを表すとか、使われた石の数は約362個で、1年の日数を表すといった説明がよく見"},{"id":"korea-japan-state-t9","k":"trivia","kj":"こぼれ話","t":"亀と兎の話","l":"korea-japan-state","x":"高句麗に捕らえられた金春秋は、高句麗の臣下の先道解せんどうかいに、ひそかに贈り物をした。すると先道解は、酒の席で次のような話をした。竜王の娘が病気になり、「兎の肝を飲めば治る」と言"},{"id":"korea-japan-state-t10","k":"myth","kj":"俗説","t":"落花岩と「三千宮女」","l":"korea-japan-state","x":"扶余の町の北、白馬江（錦江）に臨む扶蘇山の断崖を、落花岩という。泗沘城が落ちた時、敵に辱められることを拒んだ宮女たちが、ここから次々に川に身を投げ、その姿が花の散るようであったこと"},{"id":"korea-japan-state-t11","k":"source","kj":"史料","t":"『旧唐書』が記す白村江の戦い","l":"korea-japan-state","x":"唐の側の記録は、戦いの結末を次のように記している。劉仁軌りゅうじんきは、倭の兵と白江の河口で出会い、4度戦って4度とも勝ち、その船400艘を焼いた。煙と炎は天にみなぎり、海の水はす"},{"id":"korea-japan-state-t12","k":"person","kj":"人物","t":"文武王――海の龍になった王","l":"korea-japan-state","x":"文武王は、681年に亡くなる前、次のような遺言を残したと伝えられる。私が死んだ後は、10日たったら、宮殿の門の外の庭で、西の国（インド）の作法にならって火葬にせよ。喪の服の軽い重い"},{"id":"korea-japan-state-t13","k":"debate","kj":"諸説あり","t":"「聖徳太子」はどこまで実在したか","l":"korea-japan-state","x":"厩戸王（574〜622年）が実在の人物であることは確かである。しかし、『日本書紀』に描かれた「聖徳太子」の業績――一度に10人の訴えを聞き分けた、憲法十七条を自ら作った、などがどこ"},{"id":"korea-japan-state-t14","k":"source","kj":"史料","t":"「日出づる処の天子」","l":"korea-japan-state","x":"大業3年（607年）、その王の多利思比孤たりしひこが、使者を遣わして朝貢してきた。……その国書には、「日の出る所の天子が、書を日の没する所の天子に送る。お変わりはないか」などとあっ"},{"id":"korea-japan-state-t15","k":"debate","kj":"諸説あり","t":"改新の詔は書き換えられたのか――郡評論争","l":"korea-japan-state","x":"『日本書紀』の改新の詔には、地方の行政単位として「郡」という言葉が使われている。ところが、7世紀後半の金石文などには「評」という字が使われているものがあった。そのため、改新の詔は、"},{"id":"korea-japan-state-t16","k":"source","kj":"史料","t":"防人の歌","l":"korea-japan-state","x":"防人は、主に東国の農民から集められ、3年交代で九州の防備にあたった。食料や武器は自分で用意しなければならず、重い負担であった。8世紀の『万葉集』には、防人やその家族が詠んだ歌が10"},{"id":"korea-japan-state-t17","k":"life","kj":"暮らし","t":"日本に渡った百済と高句麗の人々","l":"korea-japan-state","x":"百済の滅亡と白村江の敗戦の後、多くの百済の人々が日本列島に渡った。『日本書紀』によれば、665年には百済の男女400余人が近江国の神前郡かんざきのこおりに、666年には2000余人"},{"id":"korea-japan-state-t18","k":"trivia","kj":"こぼれ話","t":"長安とは違った藤原京","l":"korea-japan-state","x":"藤原京は、唐の長安にならって、碁盤の目のように道路を区画した都城（条坊制）であった。しかし、発掘の結果、藤原京は、東西・南北ともに約5.3kmの正方形で、その中央に宮殿（藤原宮）が"},{"id":"korea-japan-state-t19","k":"source","kj":"史料","t":"「倭」から「日本」へ――外国の史書の記録","l":"korea-japan-state","x":"倭国が、国号を日本と改めた。自ら言うには、日の出る所に近いので、それを国の名としたという。（『三国史記』新羅本紀 文武王10年（670年）12月条より抄訳）日本国は、倭国の別種であ"},{"id":"korea-japan-state-t20","k":"trivia","kj":"こぼれ話","t":"年号「大宝」と対馬の金","l":"korea-japan-state","x":"701年、対馬から金が献上されたことを祝って、年号が「大宝」と定められた。日本の年号は、大宝以降、現在の「令和」まで途切れることなく続いている（大化の後は、年号が使われない時期があ"},{"id":"korea-japan-state-t21","k":"view","kj":"視点を変える","t":"「小中華」をめざした日本","l":"korea-japan-state","x":"律令国家となった日本は、唐に対しては朝貢の使者を送りつつも、冊封は受けなかった。そして国内では、自らを中国にならった「中華」の国とみなし、新羅や渤海を「蕃国」（日本に従う国）、東北"},{"id":"korea-japan-state-t22","k":"now","kj":"いま","t":"古代史をめぐる現代の論争","l":"korea-japan-state","x":"古代の朝鮮半島の歴史は、現代の国家どうしの対立とも結びついている。中国は、2002年から2007年にかけて、国家の研究事業「東北工程」を進め、高句麗を「中国の地方政権」とする見解を"},{"id":"korea-japan-state-t23","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"korea-japan-state","x":"手塚治虫『火の鳥 太陽編』（1986〜1988年）：白村江の戦いで敗れた百済の王族の青年が、倭に渡って壬申の乱に巻き込まれていく。古代と未来の二つの物語が並行して進む漫画。里中満智"},{"id":"kush-t1","k":"trivia","kj":"こぼれ話","t":"「弓の国」","l":"kush","x":"エジプト人はヌビアを「タ＝セティ（弓の国）」とも呼んだ。ヌビアの人々は、すぐれた弓の射手として知られ、エジプトの軍隊にも傭兵としてたびたび雇われていた。中王国時代の墓からは、ヌビア"},{"id":"kush-t2","k":"view","kj":"視点を変える","t":"「エジプトの総督の墓」とされたケルマ","l":"kush","x":"20世紀の初め、アメリカの考古学者ライスナーは、ケルマの遺跡を初めて本格的に発掘した。しかしライスナーは、これほど大規模な遺跡を、ヌビアの人々自身が築いたとは考えなかった。彼は、ケ"},{"id":"kush-t3","k":"source","kj":"史料","t":"奪われた密書――ヒクソスとクシュの同盟","l":"kush","x":"テーベの王カーメスは、ヒクソスとの戦いの記録を石碑に残している。その中に、カーメスの兵が砂漠の道で捕らえた使者が持っていた手紙の内容がある。ヒクソスの王アペピが、クシュの王に宛てた"},{"id":"kush-t4","k":"source","kj":"史料","t":"「馬を飢えさせたことが、何よりも許せぬ」","l":"kush","x":"ピイは、遠征の経過を大きな石碑（ピイの戦勝碑）に刻ませた。その中に、王の人柄をうかがわせる場面がある。中部エジプトの町ヘルモポリスを攻め落としたピイは、降伏した町の王ニムロトの宮殿"},{"id":"kush-t5","k":"trivia","kj":"こぼれ話","t":"石臼にされた神学書","l":"kush","x":"大英博物館に、表面の中央部分が丸くすり減った黒い石板がある。第25王朝の王シャバカが、メンフィスの神殿にあった古い文書を写させて刻ませたもので、「シャバカ石」と呼ばれる。メンフィス"},{"id":"kush-t6","k":"now","kj":"いま","t":"読めるのに意味が分からない文字","l":"kush","x":"メロエ文字には、ヒエログリフの形を借りた神聖な書体と、それをくずした筆記体の2種類がある。1909年、イギリスの学者グリフィスは、エジプト語とメロエ語の両方で書かれた王の名などを手"},{"id":"kush-t7","k":"trivia","kj":"こぼれ話","t":"踏みつけられた皇帝の首","l":"kush","x":"1910年、メロエの遺跡を発掘していたイギリスの考古学者ガースタングは、小さな神殿の入口の階段の下から、ブロンズ製の人の頭部を掘り出した。それは、ガラスと石をはめこんだ目が生き生き"},{"id":"kush-t8","k":"confuse","kj":"混同注意","t":"ヌビア・クシュ・エチオピア・アクスム","l":"kush","x":"名称指すもの注意点ヌビアナイル川の急流地帯を中心とする地方（現在のエジプト南部〜スーダン北部）地方名クシュヌビアに栄えた王国（ケルマ、ナパタ、メロエ）。エジプト人の呼び名時代によっ"},{"id":"kush-t9","k":"now","kj":"いま","t":"内戦にさらされる遺産","l":"kush","x":"メロエのピラミッド群を含む「メロエ島の古代遺跡群」は、2011年にユネスコの世界遺産に登録された。また、ゲベル＝バルカルとナパタ地方の遺跡群も、2003年に世界遺産となっている。メ"},{"id":"kush-t10","k":"debate","kj":"諸説あり","t":"アフリカの鉄はどこから来たか","l":"kush","x":"メロエのほかにも、サハラ以南のアフリカでは古くから鉄が作られていた。ナイジェリアのノク文化は、独特の素焼きの人物像で知られるが、前1千年紀の半ばには鉄を作っていた。アフリカの製鉄技"},{"id":"kushan-t1","k":"source","kj":"史料","t":"ミリンダ王の問い","l":"kushan","x":"仏典『ミリンダ王の問い』（パーリ語）は、ギリシア人の王ミリンダ（メナンドロス）と、インドの仏僧ナーガセーナとの問答の形で、仏教の教えを説いた書物である。ギリシアの哲学的な問いと、イ"},{"id":"kushan-t2","k":"source","kj":"史料","t":"『後漢書』が記すクシャーナ朝の成立","l":"kushan","x":"月氏は、匈奴に滅ぼされてから、大夏（バクトリア）に移り住み、その国を休密・双靡・貴霜・肸頓・都密の五部に分け、それぞれに翕侯（諸侯）を置いた。その後百年あまりして、貴霜の翕侯である"},{"id":"kushan-t3","k":"now","kj":"いま","t":"ベグラムの宝物","l":"kushan","x":"1937年と1939年、フランスの考古学者たちは、アフガニスタンのカーブルの北のベグラム（古代のカーピシー、クシャーナ朝の夏の都とされる）で、封印された二つの部屋を発見した。中から"},{"id":"kushan-t4","k":"source","kj":"史料","t":"中国の仏典が記す「四天子」","l":"kushan","x":"4世紀末に漢訳された仏典『十二遊経』には、当時の世界を4人の「天子」が分け合っているという、興味深い記述がある。閻浮提（人間の住む世界）には四人の天子がいる。東には晋の天子がいて、"},{"id":"kushan-t5","k":"confuse","kj":"混同注意","t":"上座部仏教と大乗仏教","l":"kushan","x":"上座部仏教大乗仏教目指すもの出家者が修行して、自らが悟りを開く（解脱）菩薩の慈悲の行いによって、多くの人々を救う（衆生救済）理想の人間像修行を完成した聖者（阿羅漢）菩薩在家信者の救"},{"id":"kushan-t6","k":"debate","kj":"諸説あり","t":"最初の仏像はどこでつくられたのか","l":"kushan","x":"仏像が、ガンダーラとマトゥラーのどちらで先につくられたのかについては、20世紀の初めから論争が続いている。ヨーロッパの研究者の多くは、ギリシア人の影響を受けたガンダーラで仏像が生ま"},{"id":"kushan-t7","k":"confuse","kj":"混同注意","t":"ガンダーラ美術・マトゥラー美術・グプタ様式","l":"kushan","x":"ガンダーラ美術マトゥラー美術グプタ様式時代1〜5世紀ごろ（最盛期は2〜3世紀）1〜3世紀ごろ（クシャーナ朝期）4〜6世紀（グプタ朝）地域西北インド（現パキスタン北部・アフガニスタン"},{"id":"kushan-t8","k":"myth","kj":"俗説","t":"法隆寺の柱はギリシアから来た？","l":"kushan","x":"奈良の法隆寺の柱は、中ほどがわずかにふくらんでいる。これがギリシアのパルテノン神殿の柱のふくらみ（エンタシス）と同じであり、ギリシアの建築の技法がシルクロードを通って日本に伝わった"},{"id":"later-han-t1","k":"confuse","kj":"混同注意","t":"王莽の主な政策","l":"later-han","x":"政策内容結果王田制全国の土地を「王田」として国有とし、売買を禁止。8人以下の家で土地が1井（約900畝）を超えれば、余分を親族や村人に分け与えさせた豪族の激しい反発で3年後に撤回奴"},{"id":"later-han-t2","k":"now","kj":"いま","t":"日本で出土する王莽の貨幣","l":"later-han","x":"王莽の時代に発行された「貨泉」という銅銭は、日本の弥生時代の遺跡からも数多く出土している。貨泉は、新の滅亡後まもなく使われなくなったため、出土した地層の年代を知る手がかりにもなる。"},{"id":"later-han-t3","k":"view","kj":"視点を変える","t":"王莽は「悪人」だったのか","l":"later-han","x":"王莽は、長い間、漢の帝位を奪った「簒奪者」として、儒学者たちから厳しく非難されてきた。後漢の歴史家班固の『漢書』も、王莽を偽善者として描いている。しかし、20世紀になると、王莽の土"},{"id":"later-han-t4","k":"trivia","kj":"こぼれ話","t":"「隴を得て蜀を望む」と青年劉秀の夢","l":"later-han","x":"光武帝は、西方の隴西（甘粛）を平定したのち、さらに四川の蜀を攻める将軍に、「人は足ることを知らないのに苦しむものだ。隴を平定すると、また蜀を望む」と書き送った。一つの望みがかなうと"},{"id":"later-han-t5","k":"source","kj":"史料","t":"『後漢書』東夷伝の倭の記事","l":"later-han","x":"建武中元2年（57年）、倭の奴国が貢ぎ物を奉じて朝賀した。使者は自ら大夫と称した。倭国の最も南の境にある。光武帝は、印と綬（ひも）を賜った。安帝の永初元年（107年）、倭国王の帥升"},{"id":"later-han-t6","k":"myth","kj":"俗説","t":"「跋扈将軍」梁冀","l":"later-han","x":"2世紀半ば、外戚の梁冀（りょうき）は、20年近くにわたって権力をほしいままにした。8歳で即位した質帝は、朝廷の会議で梁冀を見て、「これは跋扈将軍（のさばり将軍）だ」と言った。これを"},{"id":"later-han-t7","k":"source","kj":"史料","t":"「蒼天すでに死す」","l":"later-han","x":"蒼天すでに死す、黄天まさに立つべし。歳は甲子に在り、天下大吉。出典：『後漢書』皇甫嵩伝（本サイト訳）「蒼天」は後漢王朝を、「黄天」は太平道の天を指し、甲子の年（184年）に新しい世"},{"id":"later-han-t8","k":"confuse","kj":"混同注意","t":"太平道と五斗米道","l":"later-han","x":"太平道五斗米道創始者張角張陵（張道陵）地域華北（河北・山東・河南など）四川・漢中教え病気は罪の報い。懺悔と符水で治る病気治療と懺悔。入信者は米5斗を納める行動184年、黄巾の乱を起"},{"id":"later-han-t9","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"later-han","x":"『三国志演義』：明代に書かれた歴史小説で、黄巾の乱から始まり、魏・呉・蜀の三国の興亡を描く。日本では吉川英治『三国志』（1939〜1943年連載）、横山光輝の漫画『三国志』、ゲーム"},{"id":"macedonia-t1","k":"now","kj":"いま","t":"マケドニアは誰のものか","l":"macedonia","x":"古代のマケドニア人が「ギリシア人」だったのかどうかは、学問上の問題であるだけでなく、現代の国際問題とも結びついてきた。1991年、ユーゴスラヴィアから独立した国が「マケドニア共和国"},{"id":"macedonia-t2","k":"source","kj":"史料","t":"「フィリッポス弾劾演説」","l":"macedonia","x":"アテネの弁論家デモステネスは、フィリッポスをギリシアの自由を奪う独裁者とみなし、民会でたびたび演説して、マケドニアへの抵抗を訴えた。これらの演説は「フィリッピカ（フィリッポス弾劾演"},{"id":"macedonia-t3","k":"trivia","kj":"こぼれ話","t":"カイロネイアの獅子","l":"macedonia","x":"テーベの神聖隊は、150組300人の男性どうしの恋人たちで編成された精鋭部隊で、恋人の前で臆病な姿は見せられないと、互いに命がけで戦ったという。カイロネイアの戦いで、神聖隊はほぼ全"},{"id":"macedonia-t4","k":"now","kj":"いま","t":"ヴェルギナの王墓","l":"macedonia","x":"1977年、ギリシアの考古学者アンドロニコスは、ギリシア北部のヴェルギナで、盗掘を免れた王の墓を発見した。墓の中からは、黄金の箱に納められた遺骨が見つかった。箱のふたには、マケドニ"},{"id":"maurya-t1","k":"source","kj":"史料","t":"ギリシア人が見たパータリプトラ","l":"maurya","x":"和平ののち、セレウコスは、メガステネスを大使としてチャンドラグプタの宮廷に送った。メガステネスは、インドでの見聞を『インド誌』にまとめた。原本は失われたが、のちのギリシア・ローマの"},{"id":"maurya-t2","k":"debate","kj":"諸説あり","t":"『実利論』とカウティリヤ","l":"maurya","x":"インドの伝承では、チャンドラグプタが王位につくのを助けた宰相は、バラモンのカウティリヤ（チャーナキヤ）であったとされる。そして、カウティリヤが、国家の統治の技術について記した書物が"},{"id":"maurya-t3","k":"myth","kj":"俗説","t":"断食して亡くなった王","l":"maurya","x":"ジャイナ教の伝承によれば、チャンドラグプタは、晩年に王位を息子に譲って、ジャイナ教の修行者となり、南インドのシュラヴァナベラゴラで、断食によって生涯を終えたという伝承。シュラヴァナ"},{"id":"maurya-t4","k":"source","kj":"史料","t":"カリンガ征服の後悔――磨崖碑第13章","l":"maurya","x":"天愛喜見王（アショーカ王）が即位して8年がたったとき、カリンガ国が征服された。15万の人々がそこから連れ去られ、10万の人々がそこで殺され、さらにその何倍もの人々が死んだ。それから"},{"id":"maurya-t5","k":"view","kj":"視点を変える","t":"アショーカは「平和主義者」だったのか","l":"maurya","x":"アショーカは、戦争を放棄した平和の王として、しばしば理想化されて語られる。しかし、碑文を詳しく読むと、それとは異なる面も見えてくる。たとえば、磨崖碑第13章は、帝国の周辺の森に住む"},{"id":"maurya-t6","k":"source","kj":"史料","t":"ルンビニーの石柱碑","l":"maurya","x":"1896年、ネパール南部で、地中に半ば埋もれた石柱が発見された。そこには、次のように刻まれていた。天愛喜見王は、即位20年に、自らここに来て礼拝した。ここでブッダ・シャーキャムニが"},{"id":"maurya-t7","k":"now","kj":"いま","t":"インドの国章とアショーカ王","l":"maurya","x":"ブッダが初めて説法を行ったサールナートに、アショーカが建てた石柱の頂上には、4頭のライオンが背中合わせに座る、見事な彫刻（柱頭）がのせられていた。1950年、インド共和国は、このラ"},{"id":"maurya-t8","k":"confuse","kj":"混同注意","t":"インドの古代の主な王朝と宗教","l":"maurya","x":"王朝時代中心主な王宗教・文化マウリヤ朝前4世紀末〜前2世紀初めガンジス川流域（都パータリプトラ）チャンドラグプタ、アショーカアショーカが仏教を保護。ダルマの政治、磨崖碑・石柱碑クシ"},{"id":"maurya-t9","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"maurya","x":"映画『アショーカ』（2001年、インド、シャー・ルク・カーン主演）：若き日のアショーカ王の恋と戦いを、カリンガ征服までを中心に描いたインド映画。王の若い時代については史料がほとんど"},{"id":"maya-teotihuacan-t1","k":"trivia","kj":"こぼれ話","t":"チョコレートはマヤから","l":"maya-teotihuacan","x":"チョコレートの原料のカカオは、中央アメリカ原産の植物である。マヤの人々は、カカオの豆をすりつぶし、水やトウモロコシの粉、トウガラシなどを混ぜて、泡立てた飲み物にして飲んだ。甘くはな"},{"id":"maya-teotihuacan-t2","k":"myth","kj":"俗説","t":"スペイン人が焼いたマヤの書物","l":"maya-teotihuacan","x":"マヤの人々は、イチジク科の木の樹皮からつくった紙に、文字や絵を書いて、屏風のように折りたたんだ書物（コデックス）をつくった。しかし、16世紀にユカタン半島に来たスペインの修道士ディ"},{"id":"maya-teotihuacan-t3","k":"myth","kj":"俗説","t":"2012年人類滅亡説","l":"maya-teotihuacan","x":"2012年12月21日は、長期暦の「13.0.0.0.0」、つまり、神話上の世界の始まりから13バクトゥンが完了する日にあたった。これを根拠に、「マヤの予言では2012年に世界が終"},{"id":"maya-teotihuacan-t4","k":"trivia","kj":"こぼれ話","t":"地下の水銀の湖","l":"maya-teotihuacan","x":"2003年、テオティワカンの「羽毛のある蛇の神殿」の前で、大雨の後に地面に穴があいた。調査すると、その下には、地下約17mの深さを100m以上にわたって神殿の下まで続く、人工のトン"},{"id":"maya-teotihuacan-t5","k":"debate","kj":"諸説あり","t":"征服か、同盟か","l":"maya-teotihuacan","x":"378年の出来事を、テオティワカンによるティカルの軍事的な征服とみる研究者は多い。王の死と新しい王の即位が、よそ者の到来と同時に起こっていること、テオティワカンの戦士の姿が強調され"},{"id":"maya-teotihuacan-t6","k":"now","kj":"いま","t":"レーザーで見つかった「森の下の都市」","l":"maya-teotihuacan","x":"近年、マヤ文明の研究は、新しい技術によって大きく変わりつつある。航空機から地上にレーザー光線を照射して、木々の下の地形を測る「ライダー（LiDAR）」の技術を使うと、熱帯雨林におお"},{"id":"maya-teotihuacan-t7","k":"works","kj":"作品紹介","t":"マヤ・メソアメリカにまつわる作品","l":"maya-teotihuacan","x":"『ポポル・ヴフ』：16世紀に、グアテマラ高地のキチェ・マヤの人々が、ラテン文字を使って書き残した神話と歴史の書。神々が、泥や木で人間をつくろうとして失敗し、最後にトウモロコシから人"},{"id":"mesopotamia-unification-t1","k":"confuse","kj":"混同注意","t":"「セム語系」とは","l":"mesopotamia-unification","x":"アッカド人、のちのアムル人、アラム人、フェニキア人、ヘブライ人、アラブ人などは、言語の系統から「セム語系」の民族と呼ばれる。旧約聖書でノアの息子セムの子孫とされたことにちなむ、19"},{"id":"mesopotamia-unification-t2","k":"person","kj":"人物","t":"名前の分かる世界最初の作家――エンヘドゥアンナ","l":"mesopotamia-unification","x":"サルゴンは、娘のエンヘドゥアンナを、シュメールの古都ウルの月神ナンナの最高神官に任じた。征服者アッカド人の王女を、シュメール人の宗教の中心に送り込んだわけで、シュメール人を宗教の面"},{"id":"mesopotamia-unification-t3","k":"debate","kj":"諸説あり","t":"アッカドはなぜ滅んだのか","l":"mesopotamia-unification","x":"アッカド王国は、前2200年ごろから急速に衰え、東の山地から侵入してきたグティ人などによって滅ぼされた。後世のメソポタミアの人々は、ナラム＝シンがニップルのエンリル神殿を破壊したた"},{"id":"mesopotamia-unification-t4","k":"source","kj":"史料","t":"「目には目を」ではなかった最古の法典","l":"mesopotamia-unification","x":"ウル＝ナンム法典の特徴は、多くの罪に対して、銀による賠償を定めていることである。たとえば、「もし人が、他人の目を〔武器で〕損なったならば、銀2分の1ミナを支払わなければならない」「"},{"id":"mesopotamia-unification-t5","k":"trivia","kj":"こぼれ話","t":"1日で160キロ走った王？","l":"mesopotamia-unification","x":"ウル＝ナンムの子シュルギ王は、48年間にわたって王国を治め、自らをたたえる讃歌をいくつも作らせた。その一つでは、シュルギがニップルとウルの間、約160キロメートルを1日で走って往復"},{"id":"mesopotamia-unification-t6","k":"source","kj":"史料","t":"「ウル滅亡哀歌」","l":"mesopotamia-unification","x":"ウル第3王朝の滅亡の後、シュメール人はその悲劇を哀歌に詠んだ。そこでは、都を見捨てた神々を責めながら、荒廃した町の様子がこう描かれている。「都の城壁には、壊れた土器のかけらのように"},{"id":"mesopotamia-unification-t7","k":"source","kj":"史料","t":"マリ文書――古代の外交官たちの手紙","l":"mesopotamia-unification","x":"ハンムラビの時代の国際関係を生き生きと伝えるのが、ユーフラテス川中流の王国マリの宮殿跡から見つかった、約2万5000枚の粘土板文書（マリ文書）である。その中には、各地に派遣されたマ"},{"id":"mesopotamia-unification-t8","k":"confuse","kj":"混同注意","t":"年代の数字は確かなのか――「中年代説」","l":"mesopotamia-unification","x":"この回に出てきた「ハンムラビの在位：前1792〜前1750年」「バビロン陥落：前1595年」といった年代は、実はかなり不確かなものである。メソポタミアの年代は、王名表などから相対的"},{"id":"mongol-rise-t1","k":"confuse","kj":"混同注意","t":"遊牧は「さまよう」ことではない","l":"mongol-rise","x":"遊牧民というと、あてもなく草原をさまよう人々を想像しがちだが、実際は違う。夏営地・冬営地などの宿営地はおおむね決まっていて、毎年ほぼ同じ経路を回る。冬営地は風を避けられる山の南斜面"},{"id":"mongol-rise-t2","k":"life","kj":"暮らし","t":"遊牧民は何を食べていたか","l":"mongol-rise","x":"主食は肉と乳である。南宋の使節の報告書『黒韃事略』には「其の食は肉にして粒（穀物）にあらず」とあり、狩りで得たウサギ・シカ・野生のヒツジのほか、家畜では羊を常食とし、馬は大きな宴会"},{"id":"mongol-rise-t3","k":"source","kj":"史料","t":"『元朝秘史』とはどんな本か","l":"mongol-rise","x":"『元朝秘史』は、チンギス＝カンの祖先の伝説からオゴデイの治世までを描いた、モンゴル人自身による最古の歴史書である。もとはウイグル文字のモンゴル語で書かれたが、その原本は残っていない"},{"id":"mongol-rise-t4","k":"trivia","kj":"こぼれ話","t":"テムジンは犬が苦手だった？","l":"mongol-rise","x":"秘史には、父イェスゲイがテムジンを婚家に預ける際、「この子は犬を怖がるから、犬に驚かさないでやってくれ」と頼んだという一節がある（§66）伝承。遊牧民の宿営地には番犬がいて、見知ら"},{"id":"mongol-rise-t5","k":"person","kj":"人物","t":"ジェルメとジェベ――二人の部下の逸話","l":"mongol-rise","x":"秘史には、テムジンと部下の結びつきを示す有名な場面がいくつもある。タイチウト氏との戦いで、テムジンは首に矢を受けて倒れた。部下のジェルメは一晩中その傷口から血を吸い出し、さらに「喉"},{"id":"mongol-rise-t6","k":"trivia","kj":"こぼれ話","t":"ナイマンの金印とウイグル文字","l":"mongol-rise","x":"ナイマン部を破ったとき、モンゴル軍は印章を大事そうに抱えて逃げる男を捕らえた。ウイグル人の書記タタトゥンガ（塔塔統阿）である。問いただすと、これは王の命令を伝えるときに押す印で、文"},{"id":"mongol-rise-t7","k":"confuse","kj":"混同注意","t":"「ハン」「カン」「ハーン」の違い","l":"mongol-rise","x":"教科書でも「チンギス＝ハン」「チンギス＝カン」と表記が揺れている。もとのモンゴル語の称号はカン（qan）で、のちにこれを日本語では「ハン」と書くことが多かった。最近の山川の教科書は"},{"id":"mongol-rise-t8","k":"trivia","kj":"こぼれ話","t":"「長いひげの男」耶律楚材","l":"mongol-rise","x":"耶律楚材は遼の王族の子孫で、金に仕えていた。チンギスは「遼を滅ぼした金は、お前の一族の仇だろう」と声をかけて召し抱えた。楚材が「私の父祖は金に仕えておりました。どうして主君を仇と思"},{"id":"mongol-rise-t9","k":"debate","kj":"諸説あり","t":"事件の責任は誰にあったのか","l":"mongol-rise","x":"オトラル事件の責任がどこにあったかは、史料によって書き方が違う。ホラズム側の書記官だったナサウィーは、総督イナルチュクの欲に原因を求めているが、スルタンのムハンマド2世が事件を黙認"},{"id":"mongol-rise-t10","k":"view","kj":"視点を変える","t":"征服された側の声――イブン＝アル＝アシールの嘆き","l":"mongol-rise","x":"モンゴルの侵攻を同時代に記録したアラブの歴史家イブン＝アル＝アシールは、この出来事を書き始める前に、こう記している。لقد بقيت عدة سنين معرضاً عن ذكر "},{"id":"mongol-rise-t11","k":"source","kj":"史料","t":"「我は神の罰である」――ブハラの演説","l":"mongol-rise","x":"ペルシアの歴史家ジュワイニーは、ブハラに入城したチンギスが、町の有力者たちを集めて「お前たちは大きな罪を犯した。もしそうでなければ、神が私のような罰をお前たちの上に下すはずがない」"},{"id":"mongol-rise-t12","k":"war","kj":"戦術","t":"偽装退却――逃げると見せて誘い込む","l":"mongol-rise","x":"カルカ河畔の戦いは、モンゴル軍が得意とした「偽装退却」の典型例として知られる。ルーシとキプチャクの連合軍が迫ると、モンゴル軍は戦わずに後退を始めた。連合軍はこれを敗走と考え、9日間"},{"id":"mongol-rise-t13","k":"source","kj":"史料","t":"「どこから来て、どこへ消えたのか」――ノヴゴロド年代記","l":"mongol-rise","x":"ノヴゴロド第一年代記は、1224年（実際は1223年）の項にこう記している。「この年、我らの罪のために、見知らぬ民がやって来た。彼らが何者で、どんな言葉を話し、どんな種族で、どんな"},{"id":"mongol-rise-t14","k":"source","kj":"史料","t":"プラノ・カルピニが見たモンゴル兵の装備","l":"mongol-rise","x":"1245年、ローマ教皇の使節としてモンゴルを訪れた修道士プラノ・カルピニは、報告書にモンゴル軍の装備や戦い方を細かく書き残した。モンゴルの再来に備えるため、敵を知ろうとしたのである"},{"id":"mongol-rise-t15","k":"trivia","kj":"こぼれ話","t":"巻狩りは軍事演習だった","l":"mongol-rise","x":"モンゴルでは冬になると、大規模な巻狩り（ネルゲ）が行われた。数千の騎兵が広い範囲に輪を作り、何日もかけて輪を少しずつ縮めて、獲物を中央に追い込む。合図に従って隊列を保ち、勝手に獲物"},{"id":"mongol-rise-t16","k":"myth","kj":"俗説","t":"「マングダイ」「絹の肌着」――広まっている俗説","l":"mongol-rise","x":"モンゴル軍の偽装退却を「マングダイ」という戦術名で紹介する本やサイトがあるが、これは当時の用語ではない。マングトは秘史に出てくる部族の名前で、戦術名としての用法はおもに近年の歴史ゲ"},{"id":"mongol-rise-t17","k":"debate","kj":"諸説あり","t":"気候がモンゴルを後押しした？","l":"mongol-rise","x":"2014年、樹木の年輪を調べた研究チームが、興味深い説を発表した。モンゴル高原では1180年代に厳しい干ばつが続いたが、1211年から1225年にかけては、過去千年あまりで例を見な"},{"id":"mongol-rise-t18","k":"now","kj":"いま","t":"現代から見たチンギス＝カン","l":"mongol-rise","x":"チンギス＝カンの評価は、立場によって大きく違う。モンゴル国では「建国の父」として敬われ、首都の空港や紙幣にもその名や肖像が使われている。ただ、ソ連の影響下にあった時代には、民族主義"},{"id":"mongol-rise-t19","k":"debate","kj":"諸説あり","t":"「1600万人がチンギスの子孫」説","l":"mongol-rise","x":"2003年、ある遺伝学の研究が話題になった。アジアの広い範囲で、男性の約8パーセント、世界の男性の約0.5パーセントが同じY染色体の型を持ち、その起源は約1000年前のモンゴル高原"},{"id":"muhammad-t1","k":"term","kj":"用語","t":"「イスラーム」「ムスリム」「アッラー」","l":"muhammad","x":"「イスラーム」は、アラビア語で「（神に）身をゆだねること、服従すること」を意味する。イスラーム教を信じる人々を「ムスリム」（身をゆだねた者）と呼ぶ。日本では「イスラム教」「回教」と"},{"id":"muhammad-t2","k":"trivia","kj":"こぼれ話","t":"なぜムハンマドの肖像はないのか","l":"muhammad","x":"この講義では、ムハンマドの肖像画を掲載していない。イスラーム教では、偶像崇拝につながることを避けるため、預言者ムハンマドの姿を描くことは、一般にきびしく戒められているからである。た"},{"id":"muhammad-t3","k":"source","kj":"史料","t":"最古のアラビア語の碑文","l":"muhammad","x":"シリア南部のナマーラで、1901年に、1枚の石の墓碑が発見された。そこには、次のように刻まれていた。これは、すべてのアラブの王、アムルの子のイムルウルカイスの墓碑である。……彼はシ"},{"id":"muhammad-t4","k":"myth","kj":"俗説","t":"カーバ神殿に掛けられた詩","l":"muhammad","x":"6世紀のアラブの代表的な詩人たちの長い詩を集めたものが、『ムアッラカート』である。「ムアッラカート」とは「掛けられたもの」という意味で、ウカーズの市で優勝した詩が、金の文字で布に書"},{"id":"muhammad-t5","k":"source","kj":"史料","t":"『クルアーン』第106章「クライシュ族」","l":"muhammad","x":"クライシュ族の安全のために。冬と夏の隊商の旅の安全のために。彼らに、この家（カーバ）の主を崇めさせよ。飢えから彼らを養い、恐れから彼らを守られたお方を。（『クルアーン』第106章）"},{"id":"muhammad-t6","k":"debate","kj":"諸説あり","t":"メッカは国際商業の中心だったのか","l":"muhammad","x":"「メッカは、東西の国際交易の中継地として栄え、富の集中によって貧富の差が拡大し、部族の伝統的な絆が崩れた。その社会の矛盾の中から、イスラーム教が生まれた」――このような説明は、20"},{"id":"muhammad-t7","k":"trivia","kj":"こぼれ話","t":"黒石をめぐる争いと1枚の布","l":"muhammad","x":"605年ごろ、メッカのカーバ神殿は、洪水で傷んだため、建て直されることになった。工事が進み、神聖な黒石を壁にはめこむ段になって、クライシュ族の諸家の間で、誰がその名誉ある役を担うか"},{"id":"muhammad-t8","k":"person","kj":"人物","t":"ビラール――「唯一の神！唯一の神！」","l":"muhammad","x":"初期の信者の中には、奴隷や貧しい人々が多かった。アビシニア（エチオピア）出身の黒人の奴隷ビラールも、その一人であった。ビラールの主人は、彼をイスラームから離れさせようとして、真昼の"},{"id":"muhammad-t9","k":"myth","kj":"俗説","t":"夜の旅と昇天","l":"muhammad","x":"イスラームの伝承によれば、620年ごろのある夜、ムハンマドは、天使ジブリールに導かれ、ブラークと呼ばれる翼を持つ不思議な獣に乗って、メッカからエルサレムの神殿の丘へと一夜のうちに旅"},{"id":"muhammad-t10","k":"myth","kj":"俗説","t":"洞窟の入口のクモの巣","l":"muhammad","x":"伝承によれば、ムハンマドとアブー＝バクルが隠れていたサウル山の洞窟の前まで、追っ手がやってきた。ところが、洞窟の入口には、クモが巣を張り、ハトが巣をつくって卵を産んでいた。それを見"},{"id":"muhammad-t11","k":"source","kj":"史料","t":"メディナ憲章","l":"muhammad","x":"メディナ憲章は、ムハンマドとメディナの諸部族の間で結ばれた取り決めで、イブン・イスハークの『預言者伝』にその内容が伝えられている。彼ら（信者たち）は、他の人々とは別の、一つのウンマ"},{"id":"muhammad-t12","k":"source","kj":"史料","t":"『クルアーン』が語るバドルの戦い","l":"muhammad","x":"『クルアーン』第8章「戦利品」は、バドルの戦いを、次のように振り返っている。あなたがたが谷の近い側におり、彼らが遠い側にいて、隊商はあなたがたより低い所にいた時のことを思い起こせ。"},{"id":"muhammad-t13","k":"myth","kj":"俗説","t":"皇帝たちへの手紙","l":"muhammad","x":"イスラームの伝承によれば、フダイビーヤの和約の後、ムハンマドは、周辺の国々の支配者たちに、イスラームへの改宗を呼びかける手紙を送った。ビザンツ皇帝ヘラクレイオス、ササン朝の王ホスロ"},{"id":"muhammad-t14","k":"source","kj":"史料","t":"別離の説教","l":"muhammad","x":"伝承によれば、ムハンマドは、別離の巡礼の際に、次のように説いたという。人々よ。あなたがたの主は一つであり、あなたがたの父（アーダム）は一つである。アラブが非アラブに優ることはなく、"},{"id":"muhammad-t15","k":"trivia","kj":"こぼれ話","t":"最古の『クルアーン』写本","l":"muhammad","x":"2015年、イギリスのバーミンガム大学は、図書館が所蔵していた『クルアーン』の写本の2枚の羊皮紙について、放射性炭素による年代測定の結果、95％以上の確率で568年から645年の間"},{"id":"muhammad-t16","k":"now","kj":"いま","t":"現代の巡礼と二つの聖地","l":"muhammad","x":"現在、メッカとメディナは、サウジアラビアの領内にあり、ムスリムでない者が立ち入ることは禁じられている。毎年、ヒジュラ暦の第12月（巡礼月）には、世界中から約200万人のムスリムが、"},{"id":"muhammad-t17","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"muhammad","x":"映画『ザ・メッセージ』（1976年、ムスタファ・アッカド監督）：ムハンマドの生涯を描いた映画。イスラーム教の教えに従い、ムハンマド本人の姿や声は一度も画面に登場せず、カメラがムハン"},{"id":"neolithic-t1","k":"debate","kj":"諸説あり","t":"神殿が先か、農耕が先か――ギョベクリ＝テペ","l":"neolithic","x":"トルコ南東部のギョベクリ＝テペ遺跡は、考古学の常識を覆した遺跡として知られる。約1万1600年前（前9600年ごろ）にさかのぼるこの遺跡には、高さ5メートルを超えるT字形の石柱が円"},{"id":"neolithic-t2","k":"trivia","kj":"こぼれ話","t":"トウモロコシの祖先は似ても似つかない雑草だった","l":"neolithic","x":"トウモロコシの祖先は、メキシコの「テオシント」という野生の草である。テオシントの穂は親指ほどの大きさしかなく、硬い殻に包まれた実が10個ほどついているだけだった。現在のトウモロコシ"},{"id":"neolithic-t3","k":"debate","kj":"諸説あり","t":"「人類史上最悪の過ち」？","l":"neolithic","x":"アメリカの地理学者ダイアモンドは、農耕の始まりを「人類史上最悪の過ち」と呼んで話題を呼んだ。実際、初期の農耕民の人骨を調べると、狩猟採集民に比べて背が低く、虫歯や栄養不足、骨の病気"},{"id":"neolithic-t4","k":"trivia","kj":"こぼれ話","t":"パンよりビールが先？","l":"neolithic","x":"麦を育て始めた理由は、パンを作るためではなく、ビールを作るためだったのではないか――そんな説が、半ば冗談まじりに、しかし真剣に議論されてきた。2018年、イスラエルのラケフェト洞窟"},{"id":"neolithic-t5","k":"trivia","kj":"こぼれ話","t":"猫は「勝手に」家畜になった","l":"neolithic","x":"犬が人間の狩りのパートナーとして家畜になったのに対し、猫は少し違う経緯をたどった。農耕が始まり、村に穀物が蓄えられると、それを狙ってネズミが集まる。そのネズミを狙って、野生のヤマネ"},{"id":"northern-southern-t1","k":"trivia","kj":"こぼれ話","t":"「子貴ければ母死す」","l":"northern-southern","x":"北魏には、皇太子が決まると、その生母を殺すという、ほかに例のない制度があった。「子貴母死」（子が貴くなれば母は死ぬ）と呼ばれる。道武帝は、長男の拓跋嗣（のちの明元帝）を後継者と定め"},{"id":"northern-southern-t2","k":"person","kj":"人物","t":"柔然――「うごめく虫」と呼ばれた遊牧国家","l":"northern-southern","x":"柔然は、4世紀末から6世紀半ばにかけて、モンゴル高原を支配した遊牧国家である。402年ごろ、君主の社崙は「可汗」の称号を名乗った。可汗（カガン）は、のちに突厥やモンゴルの君主も用い"},{"id":"northern-southern-t3","k":"term","kj":"用語","t":"北魏の均田制","l":"northern-southern","x":"485年に定められた均田制は、隋・唐に受け継がれ、日本の班田収授法の手本にもなった重要な制度である。区分給付される土地返還露田（穀物を作る畑）15歳以上の男子に40畝、女子に20畝"},{"id":"northern-southern-t4","k":"source","kj":"史料","t":"鮮卑語の禁止","l":"northern-southern","x":"孝文帝は、鮮卑語の使用の禁止について、弟の咸陽王禧らに、次のように語ったという。今、北方の言葉を断ち、すべて正しい発音（漢語）に従わせようと思う。30歳以上の者は、長年の習慣になっ"},{"id":"northern-southern-t5","k":"debate","kj":"諸説あり","t":"漢化政策をどう評価するか","l":"northern-southern","x":"孝文帝の漢化政策については、さまざまな評価がある。積極的な評価：中国の伝統的な歴史家は、孝文帝を、「夷狄」の君主でありながら中華の文化を慕った名君としてたたえてきた。漢化政策によっ"},{"id":"northern-southern-t6","k":"trivia","kj":"こぼれ話","t":"永寧寺の九重塔","l":"northern-southern","x":"胡太后が516年に洛陽に建てた永寧寺には、高さ「90丈」（約270m）と記録される、木造の九重の塔がそびえていた。北魏の楊衒之が著した『洛陽伽藍記』は、この塔について、「都から10"},{"id":"northern-southern-t7","k":"source","kj":"史料","t":"勅勒の歌","l":"northern-southern","x":"玉壁の敗戦の後、高歓は、将兵の士気を高めるため、宴会を開いた。その席で、遊牧民の勅勒（高車）出身の老将斛律金に歌を歌わせ、高歓も、これに唱和して涙を流したという。そのとき歌われたと"},{"id":"northern-southern-t8","k":"trivia","kj":"こぼれ話","t":"「快刀乱麻を断つ」と蘭陵王","l":"northern-southern","x":"北斉の文宣帝高洋は、若いころ、口数が少なく、兄弟からも愚か者と見られていた。あるとき、父の高歓は、息子たちの才能を試そうと、もつれた糸の束を一人ずつ渡して、ほどくように命じた。他の"},{"id":"northern-southern-t9","k":"source","kj":"史料","t":"倭王武の上表文（478年）","l":"northern-southern","x":"南朝の宋には、東アジアの国々が使者を送った。日本列島の倭国からは、5世紀の約100年間に、讃・珍・済・興・武の5人の王（倭の五王）が使者を送り、宋の皇帝から称号を与えられた。478"},{"id":"northern-southern-t10","k":"confuse","kj":"混同注意","t":"北朝と南朝","l":"northern-southern","x":"北朝南朝王朝北魏→東魏・西魏→北斉・北周宋→斉→梁→陳都平城・洛陽（北魏）、鄴（東魏・北斉）、長安（西魏・北周）建康（現在の南京）支配者鮮卑系の皇室と軍人。漢人の名門も官僚として参"},{"id":"northern-southern-t11","k":"works","kj":"作品紹介","t":"南北朝にまつわる作品","l":"northern-southern","x":"「木蘭辞（木蘭詩）」（北朝の民歌）：年老いた父に代わって、男装して12年間戦場で戦った娘、木蘭の物語を歌った長編の詩。詩の中で、君主は「可汗」とも「天子」とも呼ばれており、遊牧民と"},{"id":"olmec-chavin-t1","k":"confuse","kj":"混同注意","t":"メソアメリカとアンデスを比べる","l":"olmec-chavin","x":"メソアメリカアンデス地域メキシコ中部・南部〜中央アメリカ南米のアンデス山脈と太平洋岸（ペルー・ボリビアなど）主な作物トウモロコシ、豆、カボチャ、唐辛子、カカオジャガイモ、トウモロコ"},{"id":"olmec-chavin-t2","k":"myth","kj":"俗説","t":"「人頭像はアフリカ人の顔」説","l":"olmec-chavin","x":"オルメカの巨石人頭像の顔立ちから、「古代にアフリカ人が大西洋を渡ってメキシコに来ていた証拠だ」とする説が、1970年代に唱えられ、一部で広まった。俗説しかし、オルメカの遺跡からは、"},{"id":"olmec-chavin-t3","k":"trivia","kj":"こぼれ話","t":"「ゴムの国の人々」と球技","l":"olmec-chavin","x":"「オルメカ」とは、オルメカ人自身の呼び名ではない。のちのアステカ人が、メキシコ湾岸に住む人々を「オルメカトル（ゴムの国の人々）」と呼んだことから、近代の研究者がこの名をつけたのであ"},{"id":"olmec-chavin-t4","k":"debate","kj":"諸説あり","t":"アメリカ大陸最古の文字？","l":"olmec-chavin","x":"2006年、オルメカの中心地サン＝ロレンソの近くで見つかった石板（カスカハル石板）の研究が、アメリカの科学雑誌に発表された。前900年ごろのものとされる石板の表面には、62個の記号"},{"id":"olmec-chavin-t5","k":"now","kj":"いま","t":"日本の調査団と「交差した手の神殿」","l":"olmec-chavin","x":"アンデス考古学は、日本の研究者が大きな役割を果たしてきた分野である。1960年、東京大学の泉靖一らの調査団は、ペルー中部の高地のコトシュ遺跡を発掘し、土器が使われる前の時代の神殿の"},{"id":"olmec-chavin-t6","k":"view","kj":"視点を変える","t":"「文明」の条件は一つではない","l":"olmec-chavin","x":"教科書では、文明の特徴として、農耕・都市・金属器・文字などが挙げられることが多い。しかし、アメリカ大陸の文明を見ると、この「条件」がそのまま当てはまらないことが分かる。アンデスの文"},{"id":"olmec-chavin-t7","k":"myth","kj":"俗説","t":"縄文土器は南米に渡ったか","l":"olmec-chavin","x":"エクアドルの太平洋岸のバルディビア遺跡からは、前3000年代のものとされる、アメリカ大陸でも最も古い部類の土器が見つかっている。1960年代、アメリカなどの研究者が、この土器の文様"},{"id":"olmec-chavin-t8","k":"life","kj":"暮らし","t":"闇の中で響くほら貝","l":"olmec-chavin","x":"チャビン＝デ＝ワンタルの神殿の地下回廊は、ほとんど光が入らない。回廊には、外から空気や水を通す細い溝が張りめぐらされており、水が流れると、神殿全体がうなるような音を立てたともいわれ"},{"id":"parthia-t1","k":"trivia","kj":"こぼれ話","t":"「パルティアン・ショット」","l":"parthia","x":"逃げながら振り返って後方に矢を射るパルティアの騎兵の戦法は、ローマ人に強烈な印象を与え、「パルティアン・ショット」と呼ばれた。英語には、立ち去り際に言い放つ痛烈な捨て台詞を意味する"},{"id":"parthia-t2","k":"source","kj":"史料","t":"漢の使者を迎えたパルティア","l":"parthia","x":"前2世紀末、武帝の使者がパルティアを訪れた。『史記』は、その様子を次のように記している。漢の使者が初めて安息に至ったとき、安息の王は、将軍に2万の騎兵を率いさせて、東の国境で出迎え"},{"id":"parthia-t3","k":"source","kj":"史料","t":"クラッススの首","l":"parthia","x":"クラッススの首が宮廷の入り口に届けられたとき、食事は片づけられ、悲劇役者のイアソンが、エウリピデスの『バッコスの信女たち』のアガウエの場面を歌っていた。……イアソンは、劇中で（ペン"},{"id":"parthia-t4","k":"now","kj":"いま","t":"隊商都市ハトラ","l":"parthia","x":"メソポタミア北部の砂漠の中にあったハトラは、パルティアの支配下で、アラブ人の王が治めた隊商都市であった。円形の二重の城壁に守られた町は、太陽神をまつる大神殿を中心に栄え、トラヤヌス"},{"id":"parthia-t5","k":"myth","kj":"俗説","t":"「バグダードの電池」","l":"parthia","x":"1930年代、バグダード近郊のパルティア時代（ササン朝時代とも）の遺跡から、素焼きの壺の中に銅の筒と鉄の棒が入った、奇妙な器が見つかった。これが、2000年前の「電池」で、金めっき"},{"id":"parthia-t6","k":"confuse","kj":"混同注意","t":"古代イランの3つの王朝","l":"parthia","x":"アケメネス朝パルティア（アルサケス朝）ササン朝時代前550〜前330年前247年ごろ〜後224年224（226）〜651年建国者キュロス2世アルサケスアルダシール1世担い手ペルシア"},{"id":"pax-romana-t1","k":"source","kj":"史料","t":"戦場で書かれた哲学――『自省録』","l":"pax-romana","x":"マルクス＝アウレリウスは、ドナウ川の前線の陣営で、夜ごとに、自分自身に向けた覚え書きをギリシア語で書きつけた。それが『自省録』である。そこには、皇帝としての重い責任と、ストア派の哲"},{"id":"pax-romana-t2","k":"trivia","kj":"こぼれ話","t":"大秦王安敦の使者","l":"pax-romana","x":"中国の歴史書『後漢書』には、166年に、「大秦王安敦」の使者が、日南郡（現在のベトナム中部）に到着し、象牙・犀の角・べっ甲を献上した、という記録がある。「大秦」は中国でのローマ帝国"},{"id":"pax-romana-t3","k":"now","kj":"いま","t":"ハドリアヌスの長城","l":"pax-romana","x":"ハドリアヌス帝の命令で122年ごろから築かれたハドリアヌスの長城は、ブリタニア（現在のイングランド北部）を東西に横切る、全長約118kmの石の壁である。壁に沿って、1ローマ・マイル"},{"id":"pax-romana-t4","k":"view","kj":"視点を変える","t":"「平和」は誰にとっての平和か","l":"pax-romana","x":"ローマの歴史家タキトゥスは、ブリタニアの首長カルガクスが、ローマ軍との決戦を前に部下たちに語ったとする演説を、次のように書いている。彼ら（ローマ人）は、略奪し、殺戮し、奪い取ること"},{"id":"pax-romana-t5","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"pax-romana","x":"塩野七生『ローマ人の物語』（1992〜2006年、全15巻）：ローマの建国から西ローマ帝国の滅亡までを、指導者たちの人物像を中心に描いた歴史エッセイ。五賢帝の時代は第9〜11巻で扱"},{"id":"peloponnesian-war-t1","k":"source","kj":"史料","t":"「本当の原因」――トゥキディデスの分析","l":"peloponnesian-war","x":"戦争の直接のきっかけは、コリントスとその植民市ケルキラ（コルフ島）の争いに、アテネが介入したことや、アテネがポテイダイアやメガラに圧力をかけたことだった。しかしトゥキディデスは、そ"},{"id":"peloponnesian-war-t2","k":"source","kj":"史料","t":"アテネの疫病――トゥキディデスの記録","l":"peloponnesian-war","x":"トゥキディデス自身もこの病にかかり、生き延びた。彼は、のちの人々が病を見分けられるようにと、その症状を詳しく書き残している。健康な者が、突然、頭に激しい熱を感じ、目が赤く充血した。"},{"id":"peloponnesian-war-t3","k":"source","kj":"史料","t":"「強者はなしうることをなし、弱者は受け入れねばならぬことを受け入れる」","l":"peloponnesian-war","x":"アテネの使節：正義というものは、力の等しい者どうしの間でこそ問題になるものだ。そうでない場合は、強者はなしうることをなし、弱者は受け入れねばならぬことを受け入れる。それが人間の世の"},{"id":"peloponnesian-war-t4","k":"trivia","kj":"こぼれ話","t":"エウリピデスの詩で救われた捕虜","l":"peloponnesian-war","x":"伝えられるところでは、シラクサの石切り場の捕虜のうち、アテネの悲劇作家エウリピデスの詩を暗唱できた者は、それを聞きたがったシラクサ人によって解放されたり、食べ物を与えられたりしたと"},{"id":"peloponnesian-war-t5","k":"confuse","kj":"混同注意","t":"ペロポネソス戦争の流れ","l":"peloponnesian-war","x":"年出来事前431年スパルタのアッティカ侵攻で開戦前430〜前429年アテネで疫病が流行。ペリクレス死去前421年ニキアスの和約前416年アテネがメロスを征服（メロス対話）前415〜"},{"id":"peloponnesian-war-t6","k":"view","kj":"視点を変える","t":"「ポリスの衰退」とは何だったのか","l":"peloponnesian-war","x":"前4世紀のポリスの変化は、しばしば「ポリスの衰退」と呼ばれる。その中身を見てみよう。戦争の長期化と農民の没落：長い戦争で畑は荒らされ、重装歩兵として戦ってきた中小の農民が没落した。"},{"id":"peloponnesian-war-t7","k":"now","kj":"いま","t":"「トゥキディデスの罠」","l":"peloponnesian-war","x":"2010年代、アメリカの政治学者グレアム＝アリソンは、トゥキディデスの「アテネの台頭とスパルタの恐怖」という分析にちなんで、「トゥキディデスの罠」という言葉を広めた。台頭する新興国"},{"id":"pericles-t1","k":"confuse","kj":"混同注意","t":"デロス同盟とペロポネソス同盟","l":"pericles","x":"デロス同盟ペロポネソス同盟盟主アテネスパルタ成立前478年前6世紀後半加盟国エーゲ海の島々、小アジア沿岸などのポリス（多くはイオニア人）ペロポネソス半島のポリス（コリントスなど）目"},{"id":"pericles-t2","k":"source","kj":"史料","t":"ペリクレスの葬送演説","l":"pericles","x":"ペロポネソス戦争の1年目の冬、ペリクレスは、戦死者を弔う国葬の場で演説を行った。歴史家トゥキディデスが記録した（再構成した）この「葬送演説」は、アテネの民主政の理想を語った言葉とし"},{"id":"pericles-t3","k":"trivia","kj":"こぼれ話","t":"抽選のための機械","l":"pericles","x":"アテネ人は、役人や陪審員を選ぶのに、選挙よりも抽選を重んじた。選挙では、弁が立ち、金があり、名の知れた者が選ばれやすい。抽選なら、すべての市民に平等に機会がある。アリストテレスは、"},{"id":"pericles-t4","k":"life","kj":"暮らし","t":"赤いロープで民会へ","l":"pericles","x":"民会は、成立のために一定の数の出席者が必要な議題もあった。しかし、市民の中には、アゴラで買い物やおしゃべりをして、民会になかなか来ない者もいた。アリストファネスの喜劇によれば、民会"},{"id":"pericles-t5","k":"confuse","kj":"混同注意","t":"アテネの民主政と現代の民主政","l":"pericles","x":"アテネの民主政現代の民主政（日本など）形態直接民主政（市民が民会に直接参加）間接民主政（選挙で代表を選ぶ）役人の選び方主に抽選主に選挙参政権成人男性市民のみ。女性・在留外人・奴隷は"},{"id":"pericles-t6","k":"trivia","kj":"こぼれ話","t":"まっすぐに見えるための曲線","l":"pericles","x":"パルテノン神殿は、まっすぐな直線でできているように見える。しかし実際には、ほとんどの線がわずかに曲がっている。床（基壇）は、中央が端より約10cm盛り上がっている。柱は、中ほどがわ"},{"id":"pericles-t7","k":"now","kj":"いま","t":"パルテノン神殿の彫刻はどこにあるべきか","l":"pericles","x":"パルテノン神殿の彫刻の約半分は、現在、ロンドンの大英博物館にある。19世紀の初め、オスマン帝国の駐在イギリス大使だったエルギン伯爵が、オスマン帝国の許可を得たとして、神殿の彫刻を切"},{"id":"persian-wars-t1","k":"source","kj":"史料","t":"「主君よ、アテネ人を忘れたもうな」","l":"persian-wars","x":"ヘロドトスによれば、サルデスが焼かれたと聞いたダレイオス1世は、まず「アテネ人とは何者か」と尋ねた。答えを聞くと、弓を取って天に向かって矢を放ち、「ゼウスよ、アテネ人に報復すること"},{"id":"persian-wars-t2","k":"trivia","kj":"こぼれ話","t":"悲劇『ミレトスの陥落』","l":"persian-wars","x":"ミレトスの陥落は、同じイオニア人のアテネ人に大きな衝撃を与えた。数年後、悲劇作家プリュニコスが、『ミレトスの陥落』という劇を上演すると、観客は皆泣き崩れた。アテネ人は、「同胞の不幸"},{"id":"persian-wars-t3","k":"myth","kj":"俗説","t":"マラソンの起源","l":"persian-wars","x":"マラトンの勝利を知らせるために、一人の兵士がアテネまで約40kmを走り続け、「喜べ、われらは勝った」と告げて息絶えた――。この話が、近代オリンピックの「マラソン」競技の起源となった"},{"id":"persian-wars-t4","k":"myth","kj":"俗説","t":"海をむち打った王","l":"persian-wars","x":"ヘロドトスによれば、ヘレスポントス海峡に最初にかけた船橋が嵐で壊れたとき、クセルクセスは怒り狂い、海を300回むちで打たせ、足かせを海に投げ込ませた。そして、むちを打つ者たちに、こ"},{"id":"persian-wars-t5","k":"source","kj":"史料","t":"「木の壁」の神託","l":"persian-wars","x":"ペルシアの大軍が迫る中、アテネがデルフォイに送った使者は、恐ろしい神託を受け取った。アテネは焼かれ、すべてが滅びるであろう、というのである。使者が嘆願すると、二度目の神託が下った。"},{"id":"persian-wars-t6","k":"source","kj":"史料","t":"「旅人よ、スパルタ人に伝えよ」","l":"persian-wars","x":"テルモピレーの戦いの後、戦死者を葬った丘には、詩人シモニデスの作とされる碑文が刻まれた。旅人よ、行きてスパルタ人に伝えよ。われらはその掟のままに、ここに伏すと。出典：ヘロドトス『歴"},{"id":"persian-wars-t7","k":"view","kj":"視点を変える","t":"「300人」の物語の陰で","l":"persian-wars","x":"テルモピレーの戦いは、映画や漫画などで「300人のスパルタ兵が100万の大軍に立ち向かった」物語として描かれることが多い。しかし実際には、戦いの最初の2日間、隘路を守ったのは約70"},{"id":"persian-wars-t8","k":"person","kj":"人物","t":"女性の提督アルテミシア","l":"persian-wars","x":"ペルシア艦隊には、小アジアのハリカルナッソス（ヘロドトスの故郷）の女王アルテミシアが、自ら5隻の船を率いて加わっていた。ヘロドトスによれば、アルテミシアは海戦の前の作戦会議で、ただ"},{"id":"persian-wars-t9","k":"confuse","kj":"混同注意","t":"ペルシア戦争の主な戦い","l":"persian-wars","x":"年戦いギリシア側の指揮官結果・意義前490年マラトンの戦いミルティアデス（アテネ）アテネの重装歩兵が勝利前480年テルモピレーの戦いレオニダス（スパルタ）ギリシア軍は全滅。ペルシア"},{"id":"persian-wars-t10","k":"view","kj":"視点を変える","t":"ペルシアから見たペルシア戦争","l":"persian-wars","x":"ペルシア戦争について、私たちが知っていることのほとんどは、ギリシア人、とくにヘロドトスの記録によっている。ペルシア側には、この戦争についての記録はほとんど残っていない。アケメネス朝"},{"id":"persian-wars-t11","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"persian-wars","x":"映画『300〈スリーハンドレッド〉』（2007年、原作はフランク・ミラーのグラフィック・ノベル）：テルモピュライの戦いを、劇画風の映像で描いた映画。スパルタ王レオニダスの300人の"},{"id":"phoenicia-aram-t1","k":"source","kj":"史料","t":"『ウェンアメン旅行記』――落ちぶれたエジプトの使者","l":"phoenicia-aram","x":"エジプトの勢いが衰えたことをよく示すのが、前11世紀ごろの『ウェンアメン旅行記』という文書である。テーベのアメン神殿に仕えるウェンアメンは、神の聖なる船を造るための杉材を買いつける"},{"id":"phoenicia-aram-t2","k":"trivia","kj":"こぼれ話","t":"「フェニキア」は紫の国","l":"phoenicia-aram","x":"フェニキア人の特産品として有名なのが、紫色の染料である。地中海にすむアクキガイ科の巻貝の分泌腺から取った染料で、色があせにくく、美しい赤紫色に染まった。しかし、1グラムの染料を得る"},{"id":"phoenicia-aram-t3","k":"trivia","kj":"こぼれ話","t":"「バイブル」の語源","l":"phoenicia-aram","x":"フェニキアの港町ビブロスは、エジプトからパピルスを輸入して、ギリシアなどに売る中継地でもあった。そこでギリシア人は、パピルスや書物のことを、町の名にちなんで「ビブロス」と呼ぶように"},{"id":"phoenicia-aram-t4","k":"source","kj":"史料","t":"牛の皮1枚分の土地","l":"phoenicia-aram","x":"カルタゴ建設については、こんな伝説が残っている。ティルスの王女エリッサ（ローマの詩人ウェルギリウスの作品ではディド）は、兄の王に夫を殺され、仲間とともにティルスを逃れて北アフリカに"},{"id":"phoenicia-aram-t5","k":"debate","kj":"諸説あり","t":"フェニキア人はアフリカを一周したか","l":"phoenicia-aram","x":"前5世紀のギリシアの歴史家ヘロドトスは、次のような話を記録している。前600年ごろ、エジプト王ネコ2世がフェニキア人の船団を紅海から南へ送り出した。船団は秋になると上陸して麦をまき"},{"id":"phoenicia-aram-t6","k":"confuse","kj":"混同注意","t":"「植民市」「属州」「植民地」の違い","l":"phoenicia-aram","x":"世界史には「植民」のつく言葉がたくさん出てくるが、時代によって意味がまったく違う。用語時代・主体内容本国との関係フェニキア人の植民市前12〜前8世紀ごろ交易の拠点として建てた港町当"},{"id":"phoenicia-aram-t7","k":"trivia","kj":"こぼれ話","t":"「A」は牛の頭だった","l":"phoenicia-aram","x":"アルファベットの最初の文字「A」をさかさまにしてみよう。角の生えた牛の頭に見えないだろうか。フェニキア文字の最初の文字は「アレフ」といい、セム語で「牛」を意味した。もとは牛の頭の形"},{"id":"phoenicia-aram-t8","k":"confuse","kj":"混同注意","t":"「最古のアルファベット」はどれか","l":"phoenicia-aram","x":"フェニキア文字より古い表音文字として、シリアの港町ウガリトで使われたウガリト文字がある。前14世紀ごろの文字で、楔形文字の形をしているが、約30の文字からなるアルファベットであった"},{"id":"phoenicia-aram-t9","k":"now","kj":"いま","t":"イエスの言葉は今も話されている","l":"phoenicia-aram","x":"1世紀にパレスチナで活動したイエスが日常話していたのは、アラム語だったと考えられている。『新約聖書』はギリシア語で書かれているが、その中には、イエスが十字架の上で叫んだ「エロイ、エ"},{"id":"phoenicia-aram-t10","k":"view","kj":"視点を変える","t":"文字は誰のものか","l":"phoenicia-aram","x":"「アルファベット」というと、ギリシア・ローマに始まるヨーロッパの文化と考えがちである。しかし、その源流をたどると、エジプトの文字を借りたセム語系の人々、そしてそれを地中海と西アジア"},{"id":"polis-t1","k":"confuse","kj":"混同注意","t":"「ポリス」と「都市国家」と「国家」","l":"polis","x":"ポリスは、日本語では「都市国家」と訳されることが多い。シュメール人の都市国家（2-01）や、中世イタリアの都市国家と同じ言葉である。しかし、それぞれの性格は異なる。シュメールの都市"},{"id":"polis-t2","k":"trivia","kj":"こぼれ話","t":"盾は「隣の仲間を守る」もの","l":"polis","x":"ファランクスでは、重装歩兵は左手に大きな丸い盾（ホプロン）をもった。この盾は、自分の体の左半分と、左隣の仲間の体の右半分を守った。そのため、隊列の兵士たちは、無防備な右側を守ろうと"},{"id":"polis-t3","k":"trivia","kj":"こぼれ話","t":"世界のへそ、デルフォイ","l":"polis","x":"デルフォイは、ギリシア中部のパルナッソス山の中腹にある、アポロン神をまつる聖地である。神話によれば、ゼウスが世界の両端から2羽のワシを放ったところ、2羽はデルフォイで出会った。その"},{"id":"polis-t4","k":"life","kj":"暮らし","t":"古代オリンピック","l":"polis","x":"オリンピアの祭典は、ゼウスをたたえる祭りで、伝承では前776年に始まり、4年ごとに開かれた。この最初の年は、のちにギリシア人が年代を数える基準にもなった。祭典の期間中は、ギリシア中"},{"id":"polis-t5","k":"source","kj":"史料","t":"「池のまわりのカエルのように」","l":"polis","x":"私たちは、パシスの川からヘラクレスの柱までの間の、ほんの小さな部分に住んでいるにすぎない。池のまわりに住むアリやカエルのように、海のまわりに住んでいるのだ。出典：プラトン『パイドン"},{"id":"polis-t6","k":"view","kj":"視点を変える","t":"「ギリシア＝ヨーロッパの源流」という見方","l":"polis","x":"古代ギリシアは、しばしば「ヨーロッパ文明の源流」と呼ばれる。しかし、当時のギリシア人の世界の中心は、エーゲ海であって、ヨーロッパ大陸ではなかった。ギリシア人のポリスは、小アジア（現"},{"id":"punic-wars-t1","k":"source","kj":"史料","t":"1隻の難破船から生まれた艦隊","l":"punic-wars","x":"歴史家ポリュビオスによれば、ローマ人は、浅瀬に乗り上げたカルタゴの五段櫂船（五段に漕ぎ手を配置した大型軍船）を手に入れ、それを手本にして、わずか60日ほどで100隻の五段櫂船を建造"},{"id":"punic-wars-t2","k":"source","kj":"史料","t":"9歳の誓い","l":"punic-wars","x":"ポリュビオスによれば、晩年のハンニバルは、自らの少年時代について、次のように語ったという。9歳のとき、父ハミルカルがイベリア半島への遠征に出発する前に、神々にいけにえを捧げた。父は"},{"id":"punic-wars-t3","k":"myth","kj":"俗説","t":"酢で岩を砕いた？","l":"punic-wars","x":"リウィウスによれば、アルプスを下る途中、巨大な岩が道をふさいだ。ハンニバルは、岩の周りに大量の木を積んで火をつけ、真っ赤に熱した岩に酢をかけて、もろくなった岩を砕いて道を開いたとい"},{"id":"punic-wars-t4","k":"view","kj":"視点を変える","t":"なぜローマは降伏しなかったのか","l":"punic-wars","x":"カンネーの大敗の後、南イタリアのカプアなど、多くの同盟市がローマを離れてハンニバルについた。ギリシアのマケドニア王も、ハンニバルと同盟を結んだ。しかし、ローマは降伏しなかった。ハン"},{"id":"punic-wars-t5","k":"person","kj":"人物","t":"ハンニバルのその後","l":"punic-wars","x":"敗戦後、ハンニバルはカルタゴの最高の役職に就き、政治を改革して財政を立て直した。しかし、ローマに危険視されて、カルタゴを追われた。セレウコス朝のアンティオコス3世のもとに亡命してロ"},{"id":"punic-wars-t6","k":"source","kj":"史料","t":"「カルタゴは滅ぼされねばならない」","l":"punic-wars","x":"ローマの政治家大カトーは、カルタゴを視察して、その繁栄ぶりに危機感を抱いた。プルタルコスによれば、カトーは元老院で、アフリカから持ち帰った大きく見事なイチジクを衣のひだから取り出し"},{"id":"punic-wars-t7","k":"myth","kj":"俗説","t":"カルタゴの土地に塩をまいた？","l":"punic-wars","x":"ローマ人はカルタゴを破壊した後、二度と作物が育たないように、その土地に塩をまいた――。この話は広く知られているが、古代の史料には見当たらない。この話が現れるのは、19世紀以降の書物"},{"id":"punic-wars-t8","k":"view","kj":"視点を変える","t":"カルタゴの側から見ると","l":"punic-wars","x":"カルタゴについて私たちが知っていることのほとんどは、ローマ人やギリシア人が書いたものである。カルタゴ自身の書物は、町の破壊とともにほとんど失われた（ローマはカルタゴの農学書だけはラ"},{"id":"punic-wars-t9","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"punic-wars","x":"カガノミハチ『アド・アストラ ―スキピオとハンニバル―』（漫画、2011〜2017年連載、全13巻）：第2次ポエニ戦争を、ハンニバルとスキピオの2人の天才の対決として描く。カンネー"},{"id":"qin-t1","k":"confuse","kj":"混同注意","t":"商鞅の変法の主な内容","l":"qin","x":"改革内容ねらい什伍の制民を5戸・10戸の組に編成し、犯罪を告発しない者も罰する連帯責任（連座）民衆の相互監視軍功爵制戦場で敵の首を取った数などに応じて、身分に関係なく爵位を与える兵"},{"id":"qin-t2","k":"myth","kj":"俗説","t":"自分の法に捕らえられた商鞅","l":"qin","x":"孝公が亡くなると、商鞅は、改革で特権を奪われた貴族たちに謀反の罪を着せられ、逃亡した。国境近くの宿屋に泊まろうとすると、宿の主人は、相手が商鞅とは知らずに言った。「商君の法では、身"},{"id":"qin-t3","k":"source","kj":"史料","t":"李斯の「逐客を諫むるの書」","l":"qin","x":"前237年、鄭国がスパイであったことが発覚すると、秦の王族や大臣たちは、他国から来た者（客）をすべて国外に追放すべきだと主張し、政もこれを命じた。楚出身の李斯も、追放されることにな"},{"id":"qin-t4","k":"source","kj":"史料","t":"荊軻の暗殺未遂","l":"qin","x":"秦の脅威にさらされた燕の太子丹は、刺客の荊軻を秦に送り込んだ。出発の日、易水のほとりで見送りの人々を前に、荊軻は歌った。風は蕭々として易水寒く、壮士ひとたび去りて、また還らず。出典"},{"id":"qin-t5","k":"source","kj":"史料","t":"封建か、郡県か","l":"qin","x":"周の文王・武王が封じた子弟や同姓の一族は、たいへん多かったが、その後、代を重ねるにつれて関係が疎遠になり、互いに仇敵のように攻撃し合い、諸侯は互いに殺し合って、周の天子もこれを止め"},{"id":"qin-t6","k":"trivia","kj":"こぼれ話","t":"1日30kgの書類","l":"qin","x":"『史記』によれば、始皇帝は、天下のことを、大小にかかわらずすべて自ら決裁した。毎日、決裁すべき文書の量を秤で量って定め、その量（1石＝120斤、約30kg）を処理し終えるまでは、昼"},{"id":"qin-t7","k":"confuse","kj":"混同注意","t":"始皇帝の統一政策","l":"qin","x":"統一したもの内容度量衡長さ・容積・重さの単位と基準を統一。標準の分銅（権）や升（量）をつくり、統一の詔を刻んで全国に配った貨幣各国の刀銭・布銭・蟻鼻銭などを廃止し、円形で四角い穴の"},{"id":"qin-t8","k":"debate","kj":"諸説あり","t":"埋められたのは「儒者」だったのか","l":"qin","x":"『史記』によれば、坑儒のきっかけは、始皇帝のために不老不死の仙薬を探していた方士（神仙術の専門家）たちが、仙薬を得られずに皇帝を批判して逃亡したことにあった。そこで始皇帝は、咸陽の"},{"id":"qin-t9","k":"source","kj":"史料","t":"鹿を馬と言う","l":"qin","x":"趙高は反乱を起こそうと考えたが、群臣が従わないことを恐れた。そこで、まず試してみようと、鹿を二世皇帝に献上して言った。「馬でございます」。二世は笑って言った。「丞相は間違えている。"},{"id":"qin-t10","k":"now","kj":"いま","t":"睡虎地秦簡と里耶秦簡","l":"qin","x":"1975年、湖北省雲夢県の睡虎地（すいこち）で、秦の地方役人「喜」の墓から、1155枚の竹簡が発見された。そこには、秦の法律の条文や、法律の解釈を問答形式で示した文書、裁判の手引き"},{"id":"qin-t11","k":"debate","kj":"諸説あり","t":"もう一つの始皇帝伝『趙正書』","l":"qin","x":"2009年に北京大学に寄贈された前漢時代の竹簡の中に、『趙正書』と名づけられた文書があった。そこでは、始皇帝は「趙正」と呼ばれ、死の床で、自ら胡亥を後継者に指名したことになっており"},{"id":"qin-t12","k":"trivia","kj":"こぼれ話","t":"「チャイナ」は「秦」から？","l":"qin","x":"英語の「チャイナ」（China）や、日本で使われた「支那」という呼び名は、「秦（チン）」が、インドで「チーナ」と呼ばれ、それがヨーロッパに伝わったものだとする説が広く知られている。"},{"id":"qin-t13","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"qin","x":"原泰久『キングダム』（漫画、2006年〜連載）：戦国時代末、のちの始皇帝となる秦王政（嬴政）と、天下の大将軍を目指す少年・信（のちの秦の将軍李信がモデル）を主人公に、秦の六国統一戦"},{"id":"roman-culture-t1","k":"source","kj":"史料","t":"「征服されたギリシアが、猛々しい勝者を征服した」","l":"roman-culture","x":"アウグストゥス時代の詩人ホラティウスは、ローマとギリシアの文化の関係を、次のように表現した。征服されたギリシアは、猛々しい勝者を征服し、粗野なラティウムに学芸をもたらした。出典：ホ"},{"id":"roman-culture-t2","k":"trivia","kj":"こぼれ話","t":"9月は「7番目の月」","l":"roman-culture","x":"英語の月の名前の多くは、ローマの暦に由来する。September（9月）は、ラテン語の「7（セプテム）」、October（10月）は「8（オクト）」、November（11月）は「"},{"id":"roman-culture-t3","k":"source","kj":"史料","t":"法学者ウルピアヌスの言葉","l":"roman-culture","x":"正義とは、各人にその権利を与えようとする、不変で永続的な意志である。……法の命じるところは、次のとおりである。誠実に生きること、他人を害さないこと、各人に各人のものを与えること。出"},{"id":"roman-culture-t4","k":"now","kj":"いま","t":"日本の民法とローマ法","l":"roman-culture","x":"『ローマ法大全』は、11世紀末から北イタリアのボローニャ大学などで熱心に研究され、ヨーロッパ各国の法律の土台となった。19世紀初めのフランス民法典（ナポレオン法典）や、19世紀末の"},{"id":"roman-culture-t5","k":"now","kj":"いま","t":"ローマのコンクリートはなぜ長持ちするのか","l":"roman-culture","x":"現代の鉄筋コンクリートの寿命は、ふつう数十年から100年ほどとされる。ところが、ローマのコンクリートの建物や港の防波堤は、2000年たっても崩れずに残っている。その理由については、"},{"id":"roman-culture-t6","k":"source","kj":"史料","t":"「無用のピラミッドと比べてみよ」","l":"roman-culture","x":"97年に首都ローマの水道長官となったフロンティヌスは、『水道書』を著して、水道の管理や不正な盗水の取り締まりについて記した。彼は、ローマの水道を、次のように誇っている。これほど多く"},{"id":"roman-culture-t7","k":"confuse","kj":"混同注意","t":"ローマ時代の学芸（「何語で書いたか」に注意）","l":"roman-culture","x":"分野人物主な作品書いた言葉ポイント叙事詩ウェルギリウス『アエネイス』ラテン語ローマの建国叙事詩叙情詩ホラティウス『歌章』ラテン語「征服されたギリシアが勝者を征服した」叙情詩オウィデ"},{"id":"roman-culture-t8","k":"view","kj":"視点を変える","t":"ローマ文化は「ギリシアの模倣」だったのか","l":"roman-culture","x":"かつて、ローマの文化は、独創性に乏しいギリシア文化の模倣にすぎない、と評価されることが多かった。たしかに、ローマの彫刻の多くはギリシアの作品の写しであり、ローマの神々の多くはギリシ"},{"id":"roman-life-t1","k":"source","kj":"史料","t":"小プリニウスの手紙","l":"roman-life","x":"噴火の様子は、当時17歳だった小プリニウスが、のちに歴史家タキトゥスに宛てて書いた2通の手紙によって、詳しく知ることができる。小プリニウスは、ナポリ湾の西の端のミセヌムにいた。伯父"},{"id":"roman-life-t2","k":"debate","kj":"諸説あり","t":"噴火は8月か、10月か","l":"roman-life","x":"ポンペイの噴火は、小プリニウスの手紙の写本の記述から、長く「79年8月24日」とされてきた。ところが、遺跡からは、秋に実るザクロやクルミ、ワインの仕込みが終わった壺、厚手の服を着た"},{"id":"roman-life-t3","k":"source","kj":"史料","t":"ポンペイの落書き","l":"roman-life","x":"「パン屋たちが、アエディリス（造営官）にグナエウス＝ヘルウィウス＝サビヌスを推す」（選挙のポスター）「ここで私は、一人の女の子とやった」（品のない自慢）「壁よ、おまえがこれほど多く"},{"id":"roman-life-t4","k":"source","kj":"史料","t":"「眠れない都市」","l":"roman-life","x":"1〜2世紀の詩人ユウェナリスは、首都ローマの暮らしのつらさを、皮肉たっぷりに描いている。この都で、眠りにつけるのは大金持ちだけだ。……狭い曲がりくねった道を行く荷車の騒音、身動きの"},{"id":"roman-life-t5","k":"source","kj":"史料","t":"「パンとサーカス」","l":"roman-life","x":"ユウェナリスは、政治に無関心になったローマ市民を、次のように皮肉った。かつて軍の指揮権や官職や、すべてを与えていた民衆は、今では自ら手を引き、ただ二つのことだけを熱心に求めている。"},{"id":"roman-life-t6","k":"life","kj":"暮らし","t":"コロッセウムと戦車競走","l":"roman-life","x":"80年に完成したコロッセウム（正式にはフラウィウス円形闘技場）は、約5万人の観客を収容できた。観客席の上には、日よけの巨大な布（ウェラリウム）を張ることができ、艦隊の水兵がその操作"},{"id":"roman-life-t7","k":"trivia","kj":"こぼれ話","t":"名前でわかる身分","l":"roman-life","x":"ローマの男性市民は、ふつう3つの名前をもっていた。たとえば、「ガイウス・ユリウス・カエサル」は、個人名（ガイウス）・氏族名（ユリウス）・家名（カエサル）からなる。個人名はガイウス、"},{"id":"roman-life-t8","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"roman-life","x":"ヤマザキマリ『テルマエ・ロマエ』（漫画、2008〜2013年連載）：ハドリアヌス帝の時代の浴場設計技師ルシウスが、現代日本の銭湯や温泉にタイムスリップし、そこで得たアイデアをローマ"},{"id":"rome-crisis-t1","k":"confuse","kj":"混同注意","t":"「属州」と「同盟市」と「植民地」","l":"rome-crisis","x":"イタリアの同盟市（3-13）属州（プロウィンキア）場所イタリア半島イタリアの外（シチリア、ヒスパニア、アフリカ、アシアなど）支配自治。ローマと個別に条約を結ぶローマから派遣された総"},{"id":"rome-crisis-t2","k":"source","kj":"史料","t":"キケロとウェッレスの裁判","l":"rome-crisis","x":"属州の総督たちの不正を象徴するのが、シチリアの総督ウェッレスの事件である。ウェッレスは、前73〜前71年の在任中、属州の人々から財産を奪い、神殿の美術品を盗み、無実の人を罪に問うて"},{"id":"rome-crisis-t3","k":"life","kj":"暮らし","t":"シチリアの奴隷反乱","l":"rome-crisis","x":"前135年ごろ、シチリア島で、大農場の奴隷たちが大規模な反乱を起こした（第1次シチリア奴隷反乱）。指導者は、シリア出身の奴隷エウヌスである。エウヌスは、口から火を吐いてみせる不思議"},{"id":"rome-crisis-t4","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"rome-crisis","x":"映画『スパルタカス』（1960年、スタンリー・キューブリック監督、カーク・ダグラス主演）：前73年に始まった剣闘士奴隷の反乱を描いた大作。反乱の経過や、クラッススとの対決などは史実"},{"id":"rome-early-t1","k":"myth","kj":"俗説","t":"ロムルスとレムス","l":"rome-early","x":"トロイア戦争で滅んだトロイアの王族アエネアスは、イタリアに逃れて、ラテン人の祖となった。その子孫の王女は、軍神マルスとの間に、双子の男の子ロムルスとレムスを産んだ。王位を奪った叔父"},{"id":"rome-early-t2","k":"trivia","kj":"こぼれ話","t":"ファスケスとファシズム","l":"rome-early","x":"ファスケスは、木の棒の束に斧を添えて縛ったもので、エトルリアの王、そしてローマの高位の役人の権力の象徴であった。役人が出かけるときには、ファスケスを肩に担いだ従者（リクトル）が先導"},{"id":"rome-early-t3","k":"source","kj":"史料","t":"胃袋と手足のたとえ","l":"rome-early","x":"前494年、戦争から帰ってきた平民たちは、貴族の横暴に抗議して、全員でローマを去り、町の外の「聖山」に立てこもった。兵士となる平民がいなければ、ローマは戦争をすることができない。困"},{"id":"rome-early-t4","k":"confuse","kj":"混同注意","t":"ローマの共和政とアテネの民主政","l":"rome-early","x":"アテネの民主政（前5世紀）ローマの共和政（前3世紀）最高議決機関民会（全市民が直接参加）実質的には元老院（終身の有力者）役人の選び方主に抽選選挙（立候補には富と家柄が有利）最高の役"},{"id":"rome-early-t5","k":"trivia","kj":"こぼれ話","t":"SPQR","l":"rome-early","x":"ローマの軍旗や公共の建物、硬貨には、「SPQR」という4文字がよく刻まれた。「セナトゥス・ポプルスクェ・ロマヌス」の略で、「ローマの元老院と民衆」という意味である。ローマという国家"},{"id":"rome-italy-t1","k":"myth","kj":"俗説","t":"「敗者に災いあれ」とガチョウの警報","l":"rome-italy","x":"ガリア人のローマ占領については、二つの有名な話が伝えられている。一つは、ガチョウの話である。ある夜、ガリア兵が、カピトリウムの丘の崖をよじ登って砦に忍び込もうとした。番犬さえ気づか"},{"id":"rome-italy-t2","k":"trivia","kj":"こぼれ話","t":"「ピュロスの勝利」","l":"rome-italy","x":"ピュロスは、アレクサンドロス大王の親戚にあたる名将で、マケドニア式のファランクスと、イタリアの人々が初めて見る戦象を率いて上陸した。前280年のヘラクレアの戦い、前279年のアスク"},{"id":"rome-italy-t3","k":"confuse","kj":"混同注意","t":"ローマの支配下のイタリアの人々","l":"rome-italy","x":"区分権利主な例ローマ市民（完全な市民権）民会での投票権・公職に就く権利、ローマ法の保護。兵役の義務ローマ市とその周辺、各地に建設したローマ市民の植民市（コロニア）投票権のない市民ロ"},{"id":"rome-italy-t4","k":"life","kj":"暮らし","t":"ローマの道のつくり","l":"rome-italy","x":"ローマの街道は、地面を深く掘り下げ、大きな石・小さな石・砂利・砂と火山灰を固めたもの、と層を重ね、最上部に平らな石を敷き詰めて造られた。路面は中央がわずかに高く、雨水が両脇の溝に流"},{"id":"sasanian-t1","k":"trivia","kj":"こぼれ話","t":"日本にあったマニ教の絵","l":"sasanian","x":"2000年代に入って、日本に伝わる中国製の絵画の中に、マニ教の絵画が含まれていることが、研究者によって次々に明らかにされた。山梨県の栖雲寺に「虚空蔵菩薩」の画像として伝わってきた元"},{"id":"sasanian-t2","k":"trivia","kj":"こぼれ話","t":"チェスはインドからペルシアへ","l":"sasanian","x":"チェスの起源は、6世紀ごろのインドの「チャトランガ」というゲームだと考えられている。ササン朝の時代の中世ペルシア語の物語によれば、インドの王がホスロー1世のもとにチェスを送り、その"},{"id":"sasanian-t3","k":"now","kj":"いま","t":"失われゆくカナート","l":"sasanian","x":"イランには、現在も数万本のカナートがあるといわれ、2016年には、11本の代表的なカナートが「ペルシアのカナート」として世界遺産に登録された。しかし、20世紀後半から、動力ポンプを"},{"id":"sasanian-t4","k":"works","kj":"作品紹介","t":"ササン朝にまつわる作品","l":"sasanian","x":"フィルドゥーシー『シャー＝ナーメ（王書）』（1010年完成）：神話の時代からササン朝の滅亡までのイランの王たちの歴史を、約5万の対句で歌った叙事詩。狩りの名手として知られる王バフラ"},{"id":"shang-t1","k":"trivia","kj":"こぼれ話","t":"「商人」という言葉の由来","l":"shang","x":"「商人」という言葉は、殷（商）が周に滅ぼされたあと、土地を失った商の遺民たちが各地を行き来して物を売り買いするようになったため、商売をする人を「商の人」と呼ぶようになったことに由来"},{"id":"shang-t2","k":"person","kj":"人物","t":"将軍となった王妃――婦好","l":"shang","x":"1976年、殷墟の宮殿区の近くで、盗掘を免れた墓が見つかった。そこからは、青銅器約460点、玉器約750点、子安貝約6800枚など、ぜいたくな副葬品が出土した。青銅器の多くに「婦好"},{"id":"shang-t3","k":"source","kj":"史料","t":"甲骨文を読む","l":"shang","x":"甲骨文には、殷の王たちの生活が生々しく記録されている。ある甲骨では、王の妃・婦好の出産について占っている。甲申の日にひびを入れて、貞人の㱿が問う。「婦好が子を産むが、よいことか（男"},{"id":"shang-t4","k":"trivia","kj":"こぼれ話","t":"重さ833kgの「鼎」","l":"shang","x":"殷墟から出土した青銅器のうち、最大のものが「后母戊鼎」（かつては「司母戊鼎」と読まれた）である。鼎は、三本または四本の足をもつ煮炊き用の器で、祭祀の中心となる器だった。この鼎は高さ"},{"id":"shang-t5","k":"now","kj":"いま","t":"三星堆――もう一つの青銅器文明","l":"shang","x":"1986年、四川省広漢市の三星堆遺跡で、大量の青銅器や玉器、象牙を埋めた二つの穴が見つかった。中には、目が筒のように大きく飛び出した幅1.38mの巨大な仮面、金箔の仮面をつけた人頭"},{"id":"shang-t6","k":"myth","kj":"俗説","t":"「暴君」紂王の姿","l":"shang","x":"夏の桀王と殷の紂王は、中国の歴史で「暴君」の代名詞とされる。しかし、二人の悪行の話はよく似ている。どちらも美しい女性におぼれ、酒の池を作り、忠臣を殺した、というのである。これは、新"},{"id":"shang-t7","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"shang","x":"『封神演義』：明代に書かれた小説で、殷の紂王と妲己の暴政、周の武王による殷の打倒（殷周革命）を、仙人や妖怪が入り乱れる壮大な神話の戦いとして描く。日本では藤崎竜による漫画（1996"},{"id":"silk-road-t1","k":"confuse","kj":"混同注意","t":"東西交易の3つの道","l":"silk-road","x":"道経路担い手主な特色草原の道（ステップ＝ルート）モンゴル高原から、カザフ草原・南ロシアの草原を通って黒海北岸へスキタイ・匈奴などの騎馬遊牧民最も古い。騎馬遊牧民の移動とともに、青銅"},{"id":"silk-road-t2","k":"trivia","kj":"こぼれ話","t":"タクラマカン砂漠の名前","l":"silk-road","x":"「タクラマカン」の名前は、ウイグル語で「入ったら出られない」という意味だ、とよく説明される。しかし、この語源には確かな根拠はなく、「廃墟の場所」「ポプラの森の場所」など、さまざまな"},{"id":"silk-road-t3","k":"confuse","kj":"混同注意","t":"西域の主なオアシス都市","l":"silk-road","x":"漢代の名現在の地名道特色楼蘭（のちに鄯善）ロプ＝ノール湖畔（遺跡）南道の入口4世紀ごろ水源の変化などで衰退し、砂に埋もれた于闐（うてん）ホータン南道玉（ぎょく）の産地。のちに仏教の"},{"id":"silk-road-t4","k":"source","kj":"史料","t":"張騫の報告","l":"silk-road","x":"大宛は、匈奴の西南、漢のまっすぐ西にあり、漢から1万里ほど離れています。その風俗は、定住して田を耕し、稲や麦をつくります。ぶどう酒があります。良い馬が多く、その馬は血の汗を流し、そ"},{"id":"silk-road-t5","k":"trivia","kj":"こぼれ話","t":"「胡」のつく食べ物","l":"silk-road","x":"張騫の旅ののち、西方から中国にさまざまな植物や産物が伝わった。『史記』は、漢の使者が、大宛からぶどうと、馬の飼料となるうまごやし（苜蓿、もくしゅく）の種を持ち帰り、離宮の周りに植え"},{"id":"silk-road-t6","k":"now","kj":"いま","t":"懸泉置――2000年前の駅の記録","l":"silk-road","x":"1990年から1992年にかけて、敦煌の東の懸泉置（けんせんち）という、漢代の駅（公用の宿泊・通信施設）の遺跡が発掘され、2万3000枚を超える木簡などが見つかった。そこには、公文"},{"id":"silk-road-t7","k":"source","kj":"史料","t":"虎穴に入らずんば虎子を得ず","l":"silk-road","x":"73年、班超は、わずか36人の部下を連れて、楼蘭の後身の鄯善国に使者として赴いた。鄯善の王は、はじめ班超を手厚くもてなしたが、やがて態度が冷たくなった。北匈奴の使者が来ていたのであ"},{"id":"silk-road-t8","k":"source","kj":"史料","t":"甘英はなぜ引き返したのか","l":"silk-road","x":"甘英は、安息（パルティア）を通って、条支（じょうし）の国の西の海辺に達した。そこで、海を渡ろうとすると、安息の西の境の船乗りが、甘英に言った。海はとても広く、行き来する者は、良い風"},{"id":"silk-road-t9","k":"source","kj":"史料","t":"ローマ人の絹の知識","l":"silk-road","x":"セレス人は、森から採れる羊毛のようなもので名高い。彼らは、木の葉に水をかけて、その白い綿毛をすき取る。……こうして、ローマの婦人たちは、布をほどいて、再び織り直すという二重の手間を"},{"id":"silk-road-t10","k":"confuse","kj":"混同注意","t":"シルクロードを行き交ったもの","l":"silk-road","x":"方向主な物産文化・宗教東から西へ絹・絹織物、漆器、鉄器、のちに紙の製法・陶磁器漢字文化（西域の役所の文書）、のちに製紙法西から東へ馬（汗血馬）、ぶどう・うまごやし、ガラス器、玉（于"},{"id":"silk-road-t11","k":"now","kj":"いま","t":"タリム盆地のミイラの正体","l":"silk-road","x":"「楼蘭の美女」をはじめとする、タリム盆地の青銅器時代のミイラは、西方的な顔立ちや毛織物の衣服から、はるか西方から移住してきた人々ではないかと考えられてきた。ところが、2021年に発"},{"id":"silk-road-t12","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"silk-road","x":"NHK特集『シルクロード』（1980〜1981年）：日中共同取材で、それまで外国人の立ち入りが難しかった中国西部の遺跡やオアシス都市を紹介したドキュメンタリー。喜多郎のテーマ音楽と"},{"id":"six-dynasties-culture-t1","k":"trivia","kj":"こぼれ話","t":"「五石散」――貴族たちの流行の薬","l":"six-dynasties-culture","x":"魏晋の貴族の間では、「五石散」（寒食散）と呼ばれる鉱物の薬を飲むことが流行した。魏の何晏が飲み始めたといわれ、気分を高揚させ、肌つやをよくする効果があると信じられた。しかし、この薬"},{"id":"six-dynasties-culture-t2","k":"source","kj":"史料","t":"陶淵明「飲酒」其の五","l":"six-dynasties-culture","x":"廬を結んで人境に在り 而も車馬の喧しき無し君に問う何ぞ能く爾ると 心遠ければ地自ずから偏なり菊を采る東籬の下 悠然として南山を見る山気日夕に佳し 飛鳥相い与に還る此の中に真意有り "},{"id":"six-dynasties-culture-t3","k":"trivia","kj":"こぼれ話","t":"『千字文』――1000の字が重ならない詩","l":"six-dynasties-culture","x":"梁の武帝は、皇子たちに書を学ばせるため、王羲之の書いた文字の中から、重ならない1000字を選ばせ、官僚の周興嗣に、それを使って詩を作るように命じた。周興嗣は、1字も重複させずに、4"},{"id":"six-dynasties-culture-t4","k":"person","kj":"人物","t":"鳩摩羅什――囚われの翻訳者","l":"six-dynasties-culture","x":"鳩摩羅什（クマーラジーヴァ、344〜413年ごろ）は、亀茲の王族の母と、インドの貴族の家系の父の間に生まれた。幼くして出家し、カシミールなどで学んで、西域に名の知れた高僧となった。"},{"id":"six-dynasties-culture-t5","k":"trivia","kj":"こぼれ話","t":"法顕――インドへの15年の旅","l":"six-dynasties-culture","x":"法顕は、中国に伝わっていた仏教の戒律が不完全であることを嘆き、正しい戒律の経典を求めて、399年、仲間とともに長安を出発した。すでに60歳を過ぎていた。一行は、敦煌から砂漠を越えた"},{"id":"six-dynasties-culture-t6","k":"view","kj":"視点を変える","t":"「皇帝は如来である」――北と南の仏教","l":"six-dynasties-culture","x":"華北（五胡十六国・北朝）：五胡の君主たちは、仏教を手厚く保護した。異民族の君主にとって、外来の宗教である仏教は、漢人の儒教の価値観に縛られない、新しい権威のよりどころとなった。北魏"},{"id":"six-dynasties-culture-t7","k":"myth","kj":"俗説","t":"達磨と虎渓三笑","l":"six-dynasties-culture","x":"この時代の仏教については、多くの伝説が生まれた。菩提達磨：禅宗の祖とされる菩提達磨は、南インドから海路で中国に来て、梁の武帝に会ったと伝えられる。多くの寺を建て、僧を養ってきた武帝"},{"id":"six-dynasties-culture-t8","k":"confuse","kj":"混同注意","t":"魏晋南北朝の文化の主な人物と作品","l":"six-dynasties-culture","x":"分野人物時代作品・事績思想竹林の七賢（阮籍・嵇康ら）魏・西晋老荘思想、清談詩陶淵明東晋・宋「帰去来辞」「桃花源記」、田園詩詩謝霊運宋山水詩文学昭明太子梁『文選』文学劉義慶宋『世説新"},{"id":"six-dynasties-culture-t9","k":"works","kj":"作品紹介","t":"この時代にまつわる作品と言葉","l":"six-dynasties-culture","x":"「白眼視」：阮籍の「青眼・白眼」の逸話から、人を冷たい目で見ることをいう。「桃源郷」：陶淵明の「桃花源記」から、俗世間を離れた理想郷をいう。元号「令和」：『万葉集』の梅花の歌の序文"},{"id":"slavs-t1","k":"trivia","kj":"こぼれ話","t":"「スラヴ」と「スレイブ」","l":"slavs","x":"英語で「奴隷」を意味する「スレイブ」（slave）は、「スラヴ人」（Slav）に由来する。9〜10世紀、ヴァイキングやドイツの商人、ユダヤ人の商人たちは、東ヨーロッパで捕らえたスラ"},{"id":"slavs-t2","k":"source","kj":"史料","t":"教皇への106の質問","l":"slavs","x":"866年、ボリス1世は、ローマ教皇ニコラウス1世に、キリスト教徒としての暮らし方について、106の質問を送った。教皇の答えの書簡が残っており、そこからは、新しくキリスト教を受け入れ"},{"id":"slavs-t3","k":"now","kj":"いま","t":"ヴァーツラフ広場","l":"slavs","x":"プラハの中心にある「ヴァーツラフ広場」には、馬に乗った聖ヴァーツラフの像が立っている。この広場は、チェコの近現代史の重要な舞台となってきた。1918年10月、チェコスロヴァキアの独"},{"id":"slavs-t4","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"slavs","x":"『原初年代記』：キエフ公国の成り立ちと、ウラディミル1世の改宗の物語を伝える年代記。日本語訳に、國本哲男ほか訳『ロシア原初年代記』（名古屋大学出版会）がある。アルフォンス・ミュシャ"},{"id":"south-india-trade-t1","k":"source","kj":"史料","t":"『エリュトゥラー海案内記』が記すムジリス","l":"south-india-trade","x":"ムジリスは、同じ王国（ケーロボトラス＝チェーラの王の国）に属し、アラビアから運ばれた積荷を載せた船や、ギリシア人の船でにぎわっている。……これらの市場の町には、大量でかさばるコショ"},{"id":"south-india-trade-t2","k":"source","kj":"史料","t":"サンガム文学に歌われたムジリス","l":"south-india-trade","x":"ヤヴァナの人々の、見事なつくりの大きな船が、金を積んでやって来て、ペリヤール川の白い泡を立て、コショウを積んで帰って行く。富のあふれる町ムチリ（ムジリス）。出典：『アカナーヌール』"},{"id":"south-india-trade-t3","k":"source","kj":"史料","t":"プリニウスの嘆き","l":"south-india-trade","x":"少なく見積もっても、インドとセレス（中国）とアラビア半島は、毎年1億セステルティウスを、われわれの帝国から奪っている。これが、われわれのぜいたくと女たちのために支払われている代価な"},{"id":"south-india-trade-t4","k":"now","kj":"いま","t":"アリカメードゥとパッタナム――交易の港を掘る","l":"south-india-trade","x":"1940年代、イギリスの考古学者ウィーラーは、インド南東岸のポンディシェリ（プドゥチェリ）近くのアリカメードゥを発掘し、ローマの赤い陶器（アッレティウム陶器）や、ワインを運んだ壺（"},{"id":"south-india-trade-t5","k":"confuse","kj":"混同注意","t":"紀元前後〜3世紀のインドの主な国々","l":"south-india-trade","x":"クシャーナ朝サータヴァーハナ朝タミル人の三王国地域中央アジア〜西北インド・ガンジス川上流デカン高原南インドの南端部担い手中央アジアから来た遊牧民（大月氏の一派）ドラヴィダ系ドラヴィ"},{"id":"southeast-asia-indianized-t1","k":"trivia","kj":"こぼれ話","t":"海を渡った人々――台湾からマダガスカルまで","l":"southeast-asia-indianized","x":"オーストロネシア語族の人々の祖先は、約5000年前、台湾から南へ船で渡り始めたと考えられている。彼らは、フィリピン、インドネシアへと島々を渡り、さらに東は太平洋のハワイやイースター"},{"id":"southeast-asia-indianized-t2","k":"debate","kj":"諸説あり","t":"「インド化」は誰が進めたのか","l":"southeast-asia-indianized","x":"20世紀前半、フランスの東洋学者ジョルジュ・セデスは、東南アジアの古代の国々を「インド化された国家」と呼んだ。この見方では、インドから来た商人やバラモンが、東南アジアに文明をもたら"},{"id":"southeast-asia-indianized-t3","k":"myth","kj":"俗説","t":"扶南の建国神話","l":"southeast-asia-indianized","x":"中国の史書『梁書』は、扶南の建国について、次のような話を伝えている伝承。扶南の国は、もとは柳葉りゅうようという名の女王が治めていた。ある時、南方の国の混塡こんてんという男が、夢の中"},{"id":"southeast-asia-indianized-t4","k":"source","kj":"史料","t":"裸の人々に服を――呉の使者と扶南の王","l":"southeast-asia-indianized","x":"『梁書』扶南伝は、康泰と朱応が扶南を訪れた時の様子を、次のように伝えている。呉の時代に、中郎の康泰こうたいと、宣化従事の朱応しゅおうを、范尋の国に使者として送った。この国の人々は、"},{"id":"southeast-asia-indianized-t5","k":"trivia","kj":"こぼれ話","t":"最古のオーストロネシア語の文章","l":"southeast-asia-indianized","x":"ベトナム中部のチャキエウ（チャンパーの古い都の跡）の近くで見つかった碑文は、4世紀ごろに、インド系の文字で、チャム語で刻まれている。これは、オーストロネシア語族の言葉で書かれた、現"},{"id":"southeast-asia-indianized-t6","k":"trivia","kj":"こぼれ話","t":"ゼロの記号を探した数学者","l":"southeast-asia-indianized","x":"カンボジアのメコン川のほとりのサンボー（サンボー・プレイ・クックとは別の地）で、1891年、フランスの調査団によって、一つの石碑が発見された。碑文は古クメール語で書かれ、末尾に、寄"},{"id":"southeast-asia-indianized-t7","k":"source","kj":"史料","t":"長安で演じられたピューの音楽","l":"southeast-asia-indianized","x":"802年、ピュー（驃国ひょうこく）の王は、王子に、楽人35人と12曲の音楽を携えさせて、唐の長安に送った。この「驃国楽」は、長安の人々に珍しがられた。唐の詩人白居易は、その音楽を題"},{"id":"southeast-asia-indianized-t8","k":"source","kj":"史料","t":"シュリーヴィジャヤの碑文","l":"southeast-asia-indianized","x":"パレンバンの近くのクドゥカン・ブキットで1920年に見つかった石碑には、682〜683年（シャカ暦605年）に、「ダプンタ・ヒャン」という王が、2万の兵を率いて、船で遠征に出発し、"},{"id":"southeast-asia-indianized-t9","k":"source","kj":"史料","t":"義浄が見たシュリーヴィジャヤ","l":"southeast-asia-indianized","x":"義浄は、シュリーヴィジャヤについて、次のように記している。仏逝の城の中には、僧が1000人余りいる。学問に励み、托鉢を行うことは、インド（中天竺）と変わらない。……もし唐の僧で、イ"},{"id":"southeast-asia-indianized-t10","k":"trivia","kj":"こぼれ話","t":"道に落ちた金の袋――訶陵の女王","l":"southeast-asia-indianized","x":"シュリーヴィジャヤが台頭した頃、ジャワ島中部には、中国の史書が「訶陵かりょう」と記す国があった。『新唐書』は、7世紀後半にこの国を治めた女王「悉莫しつばく」（シーマ）について、次の"},{"id":"southeast-asia-indianized-t11","k":"trivia","kj":"こぼれ話","t":"浮き彫りの船と、アフリカへの航海","l":"southeast-asia-indianized","x":"ボロブドゥールの浮き彫りの中には、複数の帆を張り、船体の両側に浮き（アウトリガー）をつけた大きな船が描かれたものがある。8〜9世紀の東南アジアの外洋船の姿を伝える貴重な資料である。"},{"id":"southeast-asia-indianized-t12","k":"trivia","kj":"こぼれ話","t":"火山灰に埋もれた遺跡","l":"southeast-asia-indianized","x":"10世紀前半、ジャワ島の政治の中心は、中部から東部へと移った。その理由として、ジャワ島中部のムラピ山の大噴火などの自然災害があったとする説がある諸説。ボロブドゥールは、しだいに忘れ"},{"id":"southeast-asia-indianized-t13","k":"now","kj":"いま","t":"現代の東南アジアと古代の遺産","l":"southeast-asia-indianized","x":"現代の東南アジアの国々にとって、古代の国家や遺跡は、国の誇りの象徴となっている。カンボジアの国旗には、アンコール＝ワットが描かれている。インドネシアは、シュリーヴィジャヤやマジャパ"},{"id":"southeast-asia-indianized-t14","k":"works","kj":"作品紹介","t":"この時代を描いた作品・関連する文化","l":"southeast-asia-indianized","x":"ワヤン・クリ（影絵芝居）：インドネシアのジャワ島やバリ島の伝統的な影絵芝居。『ラーマーヤナ』や『マハーバーラタ』の物語を演じる。2003年、ユネスコの「人類の口承及び無形遺産の傑作"},{"id":"spring-autumn-t1","k":"confuse","kj":"混同注意","t":"春秋の五覇","l":"spring-autumn","x":"春秋時代の代表的な5人の覇者を「春秋の五覇」という。ただし、だれを数えるかについては、古くから複数の説がある諸説。覇者国主な事績桓公斉管仲を登用。葵丘の会盟（前651年）で最初の覇"},{"id":"spring-autumn-t2","k":"source","kj":"史料","t":"鼎の軽重を問う","l":"spring-autumn","x":"前606年、楚の荘王は、兵を率いて周の都洛邑の郊外まで進み、周の王の使者・王孫満に、周の王室に伝わる九つの鼎（かなえ）の大きさと重さを尋ねた。鼎は、王権の象徴であった。王孫満は答え"},{"id":"spring-autumn-t3","k":"myth","kj":"俗説","t":"臥薪嘗胆","l":"spring-autumn","x":"呉王闔閭（こうりょ）は、越との戦いで受けた傷がもとで亡くなった。その子の夫差は、父の仇を忘れないよう、薪の上に寝て（臥薪）自分を奮い立たせ、ついに越王勾践を破った。敗れた勾践は、許"},{"id":"spring-autumn-t4","k":"source","kj":"史料","t":"斉の都・臨淄のにぎわい","l":"spring-autumn","x":"臨淄の町の中には、7万戸がある。……臨淄はたいへん豊かで充実しており、その住民で、竽（う、笛の一種）を吹き、瑟（しつ、琴の一種）を鳴らし、筑を打ち、琴を弾き、闘鶏や犬の競走、すごろ"},{"id":"spring-autumn-t5","k":"confuse","kj":"混同注意","t":"戦国時代の青銅貨幣","l":"spring-autumn","x":"貨幣形主に使われた地域刀銭（刀貨）小刀の形斉・燕（東方・北方）布銭（布貨）農具の鋤（すき）の形韓・魏・趙（中原）蟻鼻銭（ぎびせん）子安貝の形をまねた小さな貨幣。表の文字が蟻の顔や鼻"},{"id":"spring-autumn-t6","k":"trivia","kj":"こぼれ話","t":"端午の節句とちまき","l":"spring-autumn","x":"端午の節句（もとは旧暦5月5日）に、ちまきを食べる習慣は、屈原に由来するとする話がある。屈原が汨羅（べきら）の川に身を投げた日が旧暦の5月5日であり、人々が、屈原の遺体が魚に食べら"},{"id":"spring-autumn-t7","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"spring-autumn","x":"宮城谷昌光の歴史小説：『夏姫春秋』（直木賞、1991年）、『重耳』（晋の文公の物語）、『管仲』など、春秋・戦国時代の人物を主人公とする作品を数多く書いている。『春秋左氏伝』『史記』"},{"id":"steppe-early-t1","k":"trivia","kj":"こぼれ話","t":"「インド＝ヨーロッパ」の言葉と馬","l":"steppe-early","x":"戦車の広がりは、インド＝ヨーロッパ語族の言葉の広がりと重なっていると考えられている。ヒッタイトの文書に残るミタンニ出身のキックリの馬の調教の手引きに、古代インドの言葉とそっくりの数"},{"id":"steppe-early-t2","k":"confuse","kj":"混同注意","t":"遊牧民の「民族」を整理する","l":"steppe-early","x":"草原に現れた騎馬遊牧民は、時代によって、話す言葉も系統も異なる。時代主な遊牧民言語の系統（推定）活動した地域前8〜前3世紀スキタイ、サカ、サルマタイイラン系（インド＝ヨーロッパ語族"},{"id":"steppe-early-t3","k":"source","kj":"史料","t":"鳥、ネズミ、カエル、5本の矢","l":"steppe-early","x":"前513年ごろ、アケメネス朝のダレイオス1世は、大軍を率いてボスポラス海峡を渡り、ドナウ川を越えてスキタイの地に攻め込んだ。しかしスキタイは決戦を避け、井戸を埋め、草を焼き払いなが"},{"id":"steppe-early-t4","k":"life","kj":"暮らし","t":"麻の蒸し風呂","l":"steppe-early","x":"ヘロドトスは、スキタイの人々の奇妙な習慣を伝えている。死者を葬ったあと、彼らは3本の棒を立ててフェルトで覆った小さなテントを作り、その中で真っ赤に焼いた石の上に麻（大麻）の種を投げ"},{"id":"steppe-early-t5","k":"myth","kj":"俗説","t":"アマゾネスは実在したか","l":"steppe-early","x":"ギリシア神話には、「アマゾネス」と呼ばれる女性だけの戦士の部族が登場する。ヘロドトスは、スキタイの若者たちがアマゾネスと結婚して生まれたのが、東の遊牧民サウロマタイ（サルマタイ）だ"},{"id":"steppe-early-t6","k":"now","kj":"いま","t":"戦争に翻弄されるスキタイの黄金","l":"steppe-early","x":"2014年、クリミア半島の4つの博物館が所蔵するスキタイの黄金などの文化財が、オランダのアムステルダムの博物館で展示されていた。展示中に、ロシアがクリミア半島を一方的に併合した。文"},{"id":"steppe-early-t7","k":"trivia","kj":"こぼれ話","t":"氷に閉じ込められた入れ墨","l":"steppe-early","x":"アルタイ山脈の高地のパジリク古墳群（前5〜前3世紀）では、墓の中に入り込んだ水が凍り、そのまま永久凍土のように氷に閉ざされていた。そのため、ふつうなら腐ってしまう木材やフェルト、毛"},{"id":"steppe-early-t8","k":"debate","kj":"諸説あり","t":"「騎馬民族征服王朝説」","l":"steppe-early","x":"1948年、日本の考古学者・江上波夫は、東北アジアの騎馬民族が朝鮮半島を経て日本列島に渡り、4〜5世紀ごろに大和の王権を打ち立てた、という「騎馬民族征服王朝説」を発表した。古墳時代"},{"id":"sui-t1","k":"debate","kj":"諸説あり","t":"科挙はいつ始まったのか","l":"sui","x":"科挙の始まりを何年とするかについては、研究者の間で意見が分かれている諸説。587年説：文帝が、各州から毎年3人を推薦させて試験を行った年。598年説：文帝が、「志行修謹」「清平幹済"},{"id":"sui-t2","k":"trivia","kj":"こぼれ話","t":"一箭双鵰","l":"sui","x":"長孫晟は、弓の名手であった。北周の使者として突厥に滞在していたとき、突厥の摂図（のちの沙鉢略可汗）とともに狩りに出かけた。空で2羽の鷲が肉を奪い合っているのを見た摂図が、長孫晟に2"},{"id":"sui-t3","k":"now","kj":"いま","t":"今も働く大運河","l":"sui","x":"大運河は、隋の滅亡後も、唐・宋・元・明・清の各王朝にとって、江南の米を都に運ぶ生命線であった。元の時代には、都の大都（北京）まで直接結ぶ経路に改められ、現在の京杭大運河（北京〜杭州"},{"id":"sui-t4","k":"trivia","kj":"こぼれ話","t":"木に巻かれた絹","l":"sui","x":"610年の正月、煬帝は、洛陽に集まった西域の商人や使節たちに、隋の豊かさを見せつけようとした。洛陽の大通りでは、1か月にわたって、各地から集めた芸人たちが歌舞や曲芸を披露し、その演"},{"id":"sui-t5","k":"source","kj":"史料","t":"「日出づる処の天子」","l":"sui","x":"607年、倭国の使者小野妹子は、煬帝に国書を差し出した。『隋書』倭国伝は、その様子を次のように記している。大業3年（607年）、その王の多利思比孤が、使者を遣わして朝貢してきた。使"},{"id":"sui-t6","k":"person","kj":"人物","t":"乙支文徳――朝鮮の救国の英雄","l":"sui","x":"乙支文徳は、高句麗の将軍で、その生い立ちはほとんどわかっていない。『三国史記』は、「沈着で知略に富み、文章も書けた」と記している。乙支文徳が隋の将軍于仲文に送った五言の詩は、朝鮮半"},{"id":"sui-t7","k":"source","kj":"史料","t":"「遼東に向かって無駄死にするな」","l":"sui","x":"王薄が作ったとされる「無向遼東浪死歌」は、次のように歌う。長白山のふもとの知世郎（王薄の自称）は、赤い薄絹と錦の胴着を着込んでいる。長い矛は天の半ばまで届き、振るう刀は日の光に輝く"},{"id":"sui-t8","k":"debate","kj":"諸説あり","t":"煬帝は暴君だったのか","l":"sui","x":"「煬」という諡（おくりな、死後の称号）は、唐の朝廷が贈ったもので、「天に逆らい民を虐げる」といった悪い意味を持つ。唐は、隋を倒したことを正当化するため、煬帝を暴君として描いた。中国"},{"id":"sui-t9","k":"works","kj":"作品紹介","t":"隋にまつわる作品","l":"sui","x":"『隋唐演義』（清代の褚人穫の小説）：隋の末期から唐の玄宗の時代までを描いた歴史小説。隋末の群雄や、唐の建国の英雄たちの活躍が語られる。『隋煬帝艶史』（明代の小説）：煬帝の遊興を描い"},{"id":"sumer-t1","k":"confuse","kj":"混同注意","t":"「肥沃な三日月地帯」と「メソポタミア」","l":"sumer","x":"前の部で見た「肥沃な三日月地帯」は、雨水だけで麦が育つ丘陵地帯を中心とする広い地域で、最初に農耕が始まった場所である。一方、メソポタミア南部は、雨が少なく、灌漑なしでは農業ができな"},{"id":"sumer-t2","k":"trivia","kj":"こぼれ話","t":"世界最古の「給料」はビールとパン","l":"sumer","x":"ウルクの遺跡からは、「面取り縁鉢（ベヴェルド・リム・ボウル）」と呼ばれる、粗末な作りの土器の鉢が大量に見つかっている。どれもほぼ同じ大きさで、型で量産されたものらしい。これは、神殿"},{"id":"sumer-t3","k":"trivia","kj":"こぼれ話","t":"最古の文字の記録はビールの帳簿だった","l":"sumer","x":"「文字の発明」というと、詩や神話、王の功績を記すために生まれたと考えたくなるが、現実はもっと地味である。ウルクで見つかった初期の粘土板の約85パーセントは、麦やビール、家畜、労働者"},{"id":"sumer-t4","k":"life","kj":"暮らし","t":"書記学校の生徒はつらかった","l":"sumer","x":"楔形文字は何百もの記号からなり、覚えるのは大変だった。そこで、書記を養成する学校が作られた。シュメール語で「エドゥバ（粘土板の家）」という。生徒は、朝から晩まで粘土板に文字を書き写"},{"id":"sumer-t5","k":"source","kj":"史料","t":"洪水の前に王たちは何万年も統治した――シュメール王名表","l":"sumer","x":"シュメール人は、自分たちの王の一覧表を残している。「シュメール王名表」と呼ばれる文書で、王権が天から降りてきてから、各都市の王が順に統治したことを記している。そこには、「大洪水」の"},{"id":"sumer-t6","k":"trivia","kj":"こぼれ話","t":"「自由」という言葉が最初に記された碑文","l":"sumer","x":"前2350年ごろ、ラガシュの王ウルカギナ（ウルイニムギナ）は、役人や神官の横暴を戒める改革を行った。重い税や手数料を引き下げ、借金のために奴隷にされた人々を解放し、孤児や寡婦が有力"},{"id":"sumer-t7","k":"life","kj":"暮らし","t":"王とともに葬られた人々","l":"sumer","x":"ウルの王墓には、衝撃的な発見もあった。ある墓の竪穴（「大死坑」と呼ばれる）には、着飾った女性たちを中心に、74人もの人々が整然と並んで横たわっていた。兵士は武器を持ち、楽師は竪琴の"},{"id":"sumer-t8","k":"source","kj":"史料","t":"『ギルガメシュ叙事詩』の洪水物語","l":"sumer","x":"旅の果てに、ギルガメシュは、かつて大洪水を生き延びて不死を与えられた男ウトナピシュティムに出会う。ウトナピシュティムは、昔、神々が人間を滅ぼすために大洪水を起こそうとしたとき、知恵"},{"id":"sumer-t9","k":"source","kj":"史料","t":"酒場の女主人の忠告","l":"sumer","x":"不死を求めて旅を続けるギルガメシュに、ある酒場の女主人シドゥリはこう語りかけたという（古バビロニア版）。「ギルガメシュよ、あなたはどこへさまよい行くのか。あなたが求める命を、あなた"},{"id":"sumer-t10","k":"debate","kj":"諸説あり","t":"塩が文明を衰えさせた？","l":"sumer","x":"メソポタミア南部の灌漑農業には、大きな弱点があった。乾燥した土地で畑に水を引き続けると、水が蒸発するときに地中の塩分が地表に残り、少しずつ土地に塩がたまっていく（塩害）。シュメール"},{"id":"tang-culture-t1","k":"source","kj":"史料","t":"大秦景教流行中国碑","l":"tang-culture","x":"781年、長安の大秦寺に、景教の伝来と布教の歴史を記した石碑が建てられた。碑文は、ペルシア出身の僧景浄（アダム）が作ったもので、漢文に加えて、シリア文字で僧たちの名が刻まれている。"},{"id":"tang-culture-t2","k":"person","kj":"人物","t":"義浄――海の道を往復した僧","l":"tang-culture","x":"義浄（635〜713年）は、玄奘にあこがれてインドへの旅を志した。671年、広州からペルシア商人の船に乗った義浄は、約20日で東南アジアのスマトラ島のシュリーヴィジャヤに着いた。そ"},{"id":"tang-culture-t3","k":"source","kj":"史料","t":"李白「静夜思」と王維「送元二使安西」","l":"tang-culture","x":"李白「静夜思」牀前、月光を看る 疑うらくは是れ地上の霜かと頭を挙げて山月を望み 頭を低れて故郷を思う（寝台の前に差し込む月の光を見て、地面に降りた霜かと思った。頭を上げて山の上の月"},{"id":"tang-culture-t4","k":"now","kj":"いま","t":"白居易と日本","l":"tang-culture","x":"唐の詩人の中で、平安時代の日本で最も愛されたのは、白居易（白楽天）であった。その詩文集『白氏文集』は、白居易の存命中にすでに日本に伝わり、貴族たちの必読書となった。清少納言の『枕草"},{"id":"tang-culture-t5","k":"trivia","kj":"こぼれ話","t":"世界最古の印刷物はどこにある？","l":"tang-culture","x":"年代が確実な印刷物として古いものに、日本の百万塔陀羅尼がある。764年の恵美押勝の乱の後、称徳天皇の命で、小さな木製の三重塔100万基が作られ、その中に仏教の呪文（陀羅尼）を刷った"},{"id":"tang-culture-t6","k":"works","kj":"作品紹介","t":"唐の文化にまつわる作品","l":"tang-culture","x":"『唐詩選』：明代に編まれたとされる唐詩の選集。江戸時代の日本で大流行し、漢詩を学ぶ人々の入門書となった。『三体詩』『唐詩三百首』：同じく、唐詩の代表的な選集。井上靖『敦煌』（195"},{"id":"tang-early-t1","k":"debate","kj":"諸説あり","t":"唐の建国の主役はだれか","l":"tang-early","x":"唐の正史（『旧唐書』『新唐書』）や『資治通鑑』では、太原での挙兵をためらう父の李淵を、次男の李世民が説得し、挙兵を主導したように描かれている。しかし、挙兵に従った李淵の側近温大雅が"},{"id":"tang-early-t2","k":"person","kj":"人物","t":"平陽公主――娘子軍の将軍","l":"tang-early","x":"李淵の娘の平陽公主は、父が太原で挙兵したとき、夫の柴紹とともに長安にいた。夫が父のもとに駆けつけた後、公主は、長安の郊外の自分の領地に戻って、財産を投げ出して人々を集め、各地の反乱"},{"id":"tang-early-t3","k":"trivia","kj":"こぼれ話","t":"太宗が読みたがった記録","l":"tang-early","x":"中国の宮廷には、皇帝の日々の言動を記録する「起居注」という制度があった。皇帝は、自分についての記録を読んではならないとされていた。記録が皇帝の意向で書き換えられることを防ぐためであ"},{"id":"tang-early-t4","k":"source","kj":"史料","t":"「三つの鏡」――魏徴の死","l":"tang-early","x":"643年、魏徴が死ぬと、太宗は朝廷を5日間休み、自ら葬儀に参列して、臣下たちにこう語った。銅を鏡とすれば、衣服や冠を正すことができる。古（いにしえ）を鏡とすれば、国の興亡を知ること"},{"id":"tang-early-t5","k":"trivia","kj":"こぼれ話","t":"懐に隠したハイタカ","l":"tang-early","x":"太宗は、狩りに使う鳥を好んだ。あるとき、太宗が、手に入れたばかりの立派なハイタカを腕に止まらせて遊んでいると、遠くから魏徴がやってくるのが見えた。遊んでいるところを見られて諫められ"},{"id":"tang-early-t6","k":"debate","kj":"諸説あり","t":"390人の死刑囚は戻ってきたか","l":"tang-early","x":"632年の年末、太宗は、死刑の判決を受けた390人の囚人を、いったん家に帰らせ、翌年の秋に戻ってきて刑を受けるよう命じた。翌年の秋、約束の日に、390人の死刑囚は、監視の役人もいな"},{"id":"tang-early-t7","k":"now","kj":"いま","t":"『貞観政要』と日本","l":"tang-early","x":"太宗と臣下たちの問答を記録した『貞観政要』は、8世紀前半、唐の歴史家呉兢によってまとめられた。君主のあるべき姿を説く「帝王学」の教科書として、中国だけでなく、日本や朝鮮でも広く読ま"},{"id":"tang-early-t8","k":"works","kj":"作品紹介","t":"唐の建国にまつわる作品","l":"tang-early","x":"『隋唐演義』（清代の小説）：隋末から唐初の英雄たちの活躍を描く。秦叔宝・程咬金・尉遅敬徳らが、豪傑として大活躍する。門神の秦叔宝と尉遅敬徳：太宗が悪夢にうなされたとき、2人が寝室の"},{"id":"tang-system-t1","k":"confuse","kj":"混同注意","t":"唐の律令と日本の律令","l":"tang-system","x":"日本は、唐の律令を手本として、701年に大宝律令を制定した。しかし、日本の律令は、唐の制度をそのまま写したものではなかった。唐日本（大宝律令・養老律令）中央官制三省六部（中書・門下"},{"id":"tang-system-t2","k":"trivia","kj":"こぼれ話","t":"「春風に意を得て、馬蹄疾し」――進士の喜び","l":"tang-system","x":"進士科に合格した者たちは、長安の東南の曲江池のほとりで、盛大な祝宴を開いた。また、慈恩寺の大雁塔の壁に、合格者の名前を書きつけるのが習わしであった（雁塔題名）。のちに唐を代表する詩"},{"id":"tang-system-t3","k":"trivia","kj":"こぼれ話","t":"「請う、君、甕に入れ」","l":"tang-system","x":"酷吏の周興が謀反の疑いをかけられたとき、その取り調べを命じられたのは、同じ酷吏の来俊臣であった。来俊臣は、何も知らないふりをして周興を食事に招き、こう尋ねた。「罪を認めない囚人がい"},{"id":"tang-system-t4","k":"debate","kj":"諸説あり","t":"武則天をどう評価するか","l":"tang-system","x":"武則天は、儒教の価値観が支配的な中国の伝統的な歴史家から、皇帝の位を奪い、多くの人々を殺した悪女として厳しく非難されてきた。しかし、20世紀以降は、別の見方も示されるようになった。"},{"id":"tang-system-t5","k":"works","kj":"作品紹介","t":"この時代にまつわる作品","l":"tang-system","x":"中国のテレビドラマ『則天武后』（『武則天』）：武則天を主人公とするドラマは、何度も作られてきた。2014年の『武則天 The Empress』（范冰冰主演）は、日本でも放送された。"},{"id":"tang-world-t1","k":"view","kj":"視点を変える","t":"「東アジア文化圏」という見方","l":"tang-world","x":"日本の歴史家西嶋定生は、中国を中心に、朝鮮・日本・ベトナムなどを含む地域が、漢字・儒教・中国化した仏教・律令という共通の文化を持つ一つの「世界」を形づくっていたと考え、これを「東ア"},{"id":"tang-world-t2","k":"trivia","kj":"こぼれ話","t":"李白はキルギスで生まれた？","l":"tang-world","x":"唐を代表する詩人李白の出生地については、古くから議論がある。李白の死後まもなく書かれた伝記などによれば、李白の祖先は、隋末に罪を得て西域に移り住み、李白は705年ごろ、5歳のときに"},{"id":"tang-world-t3","k":"person","kj":"人物","t":"ペーローズ――長安に亡命したペルシアの王子","l":"tang-world","x":"651年、アラブのイスラーム勢力に追われたササン朝の最後の王ヤズデギルド3世が、中央アジアのメルヴで殺された（→「ササン朝ペルシア」の回）。その子ペーローズ（漢字では卑路斯）は、ト"},{"id":"tang-world-t4","k":"debate","kj":"諸説あり","t":"製紙法はタラスで伝わったのか","l":"tang-world","x":"タラス河畔の戦いで捕虜となった唐の兵士の中に、紙すきの職人がいて、彼らによってサマルカンドで紙が作られるようになり、製紙法がイスラーム世界、さらにヨーロッパへと伝わった――この話は"},{"id":"tang-world-t5","k":"person","kj":"人物","t":"阿倍仲麻呂――唐の高官となった日本人","l":"tang-world","x":"阿倍仲麻呂（698〜770年）は、717年、19歳で、吉備真備・玄昉らとともに留学生として唐に渡った。唐の太学で学んだ仲麻呂は、科挙に合格したとも伝えられ諸説、「朝衡」（晁衡）とい"},{"id":"tang-world-t6","k":"trivia","kj":"こぼれ話","t":"鑑真――6度目の渡海","l":"tang-world","x":"鑑真（688〜763年）は、揚州の大明寺の高僧であった。742年、日本から来た留学僧の栄叡と普照が、日本に正式な戒律を伝える僧を招きたいと願い出ると、鑑真は、弟子たちの誰も応じない"},{"id":"tang-world-t7","k":"works","kj":"作品紹介","t":"唐と東アジアにまつわる作品","l":"tang-world","x":"井上靖『天平の甍』（1957年）：鑑真を日本に招くため唐に渡った留学僧の栄叡・普照らの苦闘を描いた小説。1980年に映画化された。『小倉百人一首』の阿倍仲麻呂の歌：「天の原ふりさけ"},{"id":"three-kingdoms-t1","k":"confuse","kj":"混同注意","t":"正史『三国志』と『三国志演義』","l":"three-kingdoms","x":"私たちが「三国志」として親しんでいる物語には、二つの系統がある。正史『三国志』『三国志演義』成立3世紀末、西晋の陳寿が著した歴史書。5世紀に裴松之が多くの史料を引いて注を付けた14"},{"id":"three-kingdoms-t2","k":"source","kj":"史料","t":"出師の表","l":"three-kingdoms","x":"臣はもと無位無官の身で、南陽で自ら畑を耕し、乱世にあってただ命を保つことを願い、諸侯に名を知られることを求めませんでした。先帝（劉備）は、臣を卑しい身分とお思いにならず、自ら身を屈"},{"id":"three-kingdoms-t3","k":"myth","kj":"俗説","t":"「死せる孔明、生ける仲達を走らす」","l":"three-kingdoms","x":"234年、5度目の北伐で五丈原（現在の陝西省）に陣を敷いた諸葛亮は、陣中で病死した。蜀の軍が撤退を始めると、魏の司馬懿（字は仲達）は追撃しようとした。ところが、蜀の軍が旗を返し、太"},{"id":"three-kingdoms-t4","k":"trivia","kj":"こぼれ話","t":"七歩の詩","l":"three-kingdoms","x":"曹丕は、才能豊かな弟の曹植を警戒していた。南朝の逸話集『世説新語』によれば、曹丕は曹植に、「7歩歩く間に詩を作れ。できなければ処刑する」と命じた。曹植は、歩きながら次のような詩を作"},{"id":"three-kingdoms-t5","k":"trivia","kj":"こぼれ話","t":"曹操の墓の発見","l":"three-kingdoms","x":"2009年、河南省安陽市の西高穴村で、後漢末の大きな墓（西高穴2号墓）の発掘が発表され、曹操の墓（高陵）であると発表された。墓からは、「魏武王」（曹操の称号）と刻まれた石の札や、6"},{"id":"three-kingdoms-t6","k":"now","kj":"いま","t":"関羽は「商売の神様」","l":"three-kingdoms","x":"劉備の武将関羽は、死後しだいに神格化され、宋代以降は「関帝」として、国家によって祀られるようになった。関羽は、正義と信義を重んじた人物とされたことから、約束を守ることが大切な商人た"},{"id":"three-kingdoms-t7","k":"works","kj":"作品紹介","t":"三国志にまつわる作品","l":"three-kingdoms","x":"羅貫中『三国志演義』（14世紀ごろ）：中国の四大奇書の一つ。蜀を正統とし、劉備・関羽・張飛・諸葛亮を英雄として描いた歴史小説。日本でも江戸時代に翻訳され、広く読まれた。吉川英治『三"},{"id":"tibet-nanzhao-t1","k":"person","kj":"人物","t":"文成公主","l":"tibet-nanzhao","x":"文成公主（？〜680年）は、唐の皇族の娘で、640年に吐蕃の宰相ガル・トンツェン（禄東賛）が長安に来て求婚した後、641年、太宗の命でソンツェン＝ガンポに嫁いだ（→「唐の成立と貞観"},{"id":"tibet-nanzhao-t2","k":"debate","kj":"諸説あり","t":"サムイェーの宗論――インド仏教か、中国仏教か","l":"tibet-nanzhao","x":"8世紀の吐蕃には、インドからの仏教と、唐からの仏教（禅宗）の両方が伝わっていた。792年ごろから、サムイェー寺で、両者の代表者による論争が行われたと伝えられる。中国側：禅僧の摩訶衍"},{"id":"tibet-nanzhao-t3","k":"trivia","kj":"こぼれ話","t":"名前のしりとり――父子連名制","l":"tibet-nanzhao","x":"南詔の王の名前には、不思議な規則がある。初代から順に並べると、次のようになる。細奴邏 → 邏盛 → 盛邏皮 → 皮邏閣 → 閣羅鳳 → 鳳伽異 → 異牟尋 → 尋閣勧 → 勧龍晟・"},{"id":"tibet-nanzhao-t4","k":"source","kj":"史料","t":"白居易「新豊折臂翁」","l":"tibet-nanzhao","x":"唐の雲南遠征の悲劇は、約50年後、白居易の詩に歌われた。白居易は、長安の東の新豊県で出会った88歳の老人の話を、こう記している。天宝の年に、雲南遠征のための兵の大募集があった。……"},{"id":"tibet-nanzhao-t5","k":"works","kj":"作品紹介","t":"吐蕃と南詔にまつわる作品","l":"tibet-nanzhao","x":"『天龍八部』（金庸の武侠小説、1963〜1966年連載）：主人公の一人段誉は、大理国の皇族という設定で、大理国の仏教文化や、吐蕃の国師なども登場する。何度もドラマ化された。文成公主"},{"id":"turks-uighur-t1","k":"trivia","kj":"こぼれ話","t":"ビザンツ帝国への使節","l":"turks-uighur","x":"突厥は、支配下のソグド人の商人たちの求めに応じて、中国から手に入れた絹を、ササン朝を通じて西方に売ろうとした。しかし、絹の交易を独占しようとするササン朝は、これを拒んだ。そこで56"},{"id":"turks-uighur-t2","k":"source","kj":"史料","t":"オルホン碑文が語る「中国」","l":"turks-uighur","x":"キュル・テギン碑文やビルゲ可汗碑文には、唐に支配された時代の屈辱と、唐への警戒が、繰り返し語られている。ベグ（貴族）となるべき男子らは、タブガチの民の奴隷となり、貴婦人となるべき娘"},{"id":"turks-uighur-t3","k":"view","kj":"視点を変える","t":"中央アジアの「トルコ化」","l":"turks-uighur","x":"ウイグルの西遷は、中央アジアの歴史を大きく変えた。それまで、タリム盆地のオアシス都市には、トハラ語やコータン語などのインド・ヨーロッパ系の言葉を話す人々や、イラン系のソグド人が多く"},{"id":"turks-uighur-t4","k":"works","kj":"作品紹介","t":"突厥・ウイグルにまつわる作品と言葉","l":"turks-uighur","x":"トルコ共和国と突厥：トルコ共和国では、突厥（ギョクテュルク、「天のトルコ」の意）が、トルコ民族の最初の国家としてたたえられ、オルホン碑文は「トルコ語の最古の記録」として重視されてい"},{"id":"umayyad-t1","k":"person","kj":"人物","t":"ムアーウィヤの「髪の毛」","l":"umayyad","x":"ムアーウィヤは、武力よりも、駆け引きと寛大さによって人々を従えることに長けた政治家として知られる。彼は、自らの政治のやり方を、次のように語ったと伝えられる。鞭で足りるところでは剣を"},{"id":"umayyad-t2","k":"trivia","kj":"こぼれ話","t":"書き換えられたカリフの名前","l":"umayyad","x":"岩のドームの内部の壁の上部には、全長約240mにも及ぶ帯状の碑文が、金色のモザイクで書かれている。その中には、「神は生みもせず、生まれもしない」（『クルアーン』第112章）、「マル"},{"id":"umayyad-t3","k":"trivia","kj":"こぼれ話","t":"金貨をめぐる皇帝とカリフの争い","l":"umayyad","x":"貨幣の改革の前、アブド・アルマリクは、一時、カリフ自身が剣を帯びて立つ姿を刻んだ金貨を発行していた。一方、ビザンツ皇帝ユスティニアノス2世は、692年ごろ、金貨の表に、初めてキリス"},{"id":"umayyad-t4","k":"trivia","kj":"こぼれ話","t":"「ターリクの山」と、船を焼いた将軍","l":"umayyad","x":"ターリクが軍を上陸させた岩山は、アラビア語で「ジャバル・ターリク」（ターリクの山）と呼ばれるようになった。これがなまって、現在の「ジブラルタル」という地名になった。伝説によれば、タ"},{"id":"umayyad-t5","k":"trivia","kj":"こぼれ話","t":"クサイル・アムラの「6人の王」","l":"umayyad","x":"8世紀前半に建てられたクサイル・アムラの浴場の壁には、狩りや音楽、踊り、裸の女性たちの姿などが、生き生きと描かれている。モスクには人の姿を描かなかったウマイヤ朝の王族たちも、私的な"},{"id":"umayyad-t6","k":"myth","kj":"俗説","t":"宴の席の虐殺と、逃れた王子","l":"umayyad","x":"アッバース家は、ウマイヤ家の人々を徹底的に追及した。伝承によれば、アッバース家の将軍は、パレスチナで、ウマイヤ家の約80人の人々に、安全を約束して宴会に招いた。そして、宴の最中に彼"},{"id":"umayyad-t7","k":"now","kj":"いま","t":"アーシューラーと現代","l":"umayyad","x":"カルバラーの悲劇は、シーア派の人々にとって、不正な権力に立ち向かい、殉教した者の物語として、現在まで語り継がれている。1979年のイラン革命の際にも、革命を指導した人々は、国王（シ"},{"id":"umayyad-t8","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"umayyad","x":"嶋田襄平『イスラム教史』（山川出版社）：ウマイヤ朝・アッバース朝の時代のイスラームの歴史を概説した本。ターズィエ（受難劇）：イランで演じられる、カルバラーの悲劇を題材とした伝統的な"},{"id":"vedic-t1","k":"source","kj":"史料","t":"ウィリアム＝ジョーンズの講演（1786年）","l":"vedic","x":"サンスクリット語は、その古さがどれほどであれ、驚くべき構造をもっている。ギリシア語より完全で、ラテン語より豊かで、そのどちらよりも精巧に洗練されている。しかも、この二つの言語と、動"},{"id":"vedic-t2","k":"confuse","kj":"混同注意","t":"似ている単語をくらべる","l":"vedic","x":"意味サンスクリット語アヴェスター語（古代イラン）ギリシア語ラテン語英語ドイツ語父ピタル（pitṛ）ピタル（pitar）パテール（patēr）パテル（pater）ファーザー（fath"},{"id":"vedic-t3","k":"debate","kj":"諸説あり","t":"アーリヤ人は「外から来た」のか","l":"vedic","x":"アーリヤ人が中央アジア方面からインドに移動してきたという考えは、言語学（インド＝ヨーロッパ語族の分布）や考古学、そして近年の古代DNAの研究によって、広く支持されている。前2千年紀"},{"id":"vedic-t4","k":"source","kj":"史料","t":"牛を求める戦い","l":"vedic","x":"『リグ＝ヴェーダ』の世界では、牛は最も大切な財産だった。戦争を意味する言葉の一つ「ガヴィシュティ」は、もともと「牛を求めること」という意味である。神々への祈りにも、牛と馬が繰り返し"},{"id":"vedic-t5","k":"trivia","kj":"こぼれ話","t":"十王戦争と「バーラト」","l":"vedic","x":"『リグ＝ヴェーダ』には、アーリヤ人どうしの部族の戦いの記録も残っている。バラタ族の王スダースが、10人の王の連合軍を、パンジャーブのパルシュニー川（現在のラーヴィー川）のほとりで打"},{"id":"vedic-t6","k":"source","kj":"史料","t":"原人プルシャの歌","l":"vedic","x":"『リグ＝ヴェーダ』の最も新しい層に属する賛歌の一つは、宇宙の始まりについて、神々が原初の巨人プルシャを犠牲として捧げ、その体から世界が生まれたと歌う。そして、四つの身分の起源を、次"},{"id":"vedic-t7","k":"confuse","kj":"混同注意","t":"ヴァルナ・ジャーティ・カースト","l":"vedic","x":"用語意味由来ヴァルナバラモン・クシャトリヤ・ヴァイシャ・シュードラの4つの身分の枠組みサンスクリット語で「色」ジャーティ職業や出身などで結びついた、生まれによって決まる集団。結婚や"},{"id":"vedic-t8","k":"now","kj":"いま","t":"現代インドとカースト","l":"vedic","x":"1950年に施行されたインド憲法は、カーストによる差別と「不可触民」制を禁止した。憲法の起草委員会の委員長を務めたのは、自らも「不可触民」とされた家に生まれたアンベードカルである。"},{"id":"vedic-t9","k":"source","kj":"史料","t":"「汝はそれなり」","l":"vedic","x":"ウパニシャッドの中でも有名なのが、父ウッダーラカが息子シュヴェータケートゥに教えを説く場面である。父は息子に、塩を水に入れさせ、翌朝、その塩を取り出すように言う。しかし塩は溶けてい"},{"id":"vikings-t1","k":"myth","kj":"俗説","t":"角のついたかぶと","l":"vikings","x":"ヴァイキングといえば、角のついたかぶとをかぶった姿を思い浮かべる人も多いだろう。しかし、ヴァイキングが角つきのかぶとをかぶって戦ったことを示す証拠は、まったく見つかっていない俗説。"},{"id":"vikings-t2","k":"source","kj":"史料","t":"アラブの使節が見たルーシ","l":"vikings","x":"921〜922年、アッバース朝のカリフの使節団の一員として、ヴォルガ川中流のブルガール人の国を訪れたイブン・ファドラーンは、そこで交易に来ていた「ルーシ」（スウェーデン系のノルマン"},{"id":"vikings-t3","k":"myth","kj":"俗説","t":"「北の人々の怒りから、われらを救いたまえ」","l":"vikings","x":"中世ヨーロッパの教会では、ヴァイキングの襲撃を恐れて、「主よ、北の人々（ノルマン人）の怒りから、われらを救いたまえ」と祈っていた、という話がよく知られている。しかし、この言葉そのも"},{"id":"vikings-t4","k":"myth","kj":"俗説","t":"足に口づけしなかった首領","l":"vikings","x":"11世紀初めのノルマンディーの歴史家サン・カンタンのデュドンは、ロロと王の協定の場面について、次のような話を伝えている。家臣となったしるしに、王の足に口づけするよう求められたロロは"},{"id":"vikings-t5","k":"myth","kj":"俗説","t":"パンを焦がした王","l":"vikings","x":"アルフレッドについては、次のような話が伝えられている。878年の初め、デーン人の奇襲を受けて追われたアルフレッドは、身分を隠して、沼地の農家に身を寄せた。農家の妻は、この男が王だと"},{"id":"vikings-t6","k":"myth","kj":"俗説","t":"波を止められなかった王","l":"vikings","x":"12世紀の歴史家ハンティンドンのヘンリーは、クヌートについて、次のような話を伝えている。権力の絶頂にあったクヌートは、海辺に王座を置かせ、満ちてくる潮に向かって、「わが足をぬらして"},{"id":"vikings-t7","k":"trivia","kj":"こぼれ話","t":"ブタとポーク","l":"vikings","x":"ノルマン＝コンクェストの後、イングランドの王侯貴族は、フランス語を話すノルマン人となった。宮廷や法廷、教会ではフランス語とラテン語が使われ、英語は庶民の言葉となった。そのため、英語"},{"id":"vikings-t8","k":"trivia","kj":"こぼれ話","t":"ハギア・ソフィアの落書き","l":"vikings","x":"イスタンブルのハギア・ソフィア大聖堂の2階の回廊の大理石の手すりには、ルーン文字で刻まれた落書きが残っている。読み取れるのは、「ハールヴダン」という名前と、「刻んだ」という言葉の一"},{"id":"vikings-t9","k":"trivia","kj":"こぼれ話","t":"ブルートゥースと青歯王","l":"vikings","x":"デンマークのイェリングには、10世紀の王ハーラル1世が、両親をしのんで立てた大きなルーン石碑が残っている。そこには、「デンマーク全土とノルウェーを手に入れ、デーン人をキリスト教徒に"},{"id":"vikings-t10","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"vikings","x":"幸村誠『ヴィンランド・サガ』（講談社、2005年〜）：11世紀初めの北欧とイングランドを舞台に、ヴァイキングの少年トルフィンの生涯を描いた漫画。クヌートやトルケルなど実在の人物が登"},{"id":"writing-t1","k":"view","kj":"視点を変える","t":"文字は、言葉とは別物である","l":"writing","x":"文字と言葉（言語）は、別のものである。同じ漢字が、中国語・日本語・朝鮮語・ベトナム語という系統の違う言葉を書くのに使われ、逆に、同じ言葉が、時代によって違う文字で書かれることもある"},{"id":"writing-t2","k":"confuse","kj":"混同注意","t":"主な古代文字の解読","l":"writing","x":"文字解読者年主な手がかりヒエログリフシャンポリオン（フランス）1822年ロゼッタ＝ストーン（ギリシア語との対訳）、コプト語楔形文字ローリンソン（イギリス）ら1850年代ベヒストゥー"},{"id":"writing-t3","k":"trivia","kj":"こぼれ話","t":"冷戦下のマヤ文字解読","l":"writing","x":"マヤ文字の解読は、20世紀の冷戦のもとで行われたドラマであった。16世紀、スペインの司教ランダは、マヤ文字の「アルファベット」を書き残していた。しかし、それはマヤの書記に、スペイン"},{"id":"writing-t4","k":"source","kj":"史料","t":"文字は忘れっぽさを生む――プラトンの警告","l":"writing","x":"文字が広まったことを、手放しで喜ばなかった人もいた。古代ギリシアの哲学者プラトンは、対話篇『パイドロス』の中で、師のソクラテスに、エジプトの古い伝説として次のような話を語らせている"},{"id":"writing-t5","k":"now","kj":"いま","t":"コンピュータの中の古代文字","l":"writing","x":"現在、世界中の文字をコンピュータで扱うための国際的な規格「ユニコード」には、160を超える文字体系が登録されている。その中には、楔形文字、ヒエログリフ、線文字B、フェニキア文字、甲"},{"id":"xiongnu-t1","k":"source","kj":"史料","t":"司馬遷が見た匈奴","l":"xiongnu","x":"匈奴は、家畜を追って移動し、……水と草を求めて移り住み、城郭や定住地、耕作の仕事はない。……子どもは羊に乗って弓を引き、鳥やネズミを射る。少し大きくなると狐や兎を射て、それを食料と"},{"id":"xiongnu-t2","k":"myth","kj":"俗説","t":"鳴鏑（めいてき）の矢","l":"xiongnu","x":"冒頓は、父の頭曼単于（とうまんぜんう）の太子であったが、父は、後妻の生んだ子を跡継ぎにしようとして、冒頓を西方の月氏に人質として送り、その上で月氏を攻めた。冒頓は、月氏の良馬を盗ん"},{"id":"xiongnu-t3","k":"confuse","kj":"混同注意","t":"遊牧国家と農耕国家","l":"xiongnu","x":"遊牧国家（匈奴）農耕国家（漢）生業羊・馬などの遊牧、狩猟穀物の栽培（定住農耕）住居移動式の天幕（フェルト製）城壁で囲まれた都市・村落社会部族連合。単于のもとに諸部族が結集皇帝と官僚"},{"id":"xiongnu-t4","k":"source","kj":"史料","t":"冒頓単于から呂后への手紙","l":"xiongnu","x":"高祖の死後、冒頓は、未亡人となった呂后に、次のような手紙を送った。孤独な君主である私は、沼地に生まれ、牛や馬の野に育った。何度も国境に来て、中国に遊びたいと願ってきた。陛下は独り身"},{"id":"xiongnu-t5","k":"source","kj":"史料","t":"漢を捨てた宦官・中行説","l":"xiongnu","x":"文帝の時代、匈奴に嫁ぐ公主の付き人として、宦官の中行説（ちゅうこうえつ）が匈奴に送られた。中行説は、行くことを嫌がったが無理に送られたため、匈奴に着くとそのまま単于の側近となり、漢"},{"id":"xiongnu-t6","k":"myth","kj":"俗説","t":"「匈奴未だ滅びず」","l":"xiongnu","x":"武帝は、霍去病のために立派な邸宅を建てて与えようとした。すると、霍去病は答えた。「匈奴いまだ滅びず、何ぞ家をもってなさんや（匈奴がまだ滅びていないのに、どうして家など持てましょうか"},{"id":"xiongnu-t7","k":"myth","kj":"俗説","t":"蘇武と雁の手紙","l":"xiongnu","x":"前100年、漢の使者として匈奴に赴いた蘇武は、匈奴の内紛に巻き込まれて捕らえられた。匈奴は、蘇武を降伏させようとしたが、蘇武は、穴蔵に閉じ込められても、雪と毛皮の毛を食べて生き延び"},{"id":"xiongnu-t8","k":"myth","kj":"俗説","t":"中国に来たローマ兵？","l":"xiongnu","x":"郅支単于の城を攻めた漢の軍の報告には、城の外で「魚の鱗のような陣形」をとる100人余りの兵士がいたと記されている。1950年代、アメリカの歴史学者ダブスは、これが、前53年のカルラ"},{"id":"xiongnu-t9","k":"source","kj":"史料","t":"王昭君","l":"xiongnu","x":"前33年、呼韓邪単于は再び長安を訪れ、漢の皇族の娘を妻に迎えたいと願った。元帝は、後宮の女性の一人、王昭君（おうしょうくん）を単于に嫁がせた。のちの時代の伝説によれば、後宮の女性た"},{"id":"xiongnu-t10","k":"now","kj":"いま","t":"2000年ぶりに見つかった「燕然山銘」","l":"xiongnu","x":"89年、北匈奴を破った竇憲は、モンゴル高原の燕然山に登り、勝利を記念する文章を岩に刻ませた。この文章を書いたのは、のちに『漢書』を著す歴史家の班固であった。この「燕然山銘」の文章は"},{"id":"xiongnu-t11","k":"debate","kj":"諸説あり","t":"匈奴はフン族になったのか","l":"xiongnu","x":"4世紀後半、ヨーロッパ東部に、フン人と呼ばれる遊牧民が突然現れ、ゲルマン人の大移動を引き起こした（→「ゲルマン人の大移動」の回）。18世紀のフランスの学者ド＝ギーニュは、このフン人"},{"id":"xiongnu-t12","k":"works","kj":"作品紹介","t":"この時代を描いた作品","l":"xiongnu","x":"中島敦『李陵』（1943年発表）：匈奴に降伏した将軍李陵、彼を弁護して宮刑を受けた司馬遷、そして匈奴の地で節を守り続けた蘇武の3人の生き方を描いた短編小説。漢文調の格調高い文体で知"},{"id":"zhou-t1","k":"source","kj":"史料","t":"「甲子の朝」――青銅器が証明した戦いの日","l":"zhou","x":"1976年、陝西省臨潼で、一つの青銅器が見つかった。器の内側に鋳込まれた銘文は、こう始まっている。武王、商を征す。唯れ甲子の朝なり。歳（木星）鼎（ただ）しくして、克く昏夙（一夜のう"},{"id":"zhou-t2","k":"source","kj":"史料","t":"「書を尽く信ずれば」――孟子の疑い","l":"zhou","x":"『尚書』の一篇（武成篇）は、牧野の戦いのすさまじさを「血流れて杵を漂わす」（流れた血で、臼をつく杵が浮かんで流れた）と描いていた。これに対して、戦国時代の儒家・孟子は、次のように言"},{"id":"zhou-t3","k":"confuse","kj":"混同注意","t":"周の封建制と、ヨーロッパの封建制","l":"zhou","x":"「封建制」という同じ言葉が、中国の周と、中世ヨーロッパの両方に使われるので、混同しやすい。中身はかなり違う。周の封建制中世ヨーロッパの封建制時代前11〜前8世紀ごろ（西周）9〜13"},{"id":"zhou-t4","k":"trivia","kj":"こぼれ話","t":"「中国」という言葉の最古の例","l":"zhou","x":"1963年、陝西省宝鶏で、農家の裏の崖から一つの青銅器（何尊）が見つかった。この器の内底には、周の成王の時代に、洛邑の建設について記した122字の銘文が鋳込まれていた。その中に、武"},{"id":"zhou-t5","k":"confuse","kj":"混同注意","t":"禅譲と放伐","l":"zhou","x":"方法内容伝説上の例禅譲天子が、徳のある人物に平和的に位を譲る堯 → 舜 → 禹放伐徳を失った君主を、武力で討って追放する殷の湯王が夏の桀王を討つ、周の武王が殷の紂王を討つのちの時代"},{"id":"zhou-t6","k":"source","kj":"史料","t":"周公の戒め――「殷を鑑とせよ」","l":"zhou","x":"天命が失われうるという考えは、王にとって脅しでもあった。周の初めの王たちは、殷が滅んだ理由を、酒におぼれて政治を怠ったことにあると考え、自らを強く戒めた。周の康王の時代の青銅器「大"},{"id":"zhou-t7","k":"myth","kj":"俗説","t":"笑わない后と烽火","l":"zhou","x":"西周の最後の王・幽王には、褒姒という美しい后がいた。しかし、褒姒はまったく笑わなかった。あるとき、幽王が敵の襲来を知らせる烽火（のろし）を上げさせると、諸侯たちがあわてて駆けつけた"}]);
